try:
    from scipy.signal import cwt, morlet2
except ImportError:
    # SciPy 1.15+ removed the deprecated cwt/morlet2 helpers. Keep the historical
    # S8 wavelet-coherence behavior available with a small compatible fallback.
    from scipy.signal import convolve as _s8_signal_convolve

    def morlet2(M, s, w=5.0):
        M = int(M)
        s = float(s)
        x = (np.arange(M, dtype=float) - (M - 1.0) / 2.0) / max(s, 1e-12)
        return (np.pi ** -0.25) * np.exp(1j * float(w) * x) * np.exp(-0.5 * x * x) / np.sqrt(max(s, 1e-12))

    def cwt(data, wavelet, widths, dtype=None, **kwargs):
        data = np.asarray(data)
        widths = np.asarray(widths)
        if dtype is None:
            try:
                probe = np.asarray(wavelet(1, widths[0], **kwargs)) if widths.size else np.asarray([0.0])
                dtype = np.complex128 if np.iscomplexobj(probe) else np.float64
            except Exception:
                dtype = np.complex128
        out = np.empty((len(widths), len(data)), dtype=dtype)
        for i, width in enumerate(widths):
            length = int(min(max(1, int(10 * float(width))), len(data)))
            wav = np.conj(np.asarray(wavelet(length, width, **kwargs))[::-1])
            out[i] = _s8_signal_convolve(data, wav, mode='same')
        return out
