# ---------- Utilities ----------

class StepProgress(QtWidgets.QProgressDialog):
    def __init__(self, title: str, maximum: int = 0, parent=None):
        super().__init__(title, None, 0, maximum, parent)
        self._s8_dead = False
        self.setWindowTitle(title)
        self.setWindowModality(Qt.WindowModality.ApplicationModal)
        # Keep the C++ dialog alive until callers explicitly close it.
        # Auto-close/auto-reset can delete/reset the wrapped Qt object while
        # long chunked worker loops still hold the Python wrapper.
        self.setAutoClose(False); self.setAutoReset(False); self.setCancelButton(None); self.setMinimumDuration(0)
        try:
            self.setAttribute(Qt.WA_DeleteOnClose, False)
        except Exception:
            pass
        if maximum == 0: self.setRange(0, 0)

    def _pump(self):
        try:
            app = QtWidgets.QApplication.instance()
            if app is not None:
                app.processEvents()
        except RuntimeError:
            self._s8_dead = True
        except Exception:
            pass

    def set_text(self, text: str):
        if getattr(self, '_s8_dead', False):
            return
        try:
            self.setLabelText(text)
        except RuntimeError:
            self._s8_dead = True
            return
        self._pump()

    def step(self, value: int = None):
        if getattr(self, '_s8_dead', False):
            return
        try:
            if self.maximum() == 0:
                self._pump()
                return
            if value is None:
                self.setValue(self.value() + 1)
            else:
                self.setValue(value)
        except RuntimeError:
            self._s8_dead = True
            return
        self._pump()

    def close(self):
        if getattr(self, '_s8_dead', False):
            return
        try:
            super().close()
        except RuntimeError:
            self._s8_dead = True
        except Exception:
            pass

def read_to_TZYX(img_path: Path):
    arr = tiff.memmap(str(img_path))
    if arr.ndim == 5:
        T, Z, C, Y, X = arr.shape
        arr = np.asarray(arr)[:, :, 0, ...] if C > 0 else np.asarray(arr).reshape(T, Z, Y, X)
    elif arr.ndim == 4:
        arr = np.asarray(arr)
    elif arr.ndim == 3:
        arr = np.asarray(arr)[:, None, ...]
    else:
        raise ValueError(f"Unsupported image dims: {arr.shape}")
    return arr

def _normalize_savgol_window(win_req: int, T: int) -> int:
    if T < 5: return 0
    max_odd = T - 1 if (T - 1) % 2 == 1 else T - 2
    max_odd = max(5, max_odd)
    w = win_req if win_req is not None else 49
    if w % 2 == 0: w += 1
    w = max(5, min(w, max_odd))
    return w

def filter_temporal_progress(TZYX, use_savgol: bool, win_req: int = None, do_bg_subtract: bool = True, parent=None):
    yval = TZYX
    in_dtype = yval.dtype
    T, Z, Y, X = yval.shape
    out = np.empty_like(yval)
    win = _normalize_savgol_window(int(win_req) if win_req is not None else 49, T)
    do_sg = use_savgol and (win >= 5)
    prog = StepProgress("Filtering (temporal)", maximum=Z, parent=parent)
    prog.set_text(f"Applying Savitzky–Golay (window={win}) across time (per Z slice)..." if do_sg else "Copying input (no temporal filter)...")
    for z in range(Z):
        if do_sg:
            out[:, z] = savgol_filter(yval[:, z], win, 3, axis=0, mode='mirror')
        else:
            out[:, z] = yval[:, z]
        prog.step(z+1)
    if do_bg_subtract:
        out = out - np.amin(out, axis=0)
    if np.issubdtype(in_dtype, np.integer):
        info = np.iinfo(in_dtype); out = np.clip(out, info.min, info.max).astype(in_dtype)
    else:
        out = out.astype(in_dtype, copy=False)
    prog.close()
    return out

def threshold_stack_progress(TZYX_filtered, method, use_gate=True, use_spatial=True, blur_sigma: float = 0.0,
                             manual_threshold: float = None, parent=None):
    T, Z, Y, X = TZYX_filtered.shape
    tau = float(blur_sigma) if use_spatial else 0.0
    yval = TZYX_filtered.astype(np.float32, copy=False)
    if use_gate:
        prog = StepProgress("Thresholding", parent=parent)
        prog.set_text("Applying noise gate...")
        mean_floor = np.mean(yval, axis=0)
        nf = np.clip(yval, a_min=0, a_max=mean_floor)
        rf = np.mean(nf, axis=0, dtype=np.float32)
        yval = yval - (rf * 1.2)[None, ...]; yval[yval < 0] = 0
        prog.close()
    blurred = gaussian(yval, sigma=(0, 0, tau, tau)) if tau > 0 else yval
    if method in ('Otsu', 'Yen', 'Triangle', 'Manual'):
        prog = StepProgress("Thresholding", parent=parent)
        flat = blurred.reshape(-1, Y, X)
        if method == 'Manual':
            thr = float(0.0 if manual_threshold is None else manual_threshold)
            prog.set_text(f"Applying manual global threshold ({thr:.4f})...")
        else:
            prog.set_text(f"Computing global threshold ({method})...")
            thr = (threshold_otsu(flat[:]) if method == 'Otsu'
                   else threshold_yen(flat[:]) if method == 'Yen'
                   else threshold_triangle(flat[:]))
        out = (flat > thr).reshape(T, Z, Y, X).astype(bool)
        prog.close(); return out
    elif method == 'Unet':
        if MODEL is None:
            raise RuntimeError("UNet model not loaded. Please ensure chatunet4.load_model is available.")
        prog = StepProgress("Thresholding (UNet)", maximum=T*Z, parent=parent)
        prog.set_text("Running UNet per (t,z) slice...")
        binary = np.zeros((T, Z, Y, X), dtype=bool)
        for t in range(T):
            for z in range(Z):
                frame = blurred[t, z]
                rgb = np.stack([frame] * 3, axis=-1) / 255.0
                tensor = torch.tensor(rgb).permute(2, 0, 1).unsqueeze(0).to(DEVICE)
                _, _, h, w = tensor.shape
                pad_h = (32 - h % 32) % 32; pad_w = (32 - w % 32) % 32
                padded = F_torch.pad(tensor, (0, pad_w, 0, pad_h))
                with torch.no_grad():
                    out = torch.sigmoid(MODEL(padded))
                    mask = (out > 0.5).float()[0, 0, :h, :w].cpu().numpy()
                binary[t, z] = mask.astype(bool)
                prog.step()
        prog.close(); return binary
    else:
        raise ValueError(f"Unknown threshold method '{method}'")

def compute_sites_from_time_sum(mask_bool):
    occ_zyx = mask_bool.any(axis=0)
    site_labels_zyx = label(occ_zyx, connectivity=1)
    return site_labels_zyx

def track_4d_progress(binary_TZYX, filtered_TZYX, site_labels_zyx=None, min_size=10, parent=None):
    busy = StepProgress("4D Labeling", parent=parent)
    busy.set_text("Labeling connected components in 4D (T,Z,Y,X)...")
    lab = label(binary_TZYX, connectivity=2); busy.close()
    if lab.max() == 0: return {}
    fg = lab > 0
    coords_all = np.argwhere(fg); labels_all = lab[fg]
    intens_all = filtered_TZYX[fg]
    uniq, inv = np.unique(labels_all, return_inverse=True)
    T, Z, Y, X = binary_TZYX.shape
    sites = {}
    prog = StepProgress("Assembling ROIs", maximum=len(uniq), parent=parent)
    prog.set_text("Collecting ROI metrics...")
    for k, lbl in enumerate(uniq):
        sel = (inv == k); coords = coords_all[sel]
        if coords.shape[0] < min_size:
            prog.step(k+1); continue
        intens = intens_all[sel].astype(float)
        tvals = coords[:, 0].astype(int)
        times = np.unique(tvals)
        counts = np.bincount(tvals, minlength=T); active = counts > 0
        areas = counts[active].astype(float)
        sums_int = np.bincount(tvals, weights=intens, minlength=T)
        meanint_full = np.zeros(T, dtype=float); nz_time = counts > 0
        meanint_full[nz_time] = sums_int[nz_time] / counts[nz_time]
        amps = meanint_full[active]
        if coords.size == 0:
            cents_full = np.empty((0, 4), dtype=float)
        else:
            ts = coords[:, 0].astype(int); zs = coords[:, 1].astype(float)
            ys = coords[:, 2].astype(float); xs = coords[:, 3].astype(float)
            times_u = np.unique(ts); cents_full = []
            for t in times_u:
                sel_t = (ts == t)
                zc = zs[sel_t].mean(); yc = ys[sel_t].mean(); xc = xs[sel_t].mean()
                cents_full.append([t, zc, yc, xc])
            cents_full = np.array(cents_full, dtype=float) if len(cents_full) else np.empty((0, 4), dtype=float)
        area_zt = np.zeros((T, Z), dtype=np.int32); sumint_zt = np.zeros((T, Z), dtype=np.float64)
        if coords.size:
            ts = coords[:,0].astype(int); zs = coords[:,1].astype(int)
            for t, z in zip(ts, zs): area_zt[t, z] += 1
            vals = filtered_TZYX[coords[:,0], coords[:,1], coords[:,2], coords[:,3]].astype(np.float64)
            for (t, z, v) in zip(ts, zs, vals): sumint_zt[t, z] += v
        meanint_zt = np.zeros_like(sumint_zt, dtype=np.float32); nz = area_zt > 0
        meanint_zt[nz] = (sumint_zt[nz] / area_zt[nz]).astype(np.float32)
        peak_z_t = np.argmax(area_zt, axis=1) if area_zt.size else np.full(T, -1, dtype=int)
        area_peak2d_t = area_zt[np.arange(T), peak_z_t] if area_zt.size else np.zeros(T, dtype=int)
        meanint_peak2d_t = meanint_zt[np.arange(T), peak_z_t] if area_zt.size else np.zeros(T, dtype=float)
        centroid_peak2d_tyx = np.full((T, 3), np.nan, dtype=np.float32)
        if area_zt.size:
            for t in range(T):
                if area_peak2d_t[t] > 0:
                    mask_tz = (coords[:,0] == t) & (coords[:,1] == peak_z_t[t])
                    if mask_tz.any():
                        y = coords[mask_tz, 2].mean(); x = coords[mask_tz, 3].mean()
                        centroid_peak2d_tyx[t] = (t, y, x)
        bbox = {
            't_min': int(coords[:, 0].min()), 't_max': int(coords[:, 0].max()),
            'z_min': int(coords[:, 1].min()), 'z_max': int(coords[:, 1].max()),
            'y_min': int(coords[:, 2].min()), 'y_max': int(coords[:, 2].max()),
            'x_min': int(coords[:, 3].min()), 'x_max': int(coords[:, 3].max()),
        }
        lifetime = len(times)
        duty_cycle = float(lifetime) / float(T) if T > 0 else 0.0
        n_active_runs = 0
        if len(times) > 0:
            n_active_runs = 1
            for i in range(1, len(times)):
                if times[i] != times[i-1] + 1: n_active_runs += 1
        first_time = int(times.min()) if lifetime else 0
        amp_range = float(amps.max()-amps.min()) if amps.size else 0.0
        cents_y = cents_full[:, 2] if cents_full.size else np.array([])
        cents_x = cents_full[:, 3] if cents_full.size else np.array([])
        first_centroid = np.array([first_time, cents_y[0] if cents_y.size else 0.0, cents_x[0] if cents_x.size else 0.0])
        site_label = 0; site_overlap_counts = {}
        if site_labels_zyx is not None and coords.size:
            zyx = coords[:, 1:4]
            site_ids = site_labels_zyx[zyx[:, 0], zyx[:, 1], zyx[:, 2]]
            unique, counts_arr = np.unique(site_ids[site_ids > 0], return_counts=True)
            site_overlap_counts = {int(u): int(c) for u, c in zip(unique, counts_arr)}
            if len(unique): site_label = int(unique[np.argmax(counts_arr)])
        times_active = cents_full[:, 0].astype(int) if cents_full.size else np.array([], dtype=int)
        cents_legacy = np.column_stack([times_active, cents_y, cents_x]) if cents_full.size else np.zeros((0, 3), dtype=float)
        meta = {
            'T': int(T), 'Z': int(Z),
            'area_t': counts.astype(int),
            'meanint_t': meanint_full.astype(float),
            'centroid_tzyx': cents_full.astype(float),
            'lifetime_frames': int(lifetime),
            'duty_cycle': float(duty_cycle),
            'n_active_runs': int(n_active_runs),
            'bbox': bbox,
            'peak_z_t': peak_z_t.astype(int),
            'area_peak2d_t': area_peak2d_t.astype(int),
            'meanint_peak2d_t': meanint_peak2d_t.astype(float),
            'centroid_peak2d_tyx': centroid_peak2d_tyx.astype(float),
            'has_centroids_zt': True,
            'site_label': int(site_label),
            'site_overlap_counts': site_overlap_counts
        }
        sites[int(lbl)] = np.array([
            areas, areas.max() if areas.size else 0.0, cents_legacy, lifetime, amps, amp_range,
            first_time, first_centroid, coords, np.array([False, False]),
            np.array([times, areas], dtype=object),
            np.diff(areas) if areas.size > 1 else np.array([0]),
            False, meta,
            area_zt.astype(np.int32), meanint_zt.astype(np.float32),
            np.full((T, Z), np.nan, dtype=np.float32), np.full((T, Z), np.nan, dtype=np.float32)
        ], dtype=object)
        prog.step(k+1)
    prog.close()
    return sites

def build_points_from_coords(sites, T, Z, Y, X, max_points_per_roi=3000):
    pts = []; roi_ids = []
    iterable = sites.items() if hasattr(sites, "items") else enumerate(sites)
    for roi_key, arr in iterable:
        try: coords = arr[8] if len(arr) > 8 else None
        except Exception: coords = None
        if coords is None or np.size(coords) == 0: continue
        c = np.asarray(coords)
        if c.ndim == 1:
            if c.size % 4 != 0: continue
            c = c.reshape(-1, 4)
        elif c.shape[1] < 4:
            continue
        else:
            c = c[:, :4]
        t = c[:, 0].astype(int); z = c[:, 1].astype(float); y = c[:, 2].astype(float); x = c[:, 3].astype(float)
        good = (t >= 0) & (t < T) & np.isfinite(z) & np.isfinite(y) & np.isfinite(x)
        c = c[good]
        if c.size == 0: continue
        n = len(c)
        if n > max_points_per_roi:
            idx = np.linspace(0, n - 1, max_points_per_roi).astype(int)
            c = c[idx]
        t = c[:, 0].astype(int)
        z = np.clip(c[:, 1].astype(int), 0, max(Z - 1, 0))
        y = np.clip(c[:, 2].astype(int), 0, max(Y - 1, 0))
        x = np.clip(c[:, 3].astype(int), 0, max(X - 1, 0))
        pts.extend(np.stack([t, z, y, x], axis=1))
        try: rid = int(roi_key)
        except Exception: rid = len(roi_ids)
        roi_ids.extend([rid] * len(t))
    if not pts: return np.zeros((0, 4), dtype=float), {"roi_id": np.array([], dtype=int)}
    pts = np.asarray(pts, dtype=float); props = {"roi_id": np.asarray(roi_ids, dtype=int)}
    return pts, props

# ---------- Coordination / Velocity helpers ----------

def _collect_metrics(rois: dict):
    ids, lifetime, duty, max_area, amp_range, peak_ff0, n_runs, first_t, site = [], [], [], [], [], [], [], [], []
    for rid, arr in rois.items():
        meta = arr[13]
        ids.append(int(rid)); lifetime.append(int(meta.get('lifetime_frames', 0)))
        duty.append(float(meta.get('duty_cycle', 0.0))); n_runs.append(int(meta.get('n_active_runs', 0)))
        site.append(int(meta.get('site_label', 0)))
        max_area.append(float(arr[1]) if arr[1] is not None else 0.0)
        amp_range.append(float(meta.get('ff0_range', arr[5] if arr[5] is not None else 0.0)))
        _pk = meta.get('peak_ff0', meta.get('ff0_max', arr[5] if arr[5] is not None else np.nan))
        try: peak_ff0.append(float(_pk))
        except Exception: peak_ff0.append(np.nan)
        first_t.append(int(arr[6]) if arr[6] is not None else 0)
    return {
        'roi_id': np.array(ids, dtype=int),
        'lifetime': np.array(lifetime, dtype=int),
        'duty_cycle': np.array(duty, dtype=float),
        'max_area': np.array(max_area, dtype=float),
        'amp_range': np.array(amp_range, dtype=float),
        'peak_ff0': np.array(peak_ff0, dtype=float),
        'n_active_runs': np.array(n_runs, dtype=int),
        'first_time': np.array(first_t, dtype=int),
        'site_label': np.array(site, dtype=int),
    }

def compute_amp_series_dict(sites: dict, T: int, img_amp=None):
    out = {}
    for rid, arr in sites.items():
        meta = arr[13] if len(arr) > 13 else {}
        mt = meta.get('meanint_t', None)
        if (img_amp is None) and (mt is not None) and (len(mt) == T):
            out[int(rid)] = np.asarray(mt, dtype=float)
        else:
            coords = arr[8] if len(arr) > 8 else None
            if coords is None or np.size(coords) == 0 or img_amp is None:
                out[int(rid)] = np.zeros(T, dtype=float)
            else:
                c = np.asarray(coords).reshape(-1, 4)
                t = c[:, 0].astype(int); z = c[:, 1].astype(int); y = c[:, 2].astype(int); x = c[:, 3].astype(int)
                good = (t>=0)&(t<T)&(z>=0)&(z<img_amp.shape[1])&(y>=0)&(y<img_amp.shape[2])&(x>=0)&(x<img_amp.shape[3])
                t = t[good]; z=z[good]; y=y[good]; x=x[good]
                vals = img_amp[t, z, y, x].astype(float)
                sums = np.bincount(t, weights=vals, minlength=T)
                counts = np.bincount(t, minlength=T).astype(float)
                series = np.zeros(T, float); nz = counts>0; series[nz] = sums[nz]/counts[nz]
                out[int(rid)] = series
    return out

def wavelet_coherence_R2(x: np.ndarray, y: np.ndarray, widths=None, w: float = 6.0,
                         time_smooth:int=7, freq_smooth:int=5) -> np.ndarray:
    x = np.asarray(x, float); y = np.asarray(y, float)
    if widths is None:
        maxw = max(8, min(len(x)//2, 128))
        widths = np.arange(2, maxw, dtype=float)
    Wx = cwt(x - np.nanmean(x), morlet2, widths, w=w)
    Wy = cwt(y - np.nanmean(y), morlet2, widths, w=w)
    Wxy = Wx * np.conj(Wy)
    Sxy = uniform_filter(np.abs(Wxy), size=(freq_smooth, time_smooth))
    Sxx = uniform_filter(np.abs(Wx)**2, size=(freq_smooth, time_smooth))
    Syy = uniform_filter(np.abs(Wy)**2, size=(freq_smooth, time_smooth))
    denom = Sxx * Syy + 1e-12
    R2 = (np.abs(Sxy)**2) / denom
    R2 = np.clip(R2, 0, 1)
    return R2

def band_mean_from_R2(R2: np.ndarray, widths: np.ndarray, period_frames_range=(20, 200)):
    if R2.size == 0: return np.nan
    periods = widths
    lo, hi = period_frames_range
    sel = (periods >= lo) & (periods <= hi)
    if not np.any(sel): sel = slice(None)
    return float(np.nanmean(R2[sel]))

def estimate_propagation_velocity(sites: dict, T:int):
    xs=[]; ys=[]; ts=[]
    for rid, arr in sites.items():
        meta = arr[13] if len(arr)>13 else {}
        area_t = np.asarray(meta.get('area_t', []), dtype=float)
        if area_t.size != T:
            buf = np.zeros(T, int); buf[:min(T, area_t.size)] = area_t[:min(T, area_t.size)]; area_t = buf
        thr = max(5, int(0.10 * np.max(area_t)))
        onset_idx = int(np.argmax(area_t >= thr)) if np.any(area_t >= thr) else None
        if onset_idx is None or onset_idx<=0: continue
        cents = np.asarray(meta.get('centroid_peak2d_tyx', np.full((T,3), np.nan)))
        if cents.shape != (T,3): continue
        yx = cents[onset_idx, 1:3]
        if np.any(~np.isfinite(yx)):
            valid = np.where(np.isfinite(cents[:,1]) & np.isfinite(cents[:,2]))[0]
            if valid.size==0: continue
            yx = cents[valid[0], 1:3]; onset_idx = int(valid[0])
        ys.append(float(yx[0])); xs.append(float(yx[1])); ts.append(float(onset_idx))
    xs = np.asarray(xs); ys = np.asarray(ys); ts = np.asarray(ts)
    result = {'speed_frames_per_pixel': np.nan, 'angle_radians': np.nan,
              'coeffs': (np.nan, np.nan, np.nan), 'n_points': int(len(ts)),
              'table': {'x': xs, 'y': ys, 't_onset': ts}}
    if len(ts) < 3: return result
    A = np.column_stack([xs, ys, np.ones_like(xs)])
    coeffs, *_ = np.linalg.lstsq(A, ts, rcond=None)
    a, b, c = coeffs
    speed = 1.0 / max(1e-9, math.hypot(a, b))
    angle = math.atan2(b, a)
    result.update({'speed_frames_per_pixel': float(speed), 'angle_radians': float(angle),
                   'coeffs': (float(a), float(b), float(c))})
    return result

# ---------- Plotting helpers (unchanged from previous stable) ----------

def _strip(ax, y, title, ylabel):
    if len(y) == 0:
        ax.text(0.5, 0.5, 'No data', ha='center', va='center'); ax.set_axis_off(); return
    x = np.ones_like(y, dtype=float)
    jitter = (np.random.rand(len(y)) - 0.5) * 0.2
    ax.scatter(x + jitter, y, s=10, alpha=0.7)
    ax.set_xticks([]); ax.set_title(title); ax.set_ylabel(ylabel)

def _hist(ax, y, title, xlabel, bins=30):
    if len(y) == 0:
        ax.text(0.5, 0.5, 'No data', ha='center', va='center'); ax.set_axis_off(); return
    ax.hist(y, bins=bins); ax.set_title(title); ax.set_xlabel(xlabel); ax.set_ylabel('count')

def _plot_overview(pdf, meta, metrics):
    fig = plt.figure(figsize=(10, 6), dpi=160); fig.suptitle("Hypervolume Summary", fontsize=14)
    gs = fig.add_gridspec(2, 3, height_ratios=[1, 2])
    ax0 = fig.add_subplot(gs[0, :]); ax0.axis('off')
    threshold_text = f"Threshold: {meta.get('threshold_method')}"
    if str(meta.get('threshold_method', '')).lower() == 'manual':
        threshold_text += f" ({meta.get('manual_threshold', 0.0):.4f})"
    text = (
        f"Total hypervolumes (ROIs): {len(metrics['roi_id'])}\n"
        f"Shape (T,Z,Y,X): {meta.get('shape_TZYX', None)}\n"
        f"{threshold_text} | "
        f"export={meta.get('export_filter_desc', 'All ROIs')}  "
        f"spatial={meta.get('use_spatial')} (σ={meta.get('blur_sigma', 0.0)})  "
        f"savgol={meta.get('use_savgol')} (win={meta.get('savgol_window', 'auto')})  "
        f"gate={meta.get('use_gate')}  "
        f"bg_subtract={meta.get('bg_subtract', True)}"
    )
    ax0.text(0.01, 0.8, text, va='top', ha='left', family='monospace')
    _hist(fig.add_subplot(gs[1,0]), metrics['lifetime'], 'Lifetime (frames)', 'frames')
    _hist(fig.add_subplot(gs[1,1]), metrics['max_area'], 'Max volume (voxels)', 'voxels')
    _hist(fig.add_subplot(gs[1,2]), metrics['amp_range'], 'Amplitude range', 'intensity')
    pdf.savefig(fig); plt.close(fig)

def _plot_strips(pdf, metrics):
    fig = plt.figure(figsize=(12, 8), dpi=160); fig.suptitle("Parameter Strip Charts", fontsize=14)
    gs = fig.add_gridspec(2, 3)
    _strip(fig.add_subplot(gs[0,0]), metrics['lifetime'], 'Lifetime', 'frames')
    _strip(fig.add_subplot(gs[0,1]), metrics['duty_cycle'], 'Duty Cycle', 'fraction')
    _strip(fig.add_subplot(gs[0,2]), metrics['max_area'], 'Max Volume', 'voxels')
    _strip(fig.add_subplot(gs[1,0]), metrics['amp_range'], 'Amplitude Range', 'intensity')
    _strip(fig.add_subplot(gs[1,1]), metrics['n_active_runs'], 'Active Runs', 'count')
    _strip(fig.add_subplot(gs[1,2]), metrics['first_time'], 'First Active Frame', 'frame')
    pdf.savefig(fig); plt.close(fig)

def _plot_multi_series(pdf, rois, T):
    fig = plt.figure(figsize=(12, 6), dpi=160)
    ax = fig.add_subplot(1, 1, 1)
    series = []; site_labels = []
    for rid, arr in sorted(rois.items(), key=lambda kv: int(kv[0])):
        meta = arr[13]; area_t = np.array(meta.get('area_t', []), dtype=float)
        if area_t.size == 0: continue
        series.append(area_t); site_labels.append(int(meta.get('site_label', 0)))
    if not series:
        ax.text(0.5, 0.5, 'No ROI time series', ha='center', va='center'); ax.set_axis_off()
    else:
        maxT = max(T, max(s.size for s in series)); xs = np.arange(maxT)
        uniq_sites = np.unique(site_labels)
        cmap = plt.get_cmap('tab20')
        site_color = {s: cmap(i % cmap.N) for i, s in enumerate(uniq_sites)}
        for s, lab in zip(series, site_labels):
            y = np.zeros(maxT, dtype=float); y[:s.size] = s
            ax.plot(xs, y, lw=0.8, alpha=0.5, color=site_color.get(lab, 'k'))
        ax.set_title('All ROIs — Volume (voxels) over time (colored by site)')
        ax.set_xlabel('time (frame)'); ax.set_ylabel('voxels')
        if len(uniq_sites) <= 12:
            handles = [plt.Line2D([0], [0], color=site_color[s], lw=2) for s in uniq_sites]
            labels = [f"site {int(s)}" for s in uniq_sites]
            ax.legend(handles, labels, loc='upper right', fontsize=8, framealpha=0.7)
    pdf.savefig(fig); plt.close(fig)

def _plot_coherence_pdf(pdf, coord_dict, T):
    if not coord_dict or 'band_mean' not in coord_dict: return
    band_vals = np.asarray([v for v in coord_dict['band_mean'].values() if np.isfinite(v)], float)
    fig = plt.figure(figsize=(10,4), dpi=160); ax = fig.add_subplot(1,1,1)
    if band_vals.size:
        ax.hist(band_vals, bins=30)
        ax.set_title(f"Wavelet Coherence — band mean (period {coord_dict.get('band_period_frames', (20,200))} frames)")
        ax.set_xlabel("R^2"); ax.set_ylabel("ROI count")
    else:
        ax.text(0.5,0.5,"No coherence values", ha='center', va='center'); ax.axis('off')
    pdf.savefig(fig); plt.close(fig)

def _plot_velocity_pdf(pdf, vel_dict):
    if not vel_dict: return
    fig = plt.figure(figsize=(10,4), dpi=160)
    gs = fig.add_gridspec(1,2); ax0 = fig.add_subplot(gs[0,0]); ax1 = fig.add_subplot(gs[0,1])
    ax0.set_title("Propagation direction")
    ax0.set_xlim(-1,1); ax0.set_ylim(-1,1); ax0.set_aspect('equal')
    th = float(vel_dict.get('angle_radians', np.nan))
    if np.isfinite(th):
        ax0.arrow(0,0, np.cos(th), np.sin(th), head_width=0.1, length_includes_head=True)
        ax0.text(-0.95,0.9, f"angle = {th:.2f} rad", ha='left', va='top')
    else:
        ax0.text(0.5,0.5,"N/A", ha='center', va='center'); ax0.axis('off')
    sp = float(vel_dict.get('speed_frames_per_pixel', np.nan))
    npts = int(vel_dict.get('n_points', 0))
    ax1.axis('off')
    ax1.text(0.02, 0.9, f"Estimated speed: {sp:.3f} frames/pixel\nSamples used: {npts}", ha='left', va='top', family='monospace')
    pdf.savefig(fig); plt.close(fig)

def _collect_start_end_displacements(rois: dict, T: int):
    import numpy as _np
    x0s=[]; y0s=[]; dxs=[]; dys=[]; ids=[]
    for rid, arr in rois.items():
        meta = arr[13] if len(arr) > 13 else {}
        cents = meta.get('centroid_peak2d_tyx', None)
        if cents is None:
            cfull = meta.get('centroid_tzyx', None)
            if cfull is not None:
                expanded = _np.full((T,3), _np.nan, dtype=float)
                for row in cfull:
                    tt = int(row[0])
                    if 0 <= tt < T:
                        expanded[tt,0]=tt; expanded[tt,1]=row[2]; expanded[tt,2]=row[3]
                cents = expanded
        if cents is None:
            continue
        cents = _np.asarray(cents, dtype=float)
        if cents.ndim!=2 or cents.shape[1]!=3:
            continue
        valid = _np.isfinite(cents[:,1]) & _np.isfinite(cents[:,2])
        if not _np.any(valid):
            continue
        idxs = _np.where(valid)[0]
        i0 = int(idxs[0]); i1 = int(idxs[-1])
        y0 = float(cents[i0,1]); x0 = float(cents[i0,2])
        y1 = float(cents[i1,1]); x1 = float(cents[i1,2])
        x0s.append(x0); y0s.append(y0); dxs.append(x1-x0); dys.append(y1-y0); ids.append(int(rid))
    import numpy as _np2
    return _np2.asarray(x0s), _np2.asarray(y0s), _np2.asarray(dxs), _np2.asarray(dys), ids

def _collect_start_end_displacements3d(rois: dict, T: int):
    import numpy as _np
    x0s=[]; y0s=[]; z0s=[]; dxs=[]; dys=[]; dzs=[]; ids=[]
    for rid, arr in rois.items():
        meta = arr[13] if len(arr) > 13 else {}
        cfull = meta.get('centroid_tzyx', None)
        cents2d = meta.get('centroid_peak2d_tyx', None)
        peakz = meta.get('peak_z_t', None)

        if cfull is not None:
            z_arr = _np.full(T, _np.nan); y_arr = _np.full(T, _np.nan); x_arr = _np.full(T, _np.nan)
            for row in cfull:
                tt = int(row[0])
                if 0 <= tt < T:
                    z_arr[tt]=float(row[1]); y_arr[tt]=float(row[2]); x_arr[tt]=float(row[3])
        elif cents2d is not None and peakz is not None:
            cents2d = _np.asarray(cents2d, dtype=float); peakz = _np.asarray(peakz, dtype=float)
            if cents2d.ndim==2 and cents2d.shape[1]==3:
                if cents2d.shape[0] != T or not _np.all(_np.isfinite(cents2d[:,0])):
                    expanded = _np.full((T,3), _np.nan, dtype=float)
                    for row in cents2d:
                        tt = int(row[0])
                        if 0 <= tt < T:
                            expanded[tt] = row
                    cents2d = expanded
                y_arr = cents2d[:,1].astype(float); x_arr = cents2d[:,2].astype(float)
                if peakz.size != T:
                    tmp = _np.full(T, _np.nan, dtype=float); tmp[:min(T,peakz.size)] = peakz[:min(T,peakz.size)]
                    peakz = tmp
                z_arr = peakz.astype(float)
            else:
                continue
        else:
            continue

        valid = _np.isfinite(x_arr) & _np.isfinite(y_arr) & _np.isfinite(z_arr)
        if not _np.any(valid):
            continue
        idxs = _np.where(valid)[0]
        i0 = int(idxs[0]); i1 = int(idxs[-1])
        x0=float(x_arr[i0]); y0=float(y_arr[i0]); z0=float(z_arr[i0])
        x1=float(x_arr[i1]); y1=float(y_arr[i1]); z1=float(z_arr[i1])
        dx=x1-x0; dy=y1-y0; dz=z1-z0
        x0s.append(x0); y0s.append(y0); z0s.append(z0); dxs.append(dx); dys.append(dy); dzs.append(dz); ids.append(int(rid))
    import numpy as _np2
    return _np2.asarray(x0s), _np2.asarray(y0s), _np2.asarray(z0s), _np2.asarray(dxs), _np2.asarray(dys), _np2.asarray(dzs), ids

def _plot_centroid_displacements_pdf(pdf, rois: dict, meta: dict):
    import numpy as _np
    import matplotlib.pyplot as plt
    T, Z, Y, X = [int(v) for v in meta.get('shape_TZYX', (0,0,0,0))]
    fig = plt.figure(figsize=(8,8)); ax = fig.add_subplot(111)
    ax.set_title("ROI centroid displacement (start→end)")
    ax.set_xlim(0, X); ax.set_ylim(Y, 0); ax.set_xlabel("X (px)"); ax.set_ylabel("Y (px, down)")
    x0,y0,dx,dy,ids = _collect_start_end_displacements(rois, T)
    if x0.size>0:
        ax.quiver(x0, y0, dx, dy, angles='xy', scale_units='xy', scale=1, width=0.002, headwidth=4, headlength=6, color='black')
        if len(ids) <= 40:
            for i, rid in enumerate(ids):
                ax.text(x0[i], y0[i], str(rid), fontsize=6, ha='left', va='bottom')
    else:
        ax.text(0.5,0.5,"No valid centroids found", ha='center', va='center', transform=ax.transAxes)
    pdf.savefig(fig); plt.close(fig)

def _plot_centroid_displacements3d_pdf(pdf, rois: dict, meta: dict):
    import numpy as _np
    import matplotlib.pyplot as plt
    T, Z, Y, X = [int(v) for v in meta.get('shape_TZYX', (0,0,0,0))]
    x0,y0,z0,dx,dy,dz,ids = _collect_start_end_displacements3d(rois, T)
    fig = plt.figure(figsize=(11, 6.5))
    gs = fig.add_gridspec(1, 2, width_ratios=[1, 1], wspace=0.3)
    ax_xz = fig.add_subplot(gs[0, 0])
    ax_yz = fig.add_subplot(gs[0, 1])
    fig.suptitle("ROI centroid displacement — orthographic projections (XZ & YZ)", fontsize=12)

    def quiver2d(ax, x, y, u, v, xlim, ylim, title, xlabel, ylabel, ids):
        ax.set_title(title, fontsize=10)
        ax.set_xlim(*xlim); ax.set_ylim(*ylim)
        ax.set_xlabel(xlabel); ax.set_ylabel(ylabel)
        if x.size>0:
            ax.quiver(x, y, u, v, angles='xy', scale_units='xy', scale=1,
                      width=0.0018, headwidth=5, headlength=7, headaxislength=6, color='black')
            if len(ids) <= 40:
                for i, rid in enumerate(ids):
                    ax.text(x[i], y[i], str(rid), fontsize=6, ha='left', va='bottom')
        else:
            ax.text(0.5,0.5,"No valid displacements", ha='center', va='center', transform=ax.transAxes)
        ax.grid(alpha=0.15)
        for spine in ax.spines.values():
            spine.set_alpha(0.4)

    quiver2d(ax_xz, x0, z0, dx, dz, (0, X), (0, Z), "XZ projection", "X (px)", "Z (slices)", ids)
    quiver2d(ax_yz, y0, z0, dy, dz, (Y, 0), (0, Z), "YZ projection (Y down in XY)", "Y (px)", "Z (slices)", ids)
    pdf.savefig(fig); plt.close(fig)

def _compute_displacements2d_map(rois: dict, T: int):
    import numpy as _np, math as _math
    out = {}
    for rid, arr in rois.items():
        meta = arr[13] if len(arr) > 13 else {}
        cents = meta.get('centroid_peak2d_tyx', None)
        if cents is None:
            cfull = meta.get('centroid_tzyx', None)
            if cfull is not None:
                expanded = _np.full((T,3), _np.nan, dtype=float)
                for row in cfull:
                    tt = int(row[0])
                    if 0 <= tt < T:
                        expanded[tt,0]=tt; expanded[tt,1]=row[2]; expanded[tt,2]=row[3]
                cents = expanded
        if cents is None: continue
        cents = _np.asarray(cents, dtype=float)
        if cents.ndim!=2 or cents.shape[1]!=3: continue
        valid = _np.isfinite(cents[:,1]) & _np.isfinite(cents[:,2])
        if not _np.any(valid): continue
        idxs = _np.where(valid)[0]; i0=int(idxs[0]); i1=int(idxs[-1])
        y0=float(cents[i0,1]); x0=float(cents[i0,2]); y1=float(cents[i1,1]); x1=float(cents[i1,2])
        dx=x1-x0; dy=y1-y0
        length=float(_np.hypot(dx,dy)); angle=float(_math.atan2(dy,dx))
        out[int(rid)] = dict(x0=x0,y0=y0,t_first=i0,x1=x1,y1=y1,t_last=i1,dx=dx,dy=dy,length=length,angle_rad=angle)
    return out

def _compute_displacements3d_map(rois: dict, T: int):
    import numpy as _np, math as _math
    out = {}
    for rid, arr in rois.items():
        meta = arr[13] if len(arr) > 13 else {}
        cfull = meta.get('centroid_tzyx', None)
        cents2d = meta.get('centroid_peak2d_tyx', None)
        peakz = meta.get('peak_z_t', None)
        if cfull is not None:
            z_arr = _np.full(T,_np.nan); y_arr=_np.full(T,_np.nan); x_arr=_np.full(T,_np.nan)
            for row in cfull:
                tt=int(row[0]); 
                if 0 <= tt < T:
                    z_arr[tt]=float(row[1]); y_arr[tt]=float(row[2]); x_arr[tt]=float(row[3])
        elif cents2d is not None and peakz is not None:
            cents2d=_np.asarray(cents2d,dtype=float); peakz=_np.asarray(peakz,dtype=float)
            if cents2d.ndim==2 and cents2d.shape[1]==3:
                if cents2d.shape[0]!=T or not _np.all(_np.isfinite(cents2d[:,0])):
                    expanded=_np.full((T,3),_np.nan,dtype=float)
                    for row in cents2d:
                        tt=int(row[0])
                        if 0<=tt<T: expanded[tt]=row
                    cents2d=expanded
                x_arr=cents2d[:,2].astype(float); y_arr=cents2d[:,1].astype(float)
                if peakz.size!=T:
                    tmp=_np.full(T,_np.nan,dtype=float); tmp[:min(T,peakz.size)]=peakz[:min(T,peakz.size)]
                    peakz=tmp
                z_arr=peakz.astype(float)
            else:
                continue
        else:
            continue
        valid=_np.isfinite(x_arr)&_np.isfinite(y_arr)&_np.isfinite(z_arr)
        if not _np.any(valid): continue
        idxs=_np.where(valid)[0]; i0=int(idxs[0]); i1=int(idxs[-1])
        x0=float(x_arr[i0]); y0=float(y_arr[i0]); z0=float(z_arr[i0])
        x1=float(x_arr[i1]); y1=float(y_arr[i1]); z1=float(z_arr[i1])
        dx=x1-x0; dy=y1-y0; dz=z1-z0
        length3d=float(_np.sqrt(dx*dx+dy*dy+dz*dz))
        theta_xy=float(_math.atan2(dy,dx)); r_xy=float(_np.hypot(dx,dy))
        phi_z=float(_math.atan2(dz,r_xy))
        out[int(rid)]=dict(x0=x0,y0=y0,z0=z0,t_first=i0,x1=x1,y1=y1,z1=z1,t_last=i1,dx=dx,dy=dy,dz=dz,length3d=length3d,theta_xy_rad=theta_xy,phi_z_rad=phi_z)
    return out

def write_report_pdf_progress(out_base: str, combined: dict, parent=None):
    rois = combined.get('rois', {}); meta = combined.get('metadata', {})
    coord = combined.get('coordination', {})
    vel = combined.get('propagation', {})
    T = int(meta.get('shape_TZYX', (0,0,0,0))[0] or 0)
    out_pdf = out_base + "_hypervolume_report.pdf"
    with PdfPages(out_pdf) as pdf:
        _plot_overview(pdf, meta, _collect_metrics(rois))
        _plot_strips(pdf, _collect_metrics(rois))
        _plot_multi_series(pdf, rois, T)
        _plot_centroid_displacements_pdf(pdf, rois, meta)
        _plot_centroid_displacements3d_pdf(pdf, rois, meta)
        _plot_coherence_pdf(pdf, coord, T)
        _plot_velocity_pdf(pdf, vel)
    print(f"Wrote report: {out_pdf}")

# ---------- ROI helpers for panel ----------

def infer_coord_axes(coords, Z, Y, X):
    cols = [coords[:, 1], coords[:, 2], coords[:, 3]]; bounds = [Z, Y, X]
    best = None; best_score = -1.0
    import itertools
    for perm in itertools.permutations([0,1,2]):
        score = 0.0
        for col_idx, bound in zip(perm, bounds):
            c = cols[col_idx]; good = np.isfinite(c) & (c >= 0) & (c < bound)
            score += np.mean(good) if c.size else 0.0
        if score > best_score: best_score = score; best = perm
    if best is None: best = (0,1,2)
    return best

def area_from_coords(coords, T):
    area_t = np.zeros(T, dtype=int)
    if coords.size == 0: return area_t
    tvals = coords[:, 0].astype(int)
    good = (tvals >= 0) & (tvals < T); tvals = tvals[good]
    if tvals.size:
        bins = np.bincount(tvals, minlength=T); area_t[:len(bins)] = bins[:T]
    return area_t

def area_zt_from_coords(coords, T, Z):
    area_zt = np.zeros((T, Z), dtype=int)
    if coords.size == 0: return area_zt
    t = coords[:, 0].astype(int); z = coords[:, 1].astype(int)
    good = (t >= 0) & (t < T) & (z >= 0) & (z < Z); t = t[good]; z = z[good]
    if t.size:
        for ti, zi in zip(t, z): area_zt[ti, zi] += 1
    return area_zt

def amp_from_coords(coords, img_TZYX, T):
    amp = np.zeros(T, dtype=float)
    if coords.size == 0: return amp
    t = coords[:, 0].astype(int); z = coords[:, 1].astype(int)
    y = coords[:, 2].astype(int); x = coords[:, 3].astype(int)
    good = (t >= 0) & (t < img_TZYX.shape[0]) & \
           (z >= 0) & (z < img_TZYX.shape[1]) & \
           (y >= 0) & (y < img_TZYX.shape[2]) & \
           (x >= 0) & (x < img_TZYX.shape[3])
    t = t[good]; z = z[good]; y = y[good]; x = x[good]
    if t.size == 0: return amp
    vals = img_TZYX[t, z, y, x].astype(float)
    sums = np.bincount(t, weights=vals, minlength=T)
    counts = np.bincount(t, minlength=T).astype(float)
    nz = counts > 0; amp[nz] = sums[nz] / counts[nz]
    return amp

