class CoherencePanel(QtWidgets.QWidget):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setLayout(QtWidgets.QVBoxLayout())
        try:
            self.layout().setContentsMargins(2, 2, 2, 2)
            self.layout().setSpacing(2)
        except Exception:
            pass
        ctr = QtWidgets.QHBoxLayout()
        ctr.addWidget(QtWidgets.QLabel("Band (period frames):"))
        self.spin_lo = QtWidgets.QSpinBox(); self.spin_lo.setRange(2, 10000); self.spin_lo.setValue(20); ctr.addWidget(self.spin_lo)
        self.spin_hi = QtWidgets.QSpinBox(); self.spin_hi.setRange(2, 10000); self.spin_hi.setValue(200); ctr.addWidget(self.spin_hi)
        self.layout().addLayout(ctr)
        self.fig = Figure(figsize=(5, 4), dpi=110, constrained_layout=True)
        self.canvas = FigureCanvas(self.fig)
        self.ax = self.fig.add_subplot(1,1,1)
        self.layout().addWidget(self.canvas)
        self._data = None
    def set_data(self, R2, widths, T):
        self._data = (R2, widths, T)
        self.refresh()
    def refresh(self):
        self.ax.clear()
        if self._data is None:
            self.ax.text(0.5,0.5,"Select an ROI to view coherence", ha='center', va='center'); self.ax.axis('off')
        else:
            R2, widths, T = self._data
            im = self.ax.imshow(R2, aspect='auto', origin='lower', extent=(0, T-1, widths[0], widths[-1]))
            self.ax.set_title("Wavelet Coherence R² (ROI vs. population mean)")
            self.ax.set_xlabel("time (frame)"); self.ax.set_ylabel("period (frames)")
            self.fig.colorbar(im, ax=self.ax, fraction=0.046, pad=0.04, label='R²')
        self.canvas.draw_idle()
    def band_period_range(self):
        lo = int(self.spin_lo.value()); hi = int(self.spin_hi.value())
        if hi < lo: hi = lo
        return (lo, hi)

# ---------- ROIPlots widget (unchanged charts) ----------

class ROIPlots(QtWidgets.QWidget):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setLayout(QtWidgets.QVBoxLayout())
        self.fig = Figure(figsize=(5, 4), dpi=120, constrained_layout=True)
        self.canvas = FigureCanvas(self.fig)
        self.layout().addWidget(self.canvas)
        self.ax_vol = self.fig.add_subplot(2, 1, 1)
        self.ax_int = self.fig.add_subplot(2, 1, 2)
        self.T = None
        self._t_cursor_top = None
        self._t_cursor_bot = None

    def clear(self):
        self.ax_vol.clear()
        self.ax_int.clear()
        self._t_cursor_top = None
        self._t_cursor_bot = None
        self.canvas.draw_idle()

    def update_data(self, area_t, amp_filt, amp_raw, current_t=None, labels=None):
        import numpy as np
        def _tolist(x):
            if isinstance(x, (list, tuple)):
                return [np.asarray(xx) if xx is not None else None for xx in x]
            if x is None:
                return []
            return [np.asarray(x)]
        area_list = _tolist(area_t)
        filt_list = _tolist(amp_filt)
        raw_list  = _tolist(amp_raw)

        n_series = max(len(area_list), len(filt_list), len(raw_list))
        if n_series == 0:
            self.clear()
            return

        def _padlist(lst, n):
            out = list(lst)
            while len(out) < n: out.append(None)
            return out
        area_list = _padlist(area_list, n_series)
        filt_list = _padlist(filt_list, n_series)
        raw_list  = _padlist(raw_list,  n_series)

        if labels is None:
            labels = [f"ROI {i+1}" for i in range(n_series)]
        else:
            labels = list(labels)
            while len(labels) < n_series:
                labels.append(f"ROI {len(labels)+1}")
            labels = labels[:n_series]
        T = 0
        for a in area_list:
            if a is not None: T = max(T, len(a))
        for a in filt_list:
            if a is not None: T = max(T, len(a))
        for a in raw_list:
            if a is not None: T = max(T, len(a))
        self.T = T if T > 0 else None

        self.ax_vol.clear()
        ymax_v = 1.0
        for arr_a, lab in zip(area_list, labels):
            if arr_a is None: continue
            aa = np.asarray(arr_a, dtype=float)
            self.ax_vol.plot(np.arange(len(aa)), aa, lw=1.5, label=lab)
            if np.isfinite(aa).any():
                ymax_v = max(ymax_v, float(np.nanmax(aa)))
        self.ax_vol.set_title("Volume (voxels) vs time")
        self.ax_vol.set_xlabel("time (frame)")
        self.ax_vol.set_ylabel("voxels")
        self.ax_vol.set_xlim(0, max(T - 1, 1))
        self.ax_vol.set_ylim(0, max(1.0, ymax_v))
        if n_series > 1:
            self.ax_vol.legend(loc="upper right", fontsize=8, frameon=False)
        if current_t is not None:
            self._t_cursor_top = self.ax_vol.axvline(current_t, ls="--", lw=1)

        self.ax_int.clear()
        ymin_i, ymax_i = None, None
        for idx in range(n_series):
            fl = filt_list[idx]
            rl = raw_list[idx]
            base_label = labels[idx]

            if fl is not None:
                ff = np.asarray(fl, dtype=float)
                self.ax_int.plot(np.arange(len(ff)), ff, lw=1.5, label=f"{base_label} (filtered)")
                if ff.size:
                    lo, hi = float(np.nanmin(ff)), float(np.nanmax(ff))
                    if np.isfinite(lo) and np.isfinite(hi):
                        ymin_i = lo if ymin_i is None else min(ymin_i, lo)
                        ymax_i = hi if ymax_i is None else max(ymax_i, hi)

            if rl is not None:
                rr = np.asarray(rl, dtype=float)
                self.ax_int.plot(np.arange(len(rr)), rr, lw=1.0, ls='--', label=f"{base_label} (raw)")
                if rr.size:
                    lo, hi = float(np.nanmin(rr)), float(np.nanmax(rr))
                    if np.isfinite(lo) and np.isfinite(hi):
                        ymin_i = lo if ymin_i is None else min(ymin_i, lo)
                        ymax_i = hi if ymax_i is None else max(ymax_i, hi)

        self.ax_int.set_title("Mean Intensity vs time")
        self.ax_int.set_xlabel("time (frame)")
        self.ax_int.set_ylabel("intensity (a.u.)")
        self.ax_int.set_xlim(0, max(T - 1, 1))

        if ymin_i is None or ymax_i is None or not np.isfinite(ymin_i) or not np.isfinite(ymax_i):
            ymin_i, ymax_i = 0.0, 1.0
        span_i = float(ymax_i - ymin_i)
        if not np.isfinite(span_i) or span_i <= 1e-12:
            # Perfectly flat traces need a finite display range; plotting only.
            center_i = float(ymin_i) if np.isfinite(ymin_i) else 1.0
            pad = max(0.05 * abs(center_i), 0.05)
        else:
            pad = 0.05 * span_i
        self.ax_int.set_ylim(ymin_i - pad, ymax_i + pad)

        self.ax_int.legend(loc="upper right", fontsize=8, frameon=False)

        if current_t is not None:
            self._t_cursor_bot = self.ax_int.axvline(current_t, ls="--", lw=1, color="gray")
        self.canvas.draw_idle()

    def update_cursor(self, current_t):
        if self._t_cursor_top is not None:
            self._t_cursor_top.set_xdata([current_t, current_t])
        if self._t_cursor_bot is not None:
            self._t_cursor_bot.set_xdata([current_t, current_t])
        self.canvas.draw_idle()

# ---------- Aggregate summary panel (unchanged visuals) ----------

class AggregatePanel(QtWidgets.QWidget):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setLayout(QtWidgets.QVBoxLayout())
        self.fig = Figure(figsize=(6, 5), dpi=110, constrained_layout=True)
        self.canvas = FigureCanvas(self.fig)
        self.layout().addWidget(self.canvas)
        self.ax0 = self.fig.add_subplot(2, 2, 1); self.ax1 = self.fig.add_subplot(2, 2, 2)
        self.ax2 = self.fig.add_subplot(2, 2, 3); self.ax3 = self.fig.add_subplot(2, 2, 4)
    def refresh(self, sites, T):
        import numpy as np
        self.ax0.clear(); self.ax1.clear(); self.ax2.clear(); self.ax3.clear()
        ks = list(sites.keys()) if hasattr(sites, "keys") else list(range(len(sites)))
        durations = []; max_vols = []; max_amps = []
        for k in ks:
            arr = sites[k]
            durations.append(int(arr[3]) if len(arr) > 3 else 0)
            mv = 0
            if len(arr) > 13 and isinstance(arr[13], dict):
                at = arr[13].get("area_t", None)
                if at is not None: mv = int(np.max(at))
            if mv == 0 and len(arr) > 1:
                try: mv = int(arr[1])
                except Exception: mv = 0
            max_vols.append(mv)
            ma = 0.0
            if len(arr) > 13 and isinstance(arr[13], dict):
                mt = arr[13].get("meanint_t", None)
                if mt is not None: ma = float(np.nanmax(np.asarray(mt)))
            if ma == 0.0 and len(arr) > 4 and np.size(arr[4]):
                try: ma = float(np.nanmax(np.asarray(arr[4])))
                except Exception: pass
            max_amps.append(ma)
        n_rois = len(durations)
        self.ax0.text(0.5, 0.5, f"Total ROIs:\n{n_rois}", ha="center", va="center", fontsize=16); self.ax0.axis("off")
        self.ax1.scatter(range(n_rois), durations, s=8); self.ax1.set_title("Duration (frames)")
        self.ax2.scatter(range(n_rois), max_vols, s=8); self.ax2.set_title("Max volume (voxels)")
        self.ax3.scatter(range(n_rois), max_amps, s=8); self.ax3.set_title("Max amplitude")
        self.canvas.draw_idle()

