def _update_stats_with_membership(self):
    if self.current_roi is None or self.sites is None:
        self.stats.setPlainText("")
        return
    arr = self.sites[self.current_roi]
    duration = int(arr[3]) if len(arr) > 3 else 0
    start = int(arr[6]) if len(arr) > 6 else 0
    amp_series = self._get_roi_amp_series_filtered(self.current_roi)
    amp_max = float(np.nanmax(amp_series)) if np.size(amp_series) else 0.0
    t_now = int(self.viewer.dims.current_step[0])
    amp_now = float(amp_series[t_now]) if (np.size(amp_series) and 0 <= t_now < len(amp_series)) else np.nan
    cname = self.class_of_roi.get(int(self.current_roi), (0, "Unclassified"))[1]
    members = ", ".join(self.ontology_membership.get(int(self.current_roi), [])) or "None"
    self.stats.setPlainText(
        f"ROI {self.current_roi}\n"
        f"Primary ontology: {cname}\n"
        f"Ontology memberships: {members}\n"
        f"Duration: {duration} frames\n"
        f"Start frame: {start}\n"
        f"Filtered Amp (max): {amp_max:.3f}\n"
        f"Filtered Amp (t={t_now}): {amp_now:.3f}"
    )
ROIPanel.update_stats = _update_stats_with_membership


def _current_filter_export_roi_ids(panel):
    if panel is None or getattr(panel, 'sites', None) is None:
        return []
    try:
        all_ids = [int(k) for k in panel.sites.keys()]
    except Exception:
        all_ids = list(range(len(getattr(panel, 'sites', {}) or {})))
    rows = getattr(panel, '_sf_rows', []) or []
    if not rows:
        return sorted(all_ids)
    try:
        roi_ids, mask = _evaluate_rows_against_values(panel, _serialize_filter_rows(panel))
        keep = {int(rid) for rid, ok in zip(roi_ids, mask) if bool(ok)}
        if keep:
            return sorted([rid for rid in all_ids if int(rid) in keep])
        return []
    except Exception:
        return sorted(all_ids)

ROIPanel.get_export_roi_ids = _current_filter_export_roi_ids

_orig_do_export = PipelinePanel.do_export
def _do_export_with_ontology(self):
    if self.sites is None:
        return
    base_dir = QtWidgets.QFileDialog.getExistingDirectory(self, "Select output directory")
    if not base_dir:
        return
    base = os.path.join(base_dir, "napari_export")
    T, Z, Y, X = self.filtered.shape

    export_rois = self.sites
    export_scope = 'all'
    export_filter_desc = 'All ROIs'
    if self.roi_panel is not None:
        try:
            export_ids = self.roi_panel.get_export_roi_ids()
        except Exception:
            export_ids = []
        rows = getattr(self.roi_panel, '_sf_rows', [])
        if rows:
            export_scope = 'filtered'
            export_rois = {int(rid): self.sites[int(rid)] for rid in export_ids if int(rid) in self.sites}
            export_filter_desc = f"Filtered ROIs ({len(export_rois)} of {len(self.sites)})"

    disp2d_map = _compute_displacements2d_map(export_rois, int(T))
    disp3d_map = _compute_displacements3d_map(export_rois, int(T))
    site_to_rois = {}
    for roi_id, arr_roi in export_rois.items():
        sid = int(arr_roi[13].get('site_label', 0))
        site_to_rois.setdefault(sid, []).append(int(roi_id))

    coordination = {}
    if isinstance(self.coordination, dict):
        coordination = dict(self.coordination)
        if 'band_mean' in coordination and isinstance(coordination['band_mean'], dict):
            coordination['band_mean'] = {
                int(rid): coordination['band_mean'][rid]
                for rid in coordination['band_mean']
                if int(rid) in export_rois
            }

    propagation = estimate_propagation_velocity(export_rois, T) if export_scope == 'filtered' else (self.propagation if self.propagation is not None else {})
    ontology_export = _build_ontology_export(self.roi_panel) if self.roi_panel is not None else {}
    if ontology_export:
        ontology_export["primary_class_by_roi"] = {int(rid): nm for rid, nm in ontology_export.get("primary_class_by_roi", {}).items() if int(rid) in export_rois}
        ontology_export["membership_by_roi"] = {int(rid): nm for rid, nm in ontology_export.get("membership_by_roi", {}).items() if int(rid) in export_rois}
        summary_counts = {}
        for rid, nm in ontology_export.get("primary_class_by_roi", {}).items():
            summary_counts[nm] = summary_counts.get(nm, 0) + 1
        ontology_export["summary_counts"] = summary_counts

    combined = {
        'rois': export_rois,
        'hierarchy': {'site_to_rois': site_to_rois, 'n_sites': len(site_to_rois)},
        'metadata': {
            'input_file': '(napari)',
            'shape_TZYX': (int(T), int(Z), int(Y), int(X)),
            'threshold_method': self.method.currentText(),
            'use_spatial': bool(self.chk_spatial.isChecked()),
            'use_savgol': bool(self.chk_savgol.isChecked()),
            'use_gate': bool(self.chk_gate.isChecked()),
            'blur_sigma': float(self.spin_sigma.value()),
            'manual_threshold': float(self.spin_manual_threshold.value()),
            'savgol_window': int(self.spin_win.value()),
            'bg_subtract': bool(self.chk_bg.isChecked()),
            'export_scope': export_scope,
            'export_filter_desc': export_filter_desc,
            'n_rois_exported': int(len(export_rois)),
            'n_rois_total': int(len(self.sites)),
        },
        'coordination': coordination,
        'propagation': propagation,
        'ontology': ontology_export,
    }
    combined.setdefault('displacements', {})['centroid_start_end_2d'] = disp2d_map
    combined['displacements']['centroid_start_end_3d'] = disp3d_map
    pprog = StepProgress("Exporting", maximum=2, parent=self); pprog.set_text("Writing combined pickle...")
    with open(base + "_hypervolume_sites_COMBINED.p", "wb") as f:
        pkl.dump(combined, f, protocol=pkl.HIGHEST_PROTOCOL)
    pprog.step(1); pprog.set_text("Writing PDF report...")
    write_report_pdf_progress(base, combined, parent=self)
    pprog.step(2); pprog.close()
    QtWidgets.QMessageBox.information(self, "Export", f"Wrote:\n{base}_hypervolume_sites_COMBINED.p\n{base}_hypervolume_report.pdf\n\nExported scope: {export_filter_desc}")
PipelinePanel.do_export = _do_export_with_ontology

_orig_plot_overview = _plot_overview
def _plot_ontology_summary(pdf, combined):
    ontology = combined.get("ontology", {}) if isinstance(combined, dict) else {}
    classes = ontology.get("classes", []) or []
    summary = ontology.get("summary_counts", {}) or {}
    fig = plt.figure(figsize=(10, 6), dpi=160)
    fig.suptitle("Ontology Summary", fontsize=14)
    gs = fig.add_gridspec(2, 2)
    ax0 = fig.add_subplot(gs[:, 0]); ax0.axis("off")
    if not classes:
        ax0.text(0.02, 0.98, "No ontology classes saved for this export.", va="top", ha="left", family="monospace")
        ax1 = fig.add_subplot(gs[0, 1]); ax1.axis("off")
        ax2 = fig.add_subplot(gs[1, 1]); ax2.axis("off")
    else:
        lines = []
        for cls in classes:
            lines.append(f"{int(cls.get('priority', 0)):>2}. {cls.get('name', '')}: {cls.get('rule_text', '')}")
        ax0.text(0.02, 0.98, "\n".join(lines), va="top", ha="left", family="monospace")
        ax1 = fig.add_subplot(gs[0, 1])
        labels = list(summary.keys())
        values = [summary[k] for k in labels]
        if labels:
            ax1.bar(np.arange(len(labels)), values)
            ax1.set_xticks(np.arange(len(labels)))
            ax1.set_xticklabels(labels, rotation=35, ha='right')
            ax1.set_ylabel("ROI count")
            ax1.set_title("Primary ontology counts")
        else:
            ax1.axis("off")
        ax2 = fig.add_subplot(gs[1, 1]); ax2.axis("off")
        ax2.text(0.02, 0.98, "\n".join([f"{k}: {v}" for k, v in summary.items()]), va="top", ha="left", family="monospace")
    pdf.savefig(fig); plt.close(fig)

_orig_write_report = write_report_pdf_progress
def write_report_pdf_progress(out_base: str, combined: dict, parent=None):
    rois = combined.get('rois', {}); meta = combined.get('metadata', {})
    coord = combined.get('coordination', {})
    vel = combined.get('propagation', {})
    T = int(meta.get('shape_TZYX', (0,0,0,0))[0] or 0)
    out_pdf = out_base + "_hypervolume_report.pdf"
    with PdfPages(out_pdf) as pdf:
        _plot_overview(pdf, meta, _collect_metrics(rois))
        _plot_ontology_summary(pdf, combined)
        _plot_strips(pdf, _collect_metrics(rois))
        _plot_multi_series(pdf, rois, T)
        _plot_centroid_displacements_pdf(pdf, rois, meta)
        _plot_centroid_displacements3d_pdf(pdf, rois, meta)
        _plot_coherence_pdf(pdf, coord, T)
        _plot_velocity_pdf(pdf, vel)
    print(f"Wrote report: {out_pdf}")
# --- END ONTOLOGY PATCH ---


# --- BEGIN FINGERPRINT PATCH ---
class FingerprintPanel(QtWidgets.QWidget):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setLayout(QtWidgets.QVBoxLayout())
        self.summary = QtWidgets.QPlainTextEdit()
        self.summary.setReadOnly(True)
        self.summary.setMinimumHeight(140)
        self.layout().addWidget(self.summary)
        self.fig = Figure(figsize=(5, 2.8), dpi=110, constrained_layout=True)
        self.canvas = FigureCanvas(self.fig)
        self.ax = self.fig.add_subplot(1,1,1)
        self.layout().addWidget(self.canvas)
        self.fingerprint = {}

    def set_fingerprint(self, fingerprint: dict):
        self.fingerprint = dict(fingerprint or {})
        self.refresh()

    def refresh(self):
        fp = dict(self.fingerprint or {})
        self.ax.clear()
        if not fp:
            self.summary.setPlainText("No fingerprint computed")
            self.ax.text(0.5, 0.5, "No fingerprint", ha='center', va='center')
            self.ax.axis('off')
            self.canvas.draw_idle()
            return
        lines = []
        preferred = [
            'n_rois', 'roi_density_per_frame', 'n_sites',
            'mean_lifetime', 'median_lifetime', 'mean_max_area', 'median_max_area',
            'mean_amp_range', 'mean_disp_len2d', 'mean_duty_cycle',
            'mean_n_active_runs', 'mean_coherence_band', 'std_coherence_band',
            'propagation_speed_frames_per_pixel',
        ]
        for key in preferred:
            if key in fp:
                val = fp[key]
                if isinstance(val, (int, np.integer)):
                    lines.append(f"{key}: {int(val)}")
                else:
                    try:
                        lines.append(f"{key}: {float(val):.4g}")
                    except Exception:
                        lines.append(f"{key}: {val}")
        frac_items = [(k.replace('frac_', ''), float(v)) for k, v in fp.items() if str(k).startswith('frac_')]
        frac_items.sort(key=lambda kv: kv[1], reverse=True)
        if frac_items:
            lines.append("")
            lines.append("ontology fractions:")
            for k, v in frac_items[:8]:
                lines.append(f"  {k}: {v:.3f}")
        self.summary.setPlainText("\n".join(lines))
        if frac_items:
            labels = [k for k, _ in frac_items[:8]]
            vals = [v for _, v in frac_items[:8]]
            self.ax.bar(np.arange(len(labels)), vals)
            self.ax.set_xticks(np.arange(len(labels)))
            self.ax.set_xticklabels(labels, rotation=35, ha='right')
            self.ax.set_ylim(0, max(1.0, max(vals) * 1.15))
            self.ax.set_ylabel('fraction')
            self.ax.set_title('Primary ontology composition')
        else:
            self.ax.text(0.5, 0.5, 'No ontology fractions', ha='center', va='center')
            self.ax.axis('off')
        self.canvas.draw_idle()


def _compute_sample_fingerprint(rois: dict, ontology: dict=None, coordination: dict=None, propagation: dict=None, T: int=0):
    rois = rois or {}
    metrics = _collect_metrics(rois) if rois else {
        'roi_id': np.array([], dtype=int),
        'lifetime': np.array([], dtype=float),
        'duty_cycle': np.array([], dtype=float),
        'max_area': np.array([], dtype=float),
        'amp_range': np.array([], dtype=float),
        'n_active_runs': np.array([], dtype=float),
        'first_time': np.array([], dtype=float),
        'site_label': np.array([], dtype=float),
    }
    def _mean(x):
        x = np.asarray(x, dtype=float)
        return float(np.nanmean(x)) if x.size else 0.0
    def _median(x):
        x = np.asarray(x, dtype=float)
        return float(np.nanmedian(x)) if x.size else 0.0
    fp = {
        'n_rois': int(len(metrics['roi_id'])),
        'roi_density_per_frame': float(len(metrics['roi_id']) / max(1, int(T))) if T else float(len(metrics['roi_id'])),
        'n_sites': int(len(set(int(v) for v in np.asarray(metrics.get('site_label', []), dtype=float) if int(v) > 0))),
        'mean_lifetime': _mean(metrics.get('lifetime', [])),
        'median_lifetime': _median(metrics.get('lifetime', [])),
        'mean_max_area': _mean(metrics.get('max_area', [])),
        'median_max_area': _median(metrics.get('max_area', [])),
        'mean_amp_range': _mean(metrics.get('amp_range', [])),
        'median_amp_range': _median(metrics.get('amp_range', [])),
        'mean_duty_cycle': _mean(metrics.get('duty_cycle', [])),
        'mean_n_active_runs': _mean(metrics.get('n_active_runs', [])),
        'mean_first_time': _mean(metrics.get('first_time', [])),
    }
    disp = _compute_displacements2d_map(rois, int(T) if T else int(max([0] + [int(v) for v in metrics.get('lifetime', [])])))
    lengths = [float(v.get('length', 0.0)) for v in disp.values()]
    fp['mean_disp_len2d'] = float(np.mean(lengths)) if lengths else 0.0
    fp['median_disp_len2d'] = float(np.median(lengths)) if lengths else 0.0
    band_mean = []
    if isinstance(coordination, dict):
        band_mean = [float(v) for v in coordination.get('band_mean', {}).values() if np.isfinite(v)]
    fp['mean_coherence_band'] = float(np.mean(band_mean)) if band_mean else 0.0
    fp['std_coherence_band'] = float(np.std(band_mean)) if band_mean else 0.0
    if isinstance(propagation, dict):
        sp = propagation.get('speed_frames_per_pixel', np.nan)
        ang = propagation.get('angle_radians', np.nan)
        fp['propagation_speed_frames_per_pixel'] = float(sp) if np.isfinite(sp) else 0.0
        fp['propagation_angle_radians'] = float(ang) if np.isfinite(ang) else 0.0
    else:
        fp['propagation_speed_frames_per_pixel'] = 0.0
        fp['propagation_angle_radians'] = 0.0
    ontology = ontology or {}
    primary = ontology.get('primary_class_by_roi', {}) if isinstance(ontology, dict) else {}
    if primary:
        total = float(max(1, len(primary)))
        counts = {}
        for _, nm in primary.items():
            nm = str(nm)
            counts[nm] = counts.get(nm, 0) + 1
        for nm, ct in counts.items():
            safe = nm.lower().replace(' ', '_')
            fp[f'frac_{safe}'] = float(ct / total)
    return fp


def _build_fingerprint_export(panel, rois=None, coordination=None, propagation=None, T=0):
    if panel is not None and hasattr(panel, 'sample_fingerprint') and rois is None:
        return dict(getattr(panel, 'sample_fingerprint', {}) or {})
    ontology = _build_ontology_export(panel) if panel is not None else {}
    return _compute_sample_fingerprint(rois or {}, ontology=ontology, coordination=coordination or {}, propagation=propagation or {}, T=int(T or 0))


def _refresh_fingerprint(panel):
    if panel is None or getattr(panel, 'sites', None) is None:
        return
    ontology = _build_ontology_export(panel)
    coordination = getattr(getattr(panel, 'pipeline_panel', None), 'coordination', {}) if getattr(panel, 'pipeline_panel', None) is not None else {}
    propagation = getattr(getattr(panel, 'pipeline_panel', None), 'propagation', {}) if getattr(panel, 'pipeline_panel', None) is not None else {}
    T = int(getattr(panel, 'T', 0) or 0)
    panel.sample_fingerprint = _compute_sample_fingerprint(panel.sites, ontology=ontology, coordination=coordination, propagation=propagation, T=T)
    if getattr(panel, 'fingerprint_panel', None) is not None:
        panel.fingerprint_panel.set_fingerprint(panel.sample_fingerprint)


