def _roi_init_with_fingerprint(self, viewer, image_filtered_TZYX, image_raw_TZYX):
    _orig_roi_init_fp(self, viewer, image_filtered_TZYX, image_raw_TZYX)
    self.sample_fingerprint = {}
    self.pipeline_panel = None
    self.fingerprint_group = QtWidgets.QGroupBox("Sample fingerprint")
    self.fingerprint_group.setMaximumHeight(120)
    try:
        self.fingerprint_group.setSizePolicy(QtWidgets.QSizePolicy.Preferred, QtWidgets.QSizePolicy.Fixed)
    except Exception:
        pass
    flay = QtWidgets.QVBoxLayout(self.fingerprint_group)
    try:
        flay.setContentsMargins(4, 4, 4, 4)
        flay.setSpacing(4)
    except Exception:
        pass
    self.fingerprint_panel = FingerprintPanel(self)
    flay.addWidget(self.fingerprint_panel)
    insert_before = getattr(self, 'ontology_group', None)
    if insert_before is not None:
        self.layout().insertWidget(self.layout().indexOf(insert_before), self.fingerprint_group)
    else:
        self.layout().addWidget(self.fingerprint_group)
    try:
        self.plots.setMinimumHeight(260)
        self.layout().setStretchFactor(self.fingerprint_group, 0)
        if getattr(self, 'ontology_group', None) is not None:
            self.layout().setStretchFactor(self.ontology_group, 0)
        self.layout().setStretchFactor(self.stats, 0)
        self.layout().setStretchFactor(self.plots, 3)
    except Exception:
        pass
