def _housekeeping_configure_manual_threshold_widget(panel):
    try:
        w = getattr(panel, 'spin_manual_threshold', None)
        if w is None:
            return
        if hasattr(w, 'setDecimals'):
            w.setDecimals(0)
        if hasattr(w, 'setSingleStep'):
            w.setSingleStep(1)
        if hasattr(w, 'setRange'):
            w.setRange(-2147483648, 2147483647)
        if hasattr(w, 'setValue'):
            w.setValue(int(round(float(w.value()))))
    except Exception:
        pass


