_housekeeping_plot_overview = _plot_overview
def _plot_overview_housekeeping(pdf, meta, metrics):
    fig = plt.figure(figsize=(10, 6), dpi=160)
    title = str(meta.get('export_label', 'Hypervolume Summary'))
    fig.suptitle(title, fontsize=14)
    gs = fig.add_gridspec(2, 3, height_ratios=[1, 2])
    ax0 = fig.add_subplot(gs[0, :]); ax0.axis('off')
    threshold_text = f"Threshold: {meta.get('threshold_method')}"
    if str(meta.get('threshold_method', '')).lower() == 'manual':
        try:
            threshold_text += f" ({int(round(float(meta.get('manual_threshold', 0))))})"
        except Exception:
            threshold_text += f" ({meta.get('manual_threshold', 0)})"
    lines = [
        f"Total hypervolumes (ROIs): {len(metrics['roi_id'])}",
        f"Shape (T,Z,Y,X): {meta.get('shape_TZYX', None)}",
        threshold_text + " | "
        + f"export={meta.get('export_filter_desc', 'All ROIs')}  "
        + f"spatial={meta.get('use_spatial')} (σ={meta.get('blur_sigma', 0.0)})  "
        + f"savgol={meta.get('use_savgol')} (win={meta.get('savgol_window', 'auto')})  "
        + f"gate={meta.get('use_gate')}  "
        + f"bg_subtract={meta.get('bg_subtract', True)}",
    ]
    if meta.get('export_mode') is not None:
        lines.append(f"Export mode: {meta.get('export_mode')}")
    if meta.get('channel_index') is not None:
        lines.append(f"Channel: {meta.get('channel_index')}")
    if meta.get('n_channels_total') is not None:
        lines.append(f"Total channels in image: {meta.get('n_channels_total')}")
    ax0.text(0.01, 0.8, "\n".join(lines), va='top', ha='left', family='monospace')
    _hist(fig.add_subplot(gs[1,0]), metrics['lifetime'], 'Lifetime (frames)', 'frames')
    _hist(fig.add_subplot(gs[1,1]), metrics['max_area'], 'Max volume (voxels)', 'voxels')
    _hist(fig.add_subplot(gs[1,2]), metrics['amp_range'], 'Amplitude range', 'intensity')
    pdf.savefig(fig); plt.close(fig)
_plot_overview = _plot_overview_housekeeping


_housekeeping_plot_multi_series = _plot_multi_series
def _plot_multi_series_housekeeping(pdf, rois, T, meta=None):
    fig = plt.figure(figsize=(12, 6), dpi=160)
    ax = fig.add_subplot(1, 1, 1)
    series = []; site_labels = []
    for rid, arr in sorted(rois.items(), key=lambda kv: str(kv[0])):
        try:
            meta_roi = arr[13]
            area_t = np.array(meta_roi.get('area_t', []), dtype=float)
            site_label = int(meta_roi.get('site_label', 0))
        except Exception:
            area_t = np.array([], dtype=float)
            site_label = 0
        if area_t.size == 0:
            continue
        series.append(area_t); site_labels.append(site_label)
    if not series:
        ax.text(0.5, 0.5, 'No ROI time series', ha='center', va='center'); ax.set_axis_off()
    else:
        maxT = max(T, max(s.size for s in series)); xs = np.arange(maxT)
        uniq_sites = np.unique(site_labels)
        cmap = plt.get_cmap('tab20')
        site_color = {s: cmap(i % cmap.N) for i, s in enumerate(uniq_sites)}
        for s, lab in zip(series, site_labels):
            y = np.zeros(maxT, dtype=float); y[:s.size] = s
            ax.plot(xs, y, lw=0.8, alpha=0.5, color=site_color.get(lab, 'k'))
        title = 'All ROIs — Volume (voxels) over time'
        if isinstance(meta, dict) and meta.get('channel_index') is not None:
            title = f"Channel {meta.get('channel_index')} — " + title
        ax.set_title(title)
        ax.set_xlabel('time (frame)'); ax.set_ylabel('voxels')
        if len(uniq_sites) <= 12:
            handles = [plt.Line2D([0], [0], color=site_color[s], lw=2) for s in uniq_sites]
            labels = [f"site {int(s)}" for s in uniq_sites]
            ax.legend(handles, labels, loc='upper right', fontsize=8, framealpha=0.7)
    pdf.savefig(fig); plt.close(fig)


def write_report_pdf_progress(out_base: str, combined: dict, parent=None):
    rois = combined.get('rois', {})
    meta = combined.get('metadata', {})
    coord = combined.get('coordination', {})
    vel = combined.get('propagation', {})
    T = int(meta.get('shape_TZYX', (0,0,0,0))[0] or 0)
    out_pdf = out_base + "_hypervolume_report.pdf"
    with PdfPages(out_pdf) as pdf:
        _plot_overview(pdf, meta, _collect_metrics(rois))
        _plot_fingerprint_summary(pdf, combined)
        _plot_ontology_summary(pdf, combined)
        _plot_strips(pdf, _collect_metrics(rois))
        _plot_multi_series_housekeeping(pdf, rois, T, meta=meta)
        _plot_centroid_displacements_pdf(pdf, rois, meta)
        _plot_centroid_displacements3d_pdf(pdf, rois, meta)
        _plot_coherence_pdf(pdf, coord, T)
        _plot_velocity_pdf(pdf, vel)
    print(f"Wrote report: {out_pdf}")


