# --- BEGIN QT/MATPLOTLIB LIFECYCLE SAFETY PATCH V9 ---
# Purpose:
# - Keep the V8 interactivity optimizations.
# - Prevent delayed matplotlib/Qt draw callbacks from crashing after a plot widget is deleted.
# - Avoid deprecated/removed napari.gui_qt usage on newer napari versions.
# - Disconnect ROI-panel dim callbacks when the panel is destroyed.

try:
    _S8_ORIG_FIGCANVAS_DRAW_IDLE = FigureCanvas.draw_idle
    _S8_ORIG_FIGCANVAS_DRAW = FigureCanvas.draw

    def _s8_is_deleted_runtime_error(exc):
        msg = str(exc).lower()
        return "deleted" in msg or "wrapped c/c++ object" in msg or "underlying c/c++ object" in msg

    def _s8_safe_canvas_draw_idle(self, *args, **kwargs):
        try:
            return _S8_ORIG_FIGCANVAS_DRAW_IDLE(self, *args, **kwargs)
        except (RuntimeError, ReferenceError) as exc:
            if _s8_is_deleted_runtime_error(exc):
                return None
            raise

    def _s8_safe_canvas_draw(self, *args, **kwargs):
        try:
            return _S8_ORIG_FIGCANVAS_DRAW(self, *args, **kwargs)
        except (RuntimeError, ReferenceError) as exc:
            if _s8_is_deleted_runtime_error(exc):
                return None
            raise

    FigureCanvas.draw_idle = _s8_safe_canvas_draw_idle
    FigureCanvas.draw = _s8_safe_canvas_draw
except Exception as _e:
    print("Canvas lifecycle safety patch skipped:", _e)


try:
    _S8_ORIG_ROIPANEL_INIT_V9 = ROIPanel.__init__
    _S8_ORIG_ROIPANEL_ON_DIMS_CHANGED_V9 = ROIPanel.on_dims_changed

    def _s8_roi_panel_destroyed_v9(self, *args, **kwargs):
        try:
            self._s8_destroyed = True
        except Exception:
            pass
        try:
            self.viewer.dims.events.current_step.disconnect(self.on_dims_changed)
        except Exception:
            pass

    def _s8_roi_panel_init_v9(self, *args, **kwargs):
        _S8_ORIG_ROIPANEL_INIT_V9(self, *args, **kwargs)
        try:
            self._s8_destroyed = False
            self.destroyed.connect(lambda *_: _s8_roi_panel_destroyed_v9(self))
        except Exception:
            pass

    def _s8_roi_on_dims_changed_v9(self, event=None):
        try:
            if getattr(self, '_s8_destroyed', False):
                return
        except Exception:
            return
        try:
            return _S8_ORIG_ROIPANEL_ON_DIMS_CHANGED_V9(self, event)
        except (RuntimeError, ReferenceError) as exc:
            if 'deleted' in str(exc).lower() or 'wrapped c/c++ object' in str(exc).lower():
                try:
                    self._s8_destroyed = True
                except Exception:
                    pass
                return
            raise

    ROIPanel.__init__ = _s8_roi_panel_init_v9
    ROIPanel.on_dims_changed = _s8_roi_on_dims_changed_v9
except Exception as _e:
    print("ROI panel lifecycle safety patch skipped:", _e)


