def _s8_md_plot_summary(pdf, combined):
    md = combined.get('microdomain', {}) if isinstance(combined, dict) else {}
    if not md:
        return
    fig = plt.figure(figsize=(10, 6), dpi=160)
    fig.suptitle('Microdomain Resolver Summary', fontsize=14)
    ax = fig.add_subplot(1, 1, 1); ax.axis('off')
    lines = [
        f"structure_type: {md.get('structure_type', '')}",
        f"mode: {md.get('mode', '')}",
        f"structure_channel: {md.get('structure_channel', '')}",
        f"signal_channel: {md.get('signal_channel', '')}",
        f"projection: {md.get('projection', '')}",
        f"threshold: {md.get('threshold_method', '')} = {md.get('threshold_value', '')}",
        '',
        'summary:',
    ]
    for k, v in sorted((md.get('summary', {}) or {}).items()):
        if isinstance(v, (list, tuple, dict)):
            continue
        try:
            if isinstance(v, (float, np.floating)):
                lines.append(f"  {k}: {float(v):.5g}")
            else:
                lines.append(f"  {k}: {v}")
        except Exception:
            lines.append(f"  {k}: {v}")
    ax.text(0.02, 0.98, '\n'.join(lines), va='top', ha='left', family='monospace')
    pdf.savefig(fig); plt.close(fig)

