try:
    _s8_md_orig_do_analyze_pre4d = PipelinePanel.do_analyze
    def _s8_md_do_analyze_pre4d(self):
        st = self._get_channel_state() if hasattr(self, '_get_channel_state') else None
        if not st:
            return _s8_md_orig_do_analyze_pre4d(self)
        md_mask = st.get('microdomain_roi_mask_bool')
        use_md = bool(st.get('microdomain_use_for_4d', False) and md_mask is not None)
        if not use_md:
            return _s8_md_orig_do_analyze_pre4d(self)

        md_mask = _s8_md_as_tzyx(md_mask)
        if md_mask is None:
            return _s8_md_orig_do_analyze_pre4d(self)
        md_mask = md_mask.astype(bool, copy=False)
        orig_mask = st.get('mask_bool')
        orig_filtered = st.get('filtered')
        orig_img = st.get('img')
        base_shape_array = orig_filtered if orig_filtered is not None else orig_img
        if base_shape_array is None or md_mask.shape != np.asarray(base_shape_array).shape:
            QtWidgets.QMessageBox.information(self, 'Microdomain Resolver', 'Resolved microdomain mask shape does not match the active channel hyperstack. Re-resolve microdomains or change channels.')
            return None

        analysis_filtered = st.get('microdomain_signal_tzyx')
        analysis_raw = st.get('microdomain_signal_raw_tzyx')
        if analysis_filtered is None or _s8_md_as_tzyx(analysis_filtered) is None or _s8_md_as_tzyx(analysis_filtered).shape != md_mask.shape:
            analysis_filtered = orig_filtered if orig_filtered is not None else orig_img
        if analysis_raw is None or _s8_md_as_tzyx(analysis_raw) is None or _s8_md_as_tzyx(analysis_raw).shape != md_mask.shape:
            analysis_raw = analysis_filtered if analysis_filtered is not None else orig_img

        # Temporarily feed the resolved microdomain mask and selected signal image through the existing
        # 4D label machinery, preserving all downstream ROI plots, ontology, fingerprinting, export,
        # and multichannel/intersection behavior.
        st['mask_bool'] = md_mask
        st['filtered'] = np.asarray(analysis_filtered)
        st['img'] = np.asarray(analysis_raw)
        self.mask_bool = st['mask_bool']
        self.filtered = st['filtered']
        self.img = st['img']
        try:
            out = _s8_md_orig_do_analyze_pre4d(self)
            try:
                st['analysis_mask_source'] = 'microdomain_roi_mask_bool'
                st['analysis_signal_channel'] = int(st.get('microdomain_signal_channel', getattr(self, 'current_channel', 0)))
            except Exception:
                pass
            return out
        finally:
            # Restore the native channel arrays/mask so Filter/Threshold/Resolver remain tied to the
            # visible structure channel. The sites/metrics just produced remain microdomain-derived.
            st['mask_bool_native'] = orig_mask
            st['filtered_native'] = orig_filtered
            st['img_native'] = orig_img
            st['mask_bool'] = orig_mask
            st['filtered'] = orig_filtered
            st['img'] = orig_img
            self.mask_bool = orig_mask
            self.filtered = orig_filtered
            self.img = orig_img
            try:
                if getattr(self, 'roi_panel', None) is not None:
                    self.roi_panel.stats.appendPlainText('\nAnalysis source: dynamic microdomain ROI mask')
            except Exception:
                pass
    PipelinePanel.do_analyze = _s8_md_do_analyze_pre4d
except Exception as _e:
    print('Microdomain pre-4D analyze patch skipped:', _e)


try:
    _s8_md_orig_build_bundle_pre4d = _build_channel_export_bundle
    def _build_channel_export_bundle(panel, ch, intersect=False):
        combined, suffix = _s8_md_orig_build_bundle_pre4d(panel, ch, intersect=intersect)
        try:
            st = _s8_md_state(panel, ch)
            md = st.get('microdomain')
            if md:
                combined['microdomain'] = _s8_md_exportable(md)
                combined.setdefault('metadata', {})['analysis_mask_source'] = st.get('analysis_mask_source', 'microdomain_roi_mask_bool' if st.get('microdomain_use_for_4d') else 'native_mask_bool')
                combined.setdefault('metadata', {})['analysis_signal_channel'] = int(st.get('analysis_signal_channel', st.get('microdomain_signal_channel', int(ch))))
        except Exception:
            pass
        return combined, suffix
except Exception as _e:
    print('Microdomain pre-4D export metadata patch skipped:', _e)
