# --- BEGIN ROI SOURCE BUILDER PATCH ---
# Reframes the pre-4D microdomain resolver as a general ROI Source Builder.
# This keeps the existing dynamic microdomain behavior intact, but adds:
#   1) biological ROI source presets,
#   2) explicit output-domain/4D ROI source metadata,
#   3) optional signal-gated composite microdomains, and
#   4) reproducible ROI-source definitions in the exported microdomain payload.


def _s8_rsb_label_dynamic_mask(mask_tzyx, min_size=1):
    m = _s8_md_as_tzyx(mask_tzyx)
    if m is None:
        return None
    m = np.asarray(m, dtype=bool)
    labels = np.zeros(m.shape, dtype=np.int32)
    for t in range(m.shape[0]):
        try:
            labels[t] = label(m[t], connectivity=1).astype(np.int32)
        except Exception:
            labels[t] = (m[t].astype(np.int32))
    return labels


def _s8_rsb_threshold_signal_tzyx(signal_tzyx, source='Filtered', method='Otsu', manual=0.0, sigma=0.0, min_size=1, progress=None):
    sig = _s8_md_as_tzyx(signal_tzyx)
    if sig is None:
        return None, []
    sig = np.asarray(sig)
    out = np.zeros(sig.shape, dtype=bool)
    thresholds = []
    for t in range(sig.shape[0]):
        if progress is not None:
            try:
                progress.set_text(f'Thresholding signal gate frame {t+1}/{sig.shape[0]}...')
            except Exception:
                pass
        mask, thr = _s8_md_threshold_volume(
            sig[t],
            source=source,
            method=method,
            manual=float(manual),
            sigma=float(sigma),
            min_size=max(1, int(min_size)),
        )
        out[t] = mask.astype(bool)
        thresholds.append(float(thr))
    return out, thresholds


def _s8_rsb_apply_gate(structure_mask_tzyx, signal_mask_tzyx, relation):
    sm = _s8_md_as_tzyx(structure_mask_tzyx)
    gm = _s8_md_as_tzyx(signal_mask_tzyx)
    if sm is None or gm is None or sm.shape != gm.shape:
        return sm.astype(bool) if sm is not None else None
    sm = np.asarray(sm, dtype=bool)
    gm = np.asarray(gm, dtype=bool)
    relation = str(relation)
    if relation == 'OR signal-high':
        return sm | gm
    if relation == 'Structure NOT signal-high':
        return sm & (~gm)
    # Default: biologically interpretable composite ROI = structure occupied and signal-high.
    return sm & gm


def _s8_rsb_safe_combo_text(obj, default=''):
    try:
        return str(obj.currentText())
    except Exception:
        return str(default)


def _s8_rsb_definition_from_dialog(dialog, *, preset, output_domain, structure_type, mode, structure_ch, structure_source, signal_ch, signal_source, use_for_4d, gate_enabled, gate_relation, gate_method, gate_manual, threshold_method):
    return {
        'name': str(preset),
        'preset': str(preset),
        'dynamic': True,
        'output_role': 'roi_source_for_4d_label' if bool(use_for_4d) else 'preview_only',
        'output_domain': str(output_domain),
        'structure_type': str(structure_type),
        'resolver': str(mode),
        'structure_channel': int(structure_ch),
        'structure_source': str(structure_source),
        'signal_channels': [int(signal_ch)],
        'signal_source': str(signal_source),
        'parameters': {
            'threshold_method': str(threshold_method),
            'manual_threshold': float(getattr(dialog, 'spin_manual', QtWidgets.QDoubleSpinBox()).value()) if hasattr(dialog, 'spin_manual') else 0.0,
            'preblur_sigma': float(getattr(dialog, 'spin_sigma', QtWidgets.QDoubleSpinBox()).value()) if hasattr(dialog, 'spin_sigma') else 0.0,
            'min_size': int(getattr(dialog, 'spin_min_size', QtWidgets.QSpinBox()).value()) if hasattr(dialog, 'spin_min_size') else 1,
            'watershed_peak_distance': int(getattr(dialog, 'spin_peak_dist', QtWidgets.QSpinBox()).value()) if hasattr(dialog, 'spin_peak_dist') else 3,
            'min_terminal_branch_length': int(getattr(dialog, 'spin_spike_len', QtWidgets.QSpinBox()).value()) if hasattr(dialog, 'spin_spike_len') else 7,
        },
        'signal_gate': {
            'enabled': bool(gate_enabled),
            'relation': str(gate_relation),
            'threshold_method': str(gate_method),
            'manual_threshold': float(gate_manual),
        },
        'measurement_domains': ['inside_roi'],
    }


def _s8_rsb_apply_preset(dialog, *_):
    preset = _s8_rsb_safe_combo_text(getattr(dialog, 'cmb_roi_source_preset', None), 'Structure-resolved microdomain')
    try:
        if preset == 'Signal activity':
            dialog.cmb_structure.setCurrentText('Generic')
            dialog.cmb_mode.setCurrentText('Network components')
            dialog.cmb_structure_source.setCurrentText(dialog.cmb_signal_source.currentText())
            dialog.cmb_output_domain.setCurrentText('Resolved mask')
            dialog.chk_signal_gate.setChecked(False)
        elif preset == 'Mitochondria instances':
            dialog.cmb_structure.setCurrentText('Mitochondria')
            dialog.cmb_mode.setCurrentText('Instance split')
            dialog.cmb_output_domain.setCurrentText('Resolved mask')
            dialog.chk_signal_gate.setChecked(False)
        elif preset == 'Mitochondrial territories':
            dialog.cmb_structure.setCurrentText('Mitochondria')
            dialog.cmb_mode.setCurrentText('Network components')
            dialog.cmb_output_domain.setCurrentText('Resolved mask')
            dialog.chk_signal_gate.setChecked(False)
        elif preset == 'F-actin spikes':
            dialog.cmb_structure.setCurrentText('F-actin')
            dialog.cmb_mode.setCurrentText('Skeleton graph + spikes')
            dialog.cmb_output_domain.setCurrentText('Terminal spikes')
            dialog.chk_signal_gate.setChecked(False)
        elif preset == 'F-actin filaments/network':
            dialog.cmb_structure.setCurrentText('F-actin')
            dialog.cmb_mode.setCurrentText('Network components')
            dialog.cmb_output_domain.setCurrentText('Resolved mask')
            dialog.chk_signal_gate.setChecked(False)
        elif preset == 'Composite microdomain':
            dialog.cmb_output_domain.setCurrentText('Signal-gated structure')
            dialog.chk_signal_gate.setChecked(True)
            dialog.cmb_gate_relation.setCurrentText('AND signal-high')
        else:
            dialog.chk_signal_gate.setChecked(False)
    except Exception:
        pass
    try:
        _s8_rsb_update_gate_visibility(dialog)
    except Exception:
        pass


def _s8_rsb_update_gate_visibility(dialog, *_):
    visible = False
    try:
        visible = bool(dialog.chk_signal_gate.isChecked()) or dialog.cmb_output_domain.currentText() == 'Signal-gated structure'
    except Exception:
        visible = False
    for name in ('lbl_gate_relation', 'cmb_gate_relation', 'lbl_gate_threshold', 'cmb_gate_threshold', 'lbl_gate_manual', 'spin_gate_manual'):
        try:
            getattr(dialog, name).setVisible(visible)
        except Exception:
            pass


