try:
    _s8_rsb_previous_resolve = MicrodomainResolverDialog.resolve
    def _s8_rsb_resolve(self):
        use_dynamic = bool(getattr(self, 'chk_dynamic_4d', None) is not None and self.chk_dynamic_4d.isChecked())
        if not use_dynamic:
            return _s8_rsb_previous_resolve(self)

        self.refresh_channels()
        preset = _s8_rsb_safe_combo_text(getattr(self, 'cmb_roi_source_preset', None), 'Generic objects')
        output_domain = _s8_rsb_safe_combo_text(getattr(self, 'cmb_output_domain', None), 'Resolved mask')

        signal, signal_ch = self._signal_array()
        signal = _s8_md_as_tzyx(signal)
        signal_source = self.cmb_signal_source.currentText()

        ch = int(self.cmb_structure_ch.currentData() if self.cmb_structure_ch.currentData() is not None else getattr(self.pipeline, 'current_channel', 0))
        source = self.cmb_structure_source.currentText()
        stype = self.cmb_structure.currentText()
        mode = self.cmb_mode.currentText()

        # Presets set biological intent while preserving the same resolver machinery.
        if preset == 'Signal activity':
            ch = int(signal_ch)
            source = signal_source
            arr = signal
            stype = 'Generic'
            mode = 'Network components'
            output_domain = 'Resolved mask'
        else:
            arr = _s8_md_get_array(self.pipeline, ch, source)
            arr = _s8_md_as_tzyx(arr)
            if preset == 'Mitochondria instances':
                stype = 'Mitochondria'; mode = 'Instance split'
            elif preset == 'Mitochondrial territories':
                stype = 'Mitochondria'; mode = 'Network components'
            elif preset == 'F-actin spikes':
                stype = 'F-actin'; mode = 'Skeleton graph + spikes'; output_domain = 'Terminal spikes'
            elif preset == 'F-actin filaments/network':
                stype = 'F-actin'; mode = 'Network components'

        if arr is None:
            QtWidgets.QMessageBox.information(self, 'ROI Source Builder', 'No structure/signal image or mask is available for the selected ROI source.')
            return None

        if mode == 'Auto by structure':
            mode = 'Instance split' if stype == 'Mitochondria' else ('Skeleton graph + spikes' if stype == 'F-actin' else 'Network components')

        prog = StepProgress('ROI Source Builder — dynamic TZYX', maximum=max(1, int(arr.shape[0])) + 4, parent=self)
        resolved = _s8_md_dynamic_resolve_tzyx(
            arr,
            source=source,
            threshold_method=self.cmb_threshold.currentText(),
            manual=float(self.spin_manual.value()),
            sigma=float(self.spin_sigma.value()),
            min_size=int(self.spin_min_size.value()),
            structure_type=stype,
            mode=mode,
            peak_distance=int(self.spin_peak_dist.value()),
            spike_len=int(self.spin_spike_len.value()),
            progress=prog,
        )
        if resolved is None:
            prog.close()
            QtWidgets.QMessageBox.information(self, 'ROI Source Builder', 'Could not build a dynamic ROI source mask.')
            return None

        roi_mask_tzyx = np.asarray(resolved['roi_mask_tzyx'], dtype=bool)

        # Mask-only output: the ROI Source Builder no longer creates a persistent
        # source-label stack. Step 3 receives roi_mask_tzyx directly.

        gate_enabled = bool(getattr(self, 'chk_signal_gate', None) is not None and self.chk_signal_gate.isChecked())
        if output_domain == 'Signal-gated structure' or preset == 'Composite microdomain':
            gate_enabled = True
        gate_relation = _s8_rsb_safe_combo_text(getattr(self, 'cmb_gate_relation', None), 'AND signal-high')
        gate_method = _s8_rsb_safe_combo_text(getattr(self, 'cmb_gate_threshold', None), self.cmb_threshold.currentText())
        gate_manual = float(getattr(self, 'spin_gate_manual', self.spin_manual).value()) if hasattr(self, 'spin_gate_manual') else float(self.spin_manual.value())
        gate_thresholds = []
        signal_mask_voxels = 0
        if gate_enabled:
            if signal is None or signal.shape != roi_mask_tzyx.shape:
                prog.close()
                QtWidgets.QMessageBox.information(self, 'ROI Source Builder', 'Signal gate requested, but the selected signal channel/source does not match the ROI source shape.')
                return None
            sig_gate, gate_thresholds = _s8_rsb_threshold_signal_tzyx(
                signal,
                source=signal_source,
                method=gate_method,
                manual=gate_manual,
                sigma=float(self.spin_sigma.value()),
                min_size=int(self.spin_min_size.value()),
                progress=prog,
            )
            signal_mask_voxels = int(np.count_nonzero(sig_gate)) if sig_gate is not None else 0
            roi_mask_tzyx = _s8_rsb_apply_gate(roi_mask_tzyx, sig_gate, gate_relation)
            if roi_mask_tzyx is None:
                prog.close()
                QtWidgets.QMessageBox.information(self, 'ROI Source Builder', 'Could not apply the composite signal gate.')
                return None
            # Do not relabel the gated ROI-source mask; Step 3 will perform the
            # actual 4D hypervolume labeling from the boolean mask.

        signal_raw = _s8_md_get_array(self.pipeline, int(signal_ch), 'Raw')
        signal_raw = _s8_md_as_tzyx(signal_raw)
        if signal is not None and signal.shape != roi_mask_tzyx.shape:
            signal = None
        if signal_raw is not None and signal_raw.shape != roi_mask_tzyx.shape:
            signal_raw = None

        self._clear_old_layers(ch)
        prog.set_text('Adding ROI source mask layer...')
        mask_layer = self.pipeline.viewer.add_labels(roi_mask_tzyx.astype(np.uint8), name=f'ROI source 4D mask ch{ch}', opacity=0.38, visible=True)
        mask_layer.color = {0:(0,0,0,0), 1:(0.1, 0.9, 0.4, 0.65)}
        self._add_layer(ch, mask_layer)
        prog.step(int(arr.shape[0]) + 2)

        use_for_4d = bool(getattr(self, 'chk_use_for_4d', None) is None or self.chk_use_for_4d.isChecked())
        source_definition = _s8_rsb_definition_from_dialog(
            self,
            preset=preset,
            output_domain=output_domain,
            structure_type=stype,
            mode=mode,
            structure_ch=ch,
            structure_source=source,
            signal_ch=signal_ch,
            signal_source=signal_source,
            use_for_4d=use_for_4d,
            gate_enabled=gate_enabled,
            gate_relation=gate_relation,
            gate_method=gate_method,
            gate_manual=gate_manual,
            threshold_method=self.cmb_threshold.currentText(),
        )

        st = _s8_md_state(self.pipeline, ch)
        st.pop('microdomain_roi_labels_tzyx', None)
        st['microdomain_roi_mask_bool'] = roi_mask_tzyx
        st['microdomain_use_for_4d'] = bool(use_for_4d)
        st['microdomain_signal_tzyx'] = signal
        st['microdomain_signal_raw_tzyx'] = signal_raw
        st['microdomain_signal_channel'] = int(signal_ch)
        st['roi_source_definition'] = source_definition

        summary = dict(resolved.get('summary', {}) or {})
        summary.update({
            'roi_source_voxels': int(np.count_nonzero(roi_mask_tzyx)),
            'roi_source_fraction': float(np.count_nonzero(roi_mask_tzyx) / max(1, roi_mask_tzyx.size)),
            'source_labels_computed': False,
            'signal_gate_enabled': bool(gate_enabled),
            'signal_gate_voxels': int(signal_mask_voxels),
        })
        if gate_thresholds:
            summary['signal_gate_threshold_median'] = float(np.nanmedian(np.asarray(gate_thresholds, dtype=float)))

        result = {
            'structure_type': stype,
            'mode': mode,
            'dynamic': True,
            'use_for_4d_label': bool(use_for_4d),
            'structure_channel': int(ch),
            'structure_source': source,
            'signal_channel': int(signal_ch),
            'signal_source': signal_source,
            'threshold_method': self.cmb_threshold.currentText(),
            'threshold_value': float(summary.get('threshold_median', 0.0)),
            'threshold_values_per_frame': resolved.get('thresholds', []),
            'min_size': int(self.spin_min_size.value()),
            'shape_TZYX': tuple(int(v) for v in roi_mask_tzyx.shape),
            'summary': summary,
            'object_metrics': resolved.get('object_metrics', []) or [],
            'terminal_branches': resolved.get('terminal_branches', []) or [],
            'analysis_mask_source': 'microdomain_roi_mask_bool' if use_for_4d else 'native_mask_bool',
            'roi_source_definition': source_definition,
            'signal_gate_threshold_values_per_frame': gate_thresholds,
        }
        st['microdomain'] = _s8_md_exportable(result)
        self.last_result = st['microdomain']

        lines = [
            f'ROI Source Builder — {preset}',
            f'output domain: {output_domain}',
            f'structure: {stype}, resolver={mode}, channel ch{ch}, source={source}',
            f'T frames masked: {int(roi_mask_tzyx.shape[0])}',
            f'4D Label input: {"ROI source mask" if use_for_4d else "native threshold mask"}',
            f'analysis signal channel: ch{int(signal_ch)} ({signal_source})',
            f'ROI-source voxels: {int(np.count_nonzero(roi_mask_tzyx))}',
        ]
        if gate_enabled:
            lines.append(f'composite gate: {gate_relation}, {gate_method} on ch{int(signal_ch)}')
        for k, v in sorted(summary.items()):
            if isinstance(v, (list, tuple, dict)):
                continue
            try:
                if isinstance(v, (float, np.floating)):
                    lines.append(f'{k}: {float(v):.5g}')
                else:
                    lines.append(f'{k}: {v}')
            except Exception:
                lines.append(f'{k}: {v}')
        self.summary.setPlainText('\n'.join(lines))
        prog.set_text('Done.')
        prog.step(int(arr.shape[0]) + 4)
        prog.close()
        try:
            if hasattr(self.pipeline, '_activate_channel'):
                self.pipeline._activate_channel(ch)
        except Exception:
            pass
        return None
    MicrodomainResolverDialog.resolve = _s8_rsb_resolve
except Exception as _e:
    print('ROI Source Builder resolve patch skipped:', _e)


