# --- BEGIN PATCH: LOW-RAM CHANNEL_STATE COMPATIBILITY ---
# Narrow fix: low-RAM Step 3 cleanup must handle either historical dict-based
# channel_states or list-based channel_states without changing 4D ROI assembly.
def _s8_channel_states_items(panel):
    states = getattr(panel, 'channel_states', {}) or {}
    if isinstance(states, dict):
        return list(states.items())
    if isinstance(states, (list, tuple)):
        return [(int(i), st) for i, st in enumerate(states) if st is not None]
    try:
        return list(states.items())
    except Exception:
        return []

try:
    _S8_PREV_GET_CHANNEL_STATE_COMPAT = PipelinePanel._get_channel_state
except Exception:
    _S8_PREV_GET_CHANNEL_STATE_COMPAT = None

def _s8_get_channel_state_compat(self, ch=None):
    ch = getattr(self, 'current_channel', 0) if ch is None else int(ch)
    states = getattr(self, 'channel_states', None)
    if isinstance(states, dict):
        return states.setdefault(int(ch), _blank_channel_state())
    if isinstance(states, list):
        while len(states) <= int(ch):
            states.append(_blank_channel_state())
        if states[int(ch)] is None:
            states[int(ch)] = _blank_channel_state()
        return states[int(ch)]
    if isinstance(states, tuple):
        try:
            return states[int(ch)]
        except Exception:
            pass
    if _S8_PREV_GET_CHANNEL_STATE_COMPAT is not None:
        return _S8_PREV_GET_CHANNEL_STATE_COMPAT(self, ch)
    return _blank_channel_state()

try:
    PipelinePanel._get_channel_state = _s8_get_channel_state_compat
except Exception as _e:
    print('Low-RAM channel-state compatibility install skipped:', _e)

# Replace the low-RAM preparation function so it no longer assumes .items().
def _s8_prepare_for_low_ram_step3(panel):
    if not _s8_low_ram_enabled(panel):
        return
    try:
        active = int(getattr(panel, 'current_channel', 0))
    except Exception:
        active = 0

    # Drop bulky arrays/layers from previously analyzed inactive channels.
    for ch, st in _s8_channel_states_items(panel):
        try:
            ch_i = int(ch)
        except Exception:
            continue
        if ch_i == active or not isinstance(st, dict):
            continue
        if st.get('sites') is not None:
            _s8_release_channel_intermediates(panel, ch_i, preserve_current_display=False)

    # If this active channel is being re-run, clear stale outputs before generating replacements.
    try:
        st = panel._get_channel_state(active)
        if isinstance(st, dict):
            layers = st.setdefault('layers', {})
            for key in ('sel', 'all', 'points'):
                _s8_remove_layer_from_viewer(panel, layers.get(key))
                layers[key] = None
            st['sites'] = None
            st['amp_dict_filt'] = None
            st['amp_dict_raw'] = None
            st['coordination'] = None
            st['propagation'] = None
            st['disp2d_map'] = None
            st['overlaps'] = {}
            st['has_any_overlap'] = set()
        for _ch2, _st2 in _s8_channel_states_items(panel):
            try:
                if isinstance(_st2, dict):
                    _st2.get('overlaps', {}).pop(active, None)
                    _st2['has_any_overlap'] = set()
            except Exception:
                pass
    except Exception as _e:
        print('Low-RAM Step 3 preparation warning:', _e)

    _s8_force_memory_cleanup()
# --- END PATCH: LOW-RAM CHANNEL_STATE COMPATIBILITY ---


