# --- BEGIN PATCH: IMMEDIATE STEP 3 USER FEEDBACK ---
# Narrow UX-only patch: Step 3 can spend time preparing memory / masks before the
# first visible analysis progress dialog. Show immediate dock feedback and disable
# the button so users know the click was accepted. This does not change 4D ROI
# assembly, ROI-source mask use, or low-RAM cleanup behavior.
def _s8_step3_feedback_process_events():
    try:
        app = QtWidgets.QApplication.instance()
        if app is not None:
            app.processEvents()
    except Exception:
        pass


def _s8_step3_feedback_channel_text(panel):
    try:
        if int(getattr(panel, 'n_channels', 1) or 1) > 1:
            return f"channel {int(getattr(panel, 'current_channel', 0))}"
    except Exception:
        pass
    return "current channel"


try:
    _S8_PREV_PIPELINE_INIT_STEP3_FEEDBACK = PipelinePanel.__init__
    def _s8_pipeline_init_step3_feedback(self, viewer):
        _S8_PREV_PIPELINE_INIT_STEP3_FEEDBACK(self, viewer)
        try:
            if not hasattr(self, 'lbl_step3_status') or self.lbl_step3_status is None:
                self.lbl_step3_status = QtWidgets.QLabel('Step 3: idle')
                self.lbl_step3_status.setWordWrap(True)
                self.lbl_step3_status.setStyleSheet('font-size: 9pt; color: #666;')
                try:
                    idx = self.layout().indexOf(self.btn_analyze)
                    self.layout().insertWidget(idx + 1 if idx >= 0 else self.layout().count(), self.lbl_step3_status)
                except Exception:
                    self.layout().addWidget(self.lbl_step3_status)
        except Exception as _e:
            print('Step 3 feedback label install skipped:', _e)
    PipelinePanel.__init__ = _s8_pipeline_init_step3_feedback
except Exception as _e:
    print('Step 3 feedback init patch install skipped:', _e)


try:
    _S8_PREV_DO_ANALYZE_STEP3_FEEDBACK = PipelinePanel.do_analyze
    def _s8_pipeline_do_analyze_step3_feedback(self, *args, **kwargs):
        ch_text = _s8_step3_feedback_channel_text(self)
        btn = getattr(self, 'btn_analyze', None)
        status = getattr(self, 'lbl_step3_status', None)
        old_btn_text = None
        old_enabled = None
        try:
            if btn is not None:
                old_btn_text = str(btn.text())
                old_enabled = bool(btn.isEnabled())
                btn.setEnabled(False)
                btn.setText(f'3) Step 3 running ({ch_text})…')
            if status is not None:
                status.setText(f'Step 3: started for {ch_text}. Preparing memory / ROI source before 4D labeling…')
            try:
                if hasattr(self, 'lbl_channel_status') and self.lbl_channel_status is not None:
                    base = str(self.lbl_channel_status.text())
                    if 'Step 3 running' not in base:
                        self.lbl_channel_status.setText(base + f' | Step 3 running {ch_text}')
            except Exception:
                pass
            _s8_step3_feedback_process_events()
        except Exception:
            pass

        try:
            return _S8_PREV_DO_ANALYZE_STEP3_FEEDBACK(self)
        except Exception:
            try:
                if status is not None:
                    status.setText(f'Step 3: failed for {ch_text}. See traceback in terminal.')
                _s8_step3_feedback_process_events()
            except Exception:
                pass
            raise
        finally:
            try:
                if btn is not None:
                    if old_btn_text is not None:
                        btn.setText(old_btn_text)
                    if old_enabled is not None:
                        btn.setEnabled(old_enabled)
                if status is not None:
                    status.setText(f'Step 3: complete for {ch_text}.')
                if hasattr(self, '_update_channel_status'):
                    self._update_channel_status()
                _s8_step3_feedback_process_events()
            except Exception:
                pass
    PipelinePanel.do_analyze = _s8_pipeline_do_analyze_step3_feedback
except Exception as _e:
    print('Step 3 immediate feedback patch install skipped:', _e)
# --- END PATCH: IMMEDIATE STEP 3 USER FEEDBACK ---


# --- BEGIN PATCH: METADATA-DRIVEN PHYSICAL UNITS ---
# Adds metadata-derived length/time calibration to measurements, PDF graphics, and exported bundles.
# Falls back to pixels/voxels and frames when TIFF/OME/ImageJ metadata are unavailable.
import copy as _s8_units_copy
import xml.etree.ElementTree as _s8_units_ET

_S8_LAST_IMAGE_CALIBRATION = None
_S8_LAST_IMAGE_PATH = None
_S8_CURRENT_EXPORT_CALIBRATION = None
_S8_CALIBRATION_CACHE = {}


def _s8_units_float(x, default=None):
    try:
        if x is None:
            return default
        return float(x)
    except Exception:
        return default


def _s8_unit_clean(unit):
    if unit is None:
        return ''
    u = str(unit).strip()
    u = u.replace('μ', 'µ')
    return u


def _s8_length_factor_to_um(unit):
    u = _s8_unit_clean(unit).lower().replace(' ', '').replace('-', '')
    if u in ('µm', 'um', 'micron', 'microns', 'micrometer', 'micrometers', 'micrometre', 'micrometres'):
        return 1.0
    if u in ('nm', 'nanometer', 'nanometers', 'nanometre', 'nanometres'):
        return 1e-3
    if u in ('mm', 'millimeter', 'millimeters', 'millimetre', 'millimetres'):
        return 1e3
    if u in ('cm', 'centimeter', 'centimeters', 'centimetre', 'centimetres'):
        return 1e4
    if u in ('m', 'meter', 'meters', 'metre', 'metres'):
        return 1e6
    if u in ('inch', 'in', 'inches'):
        return 25400.0
    if u in ('angstrom', 'angstroms', 'å', 'a'):
        return 1e-4
    return None


def _s8_time_factor_to_s(unit):
    u = _s8_unit_clean(unit).lower().replace(' ', '').replace('-', '')
    if u in ('s', 'sec', 'secs', 'second', 'seconds'):
        return 1.0
    if u in ('ms', 'millisecond', 'milliseconds'):
        return 1e-3
    if u in ('µs', 'us', 'microsecond', 'microseconds'):
        return 1e-6
    if u in ('ns', 'nanosecond', 'nanoseconds'):
        return 1e-9
    if u in ('min', 'mins', 'minute', 'minutes'):
        return 60.0
    if u in ('h', 'hr', 'hrs', 'hour', 'hours'):
        return 3600.0
    return None


def _s8_tag_float(tag):
    try:
        val = tag.value
        if isinstance(val, tuple) and len(val) == 2:
            den = float(val[1]) if float(val[1]) != 0 else 1.0
            return float(val[0]) / den
        if hasattr(val, 'numerator') and hasattr(val, 'denominator'):
            return float(val.numerator) / float(val.denominator or 1)
        return float(val)
    except Exception:
        return None


def _s8_default_calibration(source='none'):
    return {
        'scale_x': None, 'scale_y': None, 'scale_z': None, 'scale_t': None,
        'length_unit': 'µm', 'time_unit': 's',
        'display_length_unit': 'µm', 'display_time_unit': 's',
        'source': source,
        'has_xy': False, 'has_z': False, 'has_xyz': False, 'has_time': False,
        'mode': 'pixel_frame',
    }


def _s8_finalize_calibration(cal):
    cal = dict(cal or _s8_default_calibration())
    for key in ('scale_x', 'scale_y', 'scale_z', 'scale_t'):
        val = _s8_units_float(cal.get(key), None)
        cal[key] = val if (val is not None and np.isfinite(val) and val > 0) else None
    cal['display_length_unit'] = cal.get('display_length_unit') or cal.get('length_unit') or 'µm'
    cal['display_time_unit'] = cal.get('display_time_unit') or cal.get('time_unit') or 's'
    cal['has_xy'] = bool(cal.get('scale_x') is not None and cal.get('scale_y') is not None)
    cal['has_z'] = bool(cal.get('scale_z') is not None)
    cal['has_xyz'] = bool(cal.get('has_xy') and cal.get('has_z'))
    cal['has_time'] = bool(cal.get('scale_t') is not None)
    cal['mode'] = 'physical' if (cal['has_xy'] or cal['has_time']) else 'pixel_frame'
    return cal


def _s8_set_length_scale(cal, axis_key, value, unit, source, sources):
    val = _s8_units_float(value, None)
    factor = _s8_length_factor_to_um(unit)
    if val is None or factor is None or val <= 0:
        return False
    cal[axis_key] = float(val * factor)
    cal['length_unit'] = 'µm'
    cal['display_length_unit'] = 'µm'
    if source and source not in sources:
        sources.append(source)
    return True


def _s8_set_time_scale(cal, value, unit, source, sources):
    val = _s8_units_float(value, None)
    factor = _s8_time_factor_to_s(unit)
    if val is None or factor is None or val <= 0:
        return False
    cal['scale_t'] = float(val * factor)
    cal['time_unit'] = 's'
    cal['display_time_unit'] = 's'
    if source and source not in sources:
        sources.append(source)
    return True


def _s8_extract_tiff_calibration(img_path: Path):
    path = str(Path(img_path))
    if path in _S8_CALIBRATION_CACHE:
        return _s8_units_copy.deepcopy(_S8_CALIBRATION_CACHE[path])
    cal = _s8_default_calibration()
    sources = []
    try:
        with tiff.TiffFile(path) as tif:
            # OME-XML physical units.
            try:
                ome = getattr(tif, 'ome_metadata', None)
                if ome:
                    root = _s8_units_ET.fromstring(ome)
                    pixels = None
                    for elem in root.iter():
                        if str(elem.tag).split('}')[-1] == 'Pixels':
                            pixels = elem
                            break
                    if pixels is not None:
                        attrs = pixels.attrib
                        if cal.get('scale_x') is None:
                            _s8_set_length_scale(cal, 'scale_x', attrs.get('PhysicalSizeX'), attrs.get('PhysicalSizeXUnit', 'µm'), 'OME', sources)
                        if cal.get('scale_y') is None:
                            _s8_set_length_scale(cal, 'scale_y', attrs.get('PhysicalSizeY'), attrs.get('PhysicalSizeYUnit', 'µm'), 'OME', sources)
                        if cal.get('scale_z') is None:
                            _s8_set_length_scale(cal, 'scale_z', attrs.get('PhysicalSizeZ'), attrs.get('PhysicalSizeZUnit', 'µm'), 'OME', sources)
                        if cal.get('scale_t') is None:
                            _s8_set_time_scale(cal, attrs.get('TimeIncrement'), attrs.get('TimeIncrementUnit', 's'), 'OME', sources)
                        if cal.get('scale_t') is None:
                            # Some OME files store per-plane DeltaT instead of a Pixels TimeIncrement.
                            dts = []
                            for elem in root.iter():
                                if str(elem.tag).split('}')[-1] == 'Plane' and elem.attrib.get('DeltaT') is not None:
                                    dt = _s8_units_float(elem.attrib.get('DeltaT'), None)
                                    if dt is not None:
                                        dts.append((dt, elem.attrib.get('DeltaTUnit', 's')))
                            if len(dts) >= 2:
                                d0, u0 = dts[0]
                                d1, u1 = dts[1]
                                _s8_set_time_scale(cal, abs(d1 - d0), u1 or u0 or 's', 'OME Plane DeltaT', sources)
            except Exception:
                pass

            # ImageJ metadata: z spacing and frame interval are common here.
            try:
                ij = getattr(tif, 'imagej_metadata', None) or {}
                ij_unit = ij.get('unit') or ij.get('Unit') or ij.get('spacing_unit') or 'µm'
                if cal.get('scale_z') is None and ij.get('spacing') is not None:
                    _s8_set_length_scale(cal, 'scale_z', ij.get('spacing'), ij_unit, 'ImageJ spacing', sources)
                if cal.get('scale_t') is None:
                    tunit = ij.get('timeunit') or ij.get('TimeUnit') or ij.get('time_unit') or 's'
                    if ij.get('finterval') is not None:
                        _s8_set_time_scale(cal, ij.get('finterval'), tunit, 'ImageJ frame interval', sources)
                    elif ij.get('fps') is not None:
                        fps = _s8_units_float(ij.get('fps'), None)
                        if fps is not None and fps > 0:
                            _s8_set_time_scale(cal, 1.0 / fps, 's', 'ImageJ fps', sources)
            except Exception:
                pass

            # TIFF resolution tags can provide X/Y pixel size when unit is inch or centimeter.
            try:
                page0 = tif.pages[0]
                tags = page0.tags
                ru_tag = tags.get('ResolutionUnit')
                ru = ru_tag.value if ru_tag is not None else None
                ru_name = str(ru).lower()
                ru_val = int(ru) if isinstance(ru, (int, np.integer)) else None
                unit_size_um = None
                if ru_val == 2 or 'inch' in ru_name:
                    unit_size_um = 25400.0
                elif ru_val == 3 or 'centimeter' in ru_name or 'centimetre' in ru_name:
                    unit_size_um = 10000.0
                if unit_size_um is not None:
                    xr = _s8_tag_float(tags.get('XResolution')) if tags.get('XResolution') is not None else None
                    yr = _s8_tag_float(tags.get('YResolution')) if tags.get('YResolution') is not None else None
                    if cal.get('scale_x') is None and xr is not None and xr > 0 and abs(xr - 1.0) > 1e-12:
                        cal['scale_x'] = float(unit_size_um / xr)
                        if 'TIFF resolution' not in sources:
                            sources.append('TIFF resolution')
                    if cal.get('scale_y') is None and yr is not None and yr > 0 and abs(yr - 1.0) > 1e-12:
                        cal['scale_y'] = float(unit_size_um / yr)
                        if 'TIFF resolution' not in sources:
                            sources.append('TIFF resolution')
            except Exception:
                pass
    except Exception:
        pass
    cal['source'] = ', '.join(sources) if sources else 'none'
    cal = _s8_finalize_calibration(cal)
    _S8_CALIBRATION_CACHE[path] = _s8_units_copy.deepcopy(cal)
    return cal


def _s8_calibration_summary(cal):
    cal = _s8_finalize_calibration(cal)
    parts = []
    if cal.get('has_xy'):
        if abs(float(cal['scale_x']) - float(cal['scale_y'])) < 1e-12:
            parts.append(f"XY={cal['scale_x']:.6g} {cal['display_length_unit']}/px")
        else:
            parts.append(f"X={cal['scale_x']:.6g}, Y={cal['scale_y']:.6g} {cal['display_length_unit']}/px")
    else:
        parts.append('XY=pixels')
    if cal.get('scale_z') is not None:
        parts.append(f"Z={cal['scale_z']:.6g} {cal['display_length_unit']}/slice")
    else:
        parts.append('Z=slices')
    if cal.get('scale_t') is not None:
        parts.append(f"T={cal['scale_t']:.6g} {cal['display_time_unit']}/frame")
    else:
        parts.append('T=frames')
    src = cal.get('source') or 'none'
    return '; '.join(parts) + f" | source={src}"


def _s8_get_panel_calibration(panel, ch=None):
    if panel is None:
        return _s8_finalize_calibration(_S8_LAST_IMAGE_CALIBRATION)
    try:
        if ch is None:
            ch = int(getattr(panel, 'current_channel', 0))
        if hasattr(panel, '_get_channel_state'):
            st = panel._get_channel_state(int(ch))
            if isinstance(st, dict) and st.get('calibration') is not None:
                return _s8_finalize_calibration(st.get('calibration'))
    except Exception:
        pass
    for attr in ('s8_calibration', 'image_calibration', 'calibration'):
        try:
            cal = getattr(panel, attr, None)
            if cal is not None:
                return _s8_finalize_calibration(cal)
        except Exception:
            pass
    return _s8_finalize_calibration(_S8_LAST_IMAGE_CALIBRATION)


def _s8_calibration_from_meta(meta=None):
    meta = meta or {}
    cal = meta.get('calibration') or meta.get('image_calibration') or meta.get('physical_units')
    if cal is None:
        cal = _S8_CURRENT_EXPORT_CALIBRATION or _S8_LAST_IMAGE_CALIBRATION
    return _s8_finalize_calibration(cal)


def _s8_time_axis(n, cal):
    cal = _s8_finalize_calibration(cal)
    n = int(max(0, n))
    if cal.get('scale_t') is not None:
        return np.arange(n, dtype=float) * float(cal['scale_t']), f"time ({cal['display_time_unit']})"
    return np.arange(n, dtype=float), 'time (frame)'


def _s8_time_value(frame_or_count, cal):
    cal = _s8_finalize_calibration(cal)
    val = float(frame_or_count)
    if cal.get('scale_t') is not None:
        return val * float(cal['scale_t']), cal['display_time_unit']
    return val, 'frames'


def _s8_extent_scale_and_label(meta=None, cal=None):
    meta = meta or {}
    cal = _s8_finalize_calibration(cal or _s8_calibration_from_meta(meta))
    shape = meta.get('shape_TZYX', None) or (0, 0, 0, 0)
    try:
        Z = int(shape[1])
    except Exception:
        Z = 0
    lu = cal.get('display_length_unit', 'µm')
    if Z <= 1 and cal.get('has_xy'):
        return float(cal['scale_x']) * float(cal['scale_y']), f"{lu}²", 'area'
    if Z > 1 and cal.get('has_xyz'):
        return float(cal['scale_x']) * float(cal['scale_y']) * float(cal['scale_z']), f"{lu}³", 'volume'
    return 1.0, 'pixels' if Z <= 1 else 'voxels', 'area' if Z <= 1 else 'volume'


def _s8_scale_extent_values(values, meta=None, cal=None):
    scale, unit, kind = _s8_extent_scale_and_label(meta, cal)
    return np.asarray(values, dtype=float) * float(scale), unit, kind


def _s8_xy_available(cal):
    cal = _s8_finalize_calibration(cal)
    return bool(cal.get('scale_x') is not None and cal.get('scale_y') is not None)


def _s8_xyz_available(cal):
    cal = _s8_finalize_calibration(cal)
    return bool(cal.get('scale_x') is not None and cal.get('scale_y') is not None and cal.get('scale_z') is not None)


def _s8_len_unit(cal):
    return _s8_finalize_calibration(cal).get('display_length_unit', 'µm')


def _s8_time_unit(cal):
    return _s8_finalize_calibration(cal).get('display_time_unit', 's')


def _s8_format_value_with_raw(value, unit, raw_value, raw_unit):
    try:
        if unit == raw_unit:
            return f"{float(raw_value):.4g} {raw_unit}"
        return f"{float(value):.4g} {unit} ({float(raw_value):.4g} {raw_unit})"
    except Exception:
        return f"{raw_value} {raw_unit}"


def _s8_metrics_for_display(metrics, meta=None):
    metrics = dict(metrics or {})
    cal = _s8_calibration_from_meta(meta)
    out = {k: np.asarray(v).copy() for k, v in metrics.items()}
    if cal.get('scale_t') is not None:
        for key in ('lifetime', 'first_time'):
            if key in out:
                out[key] = np.asarray(out[key], dtype=float) * float(cal['scale_t'])
    if 'max_area' in out:
        out['max_area'] = _s8_scale_extent_values(out['max_area'], meta, cal)[0]
    return out


def _s8_enrich_displacements(combined, cal=None):
    combined = combined or {}
    meta = combined.get('metadata', {}) or {}
    cal = _s8_finalize_calibration(cal or _s8_calibration_from_meta(meta))
    disp = combined.setdefault('displacements', {})
    d2 = disp.get('centroid_start_end_2d') or {}
    if d2 and _s8_xy_available(cal):
        sx, sy = float(cal['scale_x']), float(cal['scale_y'])
        lu = _s8_len_unit(cal)
        converted = {}
        for rid, d in d2.items():
            dd = dict(d)
            dx = float(d.get('dx', 0.0)) * sx
            dy = float(d.get('dy', 0.0)) * sy
            dd.update({
                'x0_length': float(d.get('x0', 0.0)) * sx,
                'y0_length': float(d.get('y0', 0.0)) * sy,
                'x1_length': float(d.get('x1', 0.0)) * sx,
                'y1_length': float(d.get('y1', 0.0)) * sy,
                'dx_length': dx,
                'dy_length': dy,
                'length_physical': float(np.hypot(dx, dy)),
                'length_unit': lu,
            })
            converted[int(rid)] = dd
        disp['centroid_start_end_2d_physical'] = converted
    d3 = disp.get('centroid_start_end_3d') or {}
    if d3 and _s8_xyz_available(cal):
        sx, sy, sz = float(cal['scale_x']), float(cal['scale_y']), float(cal['scale_z'])
        lu = _s8_len_unit(cal)
        converted = {}
        for rid, d in d3.items():
            dd = dict(d)
            dx = float(d.get('dx', 0.0)) * sx
            dy = float(d.get('dy', 0.0)) * sy
            dz = float(d.get('dz', 0.0)) * sz
            dd.update({
                'x0_length': float(d.get('x0', 0.0)) * sx,
                'y0_length': float(d.get('y0', 0.0)) * sy,
                'z0_length': float(d.get('z0', 0.0)) * sz,
                'x1_length': float(d.get('x1', 0.0)) * sx,
                'y1_length': float(d.get('y1', 0.0)) * sy,
                'z1_length': float(d.get('z1', 0.0)) * sz,
                'dx_length': dx,
                'dy_length': dy,
                'dz_length': dz,
                'length3d_physical': float(np.sqrt(dx * dx + dy * dy + dz * dz)),
                'length_unit': lu,
            })
            converted[int(rid)] = dd
        disp['centroid_start_end_3d_physical'] = converted


def _s8_physical_propagation_from_table(vel, cal=None):
    vel = dict(vel or {})
    cal = _s8_finalize_calibration(cal)
    if not (_s8_xy_available(cal) and cal.get('scale_t') is not None):
        return {}
    try:
        tbl = vel.get('table', {}) or {}
        xs = np.asarray(tbl.get('x', []), dtype=float) * float(cal['scale_x'])
        ys = np.asarray(tbl.get('y', []), dtype=float) * float(cal['scale_y'])
        ts = np.asarray(tbl.get('t_onset', []), dtype=float) * float(cal['scale_t'])
        good = np.isfinite(xs) & np.isfinite(ys) & np.isfinite(ts)
        xs, ys, ts = xs[good], ys[good], ts[good]
        if len(ts) < 3:
            return {}
        A = np.column_stack([xs, ys, np.ones_like(xs)])
        coeffs, *_ = np.linalg.lstsq(A, ts, rcond=None)
        a, b, c = coeffs
        speed = 1.0 / max(1e-12, math.hypot(float(a), float(b)))
        angle = math.atan2(float(b), float(a))
        return {
            'speed_length_per_time': float(speed),
            'speed_unit': f"{_s8_len_unit(cal)}/{_s8_time_unit(cal)}",
            'angle_radians': float(angle),
            'coeffs_time_per_length': (float(a), float(b), float(c)),
            'n_points': int(len(ts)),
        }
    except Exception:
        return {}


def _s8_units_enrich_combined(combined, cal=None):
    if not isinstance(combined, dict):
        return combined
    if 'metadata' not in combined or 'rois' not in combined:
        return combined
    meta = combined.setdefault('metadata', {})
    cal = _s8_finalize_calibration(cal or meta.get('calibration') or _S8_CURRENT_EXPORT_CALIBRATION or _S8_LAST_IMAGE_CALIBRATION)
    meta['calibration'] = _s8_units_copy.deepcopy(cal)
    meta['measurement_unit_mode'] = cal.get('mode', 'pixel_frame')
    meta['measurement_units_summary'] = _s8_calibration_summary(cal)
    scale_extent, extent_unit, extent_kind = _s8_extent_scale_and_label(meta, cal)
    meta['measurement_units'] = {
        'time': _s8_time_unit(cal) if cal.get('has_time') else 'frames',
        'length': _s8_len_unit(cal) if cal.get('has_xy') else 'pixels',
        'z': _s8_len_unit(cal) if cal.get('has_z') else 'slices',
        'extent': extent_unit,
        'extent_kind': extent_kind,
    }
    rois = combined.get('rois', {}) or {}
    roi_metrics = {}
    for rid, arr in (rois.items() if hasattr(rois, 'items') else []):
        try:
            meta_roi = arr[13] if len(arr) > 13 and isinstance(arr[13], dict) else {}
            duration_raw = float(meta_roi.get('lifetime_frames', arr[3] if len(arr) > 3 else 0))
            first_raw = float(arr[6] if len(arr) > 6 else meta_roi.get('first_time', 0))
            max_extent_raw = float(arr[1] if len(arr) > 1 else 0.0)
            dur_val, dur_unit = _s8_time_value(duration_raw, cal)
            start_val, start_unit = _s8_time_value(first_raw, cal)
            roi_metrics[int(rid)] = {
                'duration': float(dur_val),
                'duration_unit': dur_unit,
                'duration_frames': int(round(duration_raw)),
                'start_time': float(start_val),
                'start_time_unit': start_unit,
                'start_frame': int(round(first_raw)),
                extent_kind: float(max_extent_raw * scale_extent),
                f'{extent_kind}_unit': extent_unit,
                'max_voxels_or_pixels': float(max_extent_raw),
            }
        except Exception:
            continue
    combined['measurements'] = {
        'units': meta.get('measurement_units', {}),
        'calibration': _s8_units_copy.deepcopy(cal),
        'roi_metrics': roi_metrics,
    }
    _s8_enrich_displacements(combined, cal)
    prop_phys = _s8_physical_propagation_from_table(combined.get('propagation', {}) or {}, cal)
    if prop_phys:
        combined['propagation_physical'] = prop_phys
    fp = combined.get('fingerprint', {}) or {}
    if isinstance(fp, dict) and fp:
        fp_phys = {}
        if cal.get('scale_t') is not None:
            for key in ('mean_lifetime', 'median_lifetime', 'mean_first_time'):
                if key in fp:
                    fp_phys[key] = float(fp[key]) * float(cal['scale_t'])
            if 'roi_density_per_frame' in fp:
                fp_phys['roi_density_per_time'] = float(fp['roi_density_per_frame']) / float(cal['scale_t'])
        if extent_unit not in ('pixels', 'voxels'):
            for key in ('mean_max_area', 'median_max_area'):
                if key in fp:
                    fp_phys[key] = float(fp[key]) * float(scale_extent)
        if _s8_xy_available(cal) and 'mean_disp_len2d' in fp:
            # Mean displacement length is recomputed from the converted map when possible.
            d2p = (combined.get('displacements', {}) or {}).get('centroid_start_end_2d_physical', {}) or {}
            vals = [float(d.get('length_physical', np.nan)) for d in d2p.values()]
            vals = [v for v in vals if np.isfinite(v)]
            if vals:
                fp_phys['mean_disp_len2d'] = float(np.mean(vals))
                fp_phys['median_disp_len2d'] = float(np.median(vals))
        if prop_phys:
            fp_phys['propagation_speed'] = float(prop_phys.get('speed_length_per_time', 0.0))
        if fp_phys:
            combined['fingerprint_physical'] = fp_phys
            combined['fingerprint_physical_units'] = {
                'time': _s8_time_unit(cal) if cal.get('has_time') else 'frames',
                'length': _s8_len_unit(cal) if cal.get('has_xy') else 'pixels',
                'extent': extent_unit,
                'speed': prop_phys.get('speed_unit') if prop_phys else None,
            }
    return combined


# Cache calibration whenever a TIFF is read through either reader.
try:
    _S8_PREV_READ_TO_TCZYX_UNITS = read_to_TCZYX
    def read_to_TCZYX(img_path: Path):
        global _S8_LAST_IMAGE_CALIBRATION, _S8_LAST_IMAGE_PATH
        try:
            _S8_LAST_IMAGE_PATH = str(Path(img_path))
            _S8_LAST_IMAGE_CALIBRATION = _s8_extract_tiff_calibration(Path(img_path))
        except Exception:
            _S8_LAST_IMAGE_CALIBRATION = _s8_default_calibration()
        return _S8_PREV_READ_TO_TCZYX_UNITS(img_path)
except Exception:
    pass

try:
    _S8_PREV_READ_TO_TZYX_UNITS = read_to_TZYX
    def read_to_TZYX(img_path: Path):
        global _S8_LAST_IMAGE_CALIBRATION, _S8_LAST_IMAGE_PATH
        try:
            _S8_LAST_IMAGE_PATH = str(Path(img_path))
            _S8_LAST_IMAGE_CALIBRATION = _s8_extract_tiff_calibration(Path(img_path))
        except Exception:
            _S8_LAST_IMAGE_CALIBRATION = _s8_default_calibration()
        return _S8_PREV_READ_TO_TZYX_UNITS(img_path)
except Exception:
    pass


# Panel UI/status and channel-state attachment.
try:
    _S8_PREV_PIPELINE_INIT_UNITS = PipelinePanel.__init__
    def _s8_pipeline_init_units(self, viewer):
        _S8_PREV_PIPELINE_INIT_UNITS(self, viewer)
        try:
            self.s8_calibration = _s8_default_calibration()
            self.lbl_units = QtWidgets.QLabel('Units: pixels/frames')
            self.lbl_units.setWordWrap(True)
            # Keep the label near the load/channel controls without disturbing the main workflow.
            try:
                self.layout().insertWidget(2, self.lbl_units)
            except Exception:
                self.layout().addWidget(self.lbl_units)
        except Exception:
            pass
    PipelinePanel.__init__ = _s8_pipeline_init_units
except Exception as _e:
    print('Physical-units panel init patch skipped:', _e)


def _s8_attach_calibration_to_panel(panel, cal=None):
    cal = _s8_finalize_calibration(cal or _S8_LAST_IMAGE_CALIBRATION)
    try:
        panel.s8_calibration = cal
    except Exception:
        pass
    try:
        for _ch, st in (getattr(panel, 'channel_states', {}) or {}).items():
            if isinstance(st, dict):
                st['calibration'] = _s8_units_copy.deepcopy(cal)
                for lyr in (st.get('layers', {}) or {}).values():
                    if lyr is not None:
                        try:
                            md = dict(getattr(lyr, 'metadata', {}) or {})
                            md['s8_calibration'] = _s8_units_copy.deepcopy(cal)
                            lyr.metadata = md
                        except Exception:
                            pass
    except Exception:
        pass
    try:
        txt = 'Units: ' + (_s8_calibration_summary(cal) if cal.get('mode') == 'physical' else 'pixels/frames')
        if getattr(panel, 'lbl_units', None) is not None:
            panel.lbl_units.setText(txt)
    except Exception:
        pass
    return cal

try:
    _S8_PREV_LOAD_IMAGE_UNITS = PipelinePanel.load_image
    def _s8_load_image_units(self, *args, **kwargs):
        # Qt clicked() may pass a checked-state boolean, but earlier S8 load_image
        # wrappers in this file intentionally accept only self. Ignore signal args
        # so metadata calibration does not break the existing load chain.
        out = _S8_PREV_LOAD_IMAGE_UNITS(self)
        try:
            _s8_attach_calibration_to_panel(self, _S8_LAST_IMAGE_CALIBRATION)
        except Exception:
            pass
        return out
    PipelinePanel.load_image = _s8_load_image_units
except Exception as _e:
    print('Physical-units load-image patch skipped:', _e)

try:
    _S8_PREV_ACTIVATE_CHANNEL_UNITS = PipelinePanel._activate_channel
    def _s8_activate_channel_units(self, ch):
        out = _S8_PREV_ACTIVATE_CHANNEL_UNITS(self, ch)
        try:
            cal = _s8_get_panel_calibration(self, ch)
            if getattr(self, 'lbl_units', None) is not None:
                self.lbl_units.setText('Units: ' + (_s8_calibration_summary(cal) if cal.get('mode') == 'physical' else 'pixels/frames'))
        except Exception:
            pass
        return out
    PipelinePanel._activate_channel = _s8_activate_channel_units
except Exception:
    pass


# ROI-side measurements/graphics.
try:
    _S8_PREV_ROI_SET_OUTPUTS_UNITS = ROIPanel.set_analysis_outputs
    def _s8_roi_set_outputs_units(self, *args, **kwargs):
        try:
            cal = None
            pp = getattr(self, 'pipeline_panel', None)
            if pp is not None:
                cal = _s8_get_panel_calibration(pp, getattr(self, 'current_channel', 0))
            self.calibration = _s8_finalize_calibration(cal or _S8_LAST_IMAGE_CALIBRATION)
            if getattr(self, 'plots', None) is not None:
                self.plots.calibration = self.calibration
        except Exception:
            pass
        out = _S8_PREV_ROI_SET_OUTPUTS_UNITS(self, *args, **kwargs)
        try:
            cal = getattr(self, 'calibration', _s8_default_calibration())
            if getattr(self, 'plots', None) is not None:
                self.plots.calibration = cal
            prop = kwargs.get('propag', None)
            if prop is None and len(args) >= 7:
                prop = args[6]
            prop_phys = _s8_physical_propagation_from_table(prop or {}, cal)
            if prop_phys and getattr(self, 'propag_label', None) is not None:
                self.propag_label.setText(
                    f"Propagation — speed: {prop_phys['speed_length_per_time']:.4g} {prop_phys['speed_unit']} | "
                    f"angle: {prop_phys.get('angle_radians', 0.0):.2f} rad"
                )
        except Exception:
            pass
        return out
    ROIPanel.set_analysis_outputs = _s8_roi_set_outputs_units
except Exception as _e:
    print('Physical-units ROI output patch skipped:', _e)

try:
    _S8_PREV_ROIPLOTS_UPDATE_DATA_UNITS = ROIPlots.update_data
    def _s8_roiplots_update_data_units(self, area_t, amp_filt, amp_raw, current_t=None, labels=None):
        cal = _s8_finalize_calibration(getattr(self, 'calibration', None))
        # Reimplement the existing chart with scaled time/extent axes, preserving behavior otherwise.
        import numpy as _np
        def _tolist(x):
            if isinstance(x, (list, tuple)):
                return [_np.asarray(xx) if xx is not None else None for xx in x]
            if x is None:
                return []
            return [_np.asarray(x)]
        area_list = _tolist(area_t); filt_list = _tolist(amp_filt); raw_list = _tolist(amp_raw)
        n_series = max(len(area_list), len(filt_list), len(raw_list))
        if n_series == 0:
            self.clear(); return
        def _padlist(lst, n):
            out = list(lst)
            while len(out) < n:
                out.append(None)
            return out
        area_list = _padlist(area_list, n_series); filt_list = _padlist(filt_list, n_series); raw_list = _padlist(raw_list, n_series)
        if labels is None:
            labels = [f"ROI {i+1}" for i in range(n_series)]
        else:
            labels = list(labels)
            while len(labels) < n_series:
                labels.append(f"ROI {len(labels)+1}")
            labels = labels[:n_series]
        T = 0
        for lst in (area_list, filt_list, raw_list):
            for a in lst:
                if a is not None:
                    T = max(T, len(a))
        self.T = T if T > 0 else None
        x, xlab = _s8_time_axis(T, cal)
        t_cursor = (float(current_t) * float(cal['scale_t'])) if (current_t is not None and cal.get('scale_t') is not None) else current_t
        extent_scale, extent_unit, extent_kind = _s8_extent_scale_and_label({'shape_TZYX': (T, getattr(self, 'Z', 0), 0, 0)}, cal)
        # If ROIPlots does not know Z, infer 2D/3D from the parent if available; otherwise keep legacy voxels.
        try:
            parent = self.parent()
            if parent is not None:
                extent_scale, extent_unit, extent_kind = _s8_extent_scale_and_label({'shape_TZYX': (parent.T, parent.Z, parent.Y, parent.X)}, cal)
        except Exception:
            pass
        self.ax_vol.clear(); ymax_v = 1.0
        for arr_a, lab in zip(area_list, labels):
            if arr_a is None:
                continue
            aa = _np.asarray(arr_a, dtype=float) * extent_scale
            xx = x[:len(aa)] if len(x) >= len(aa) else _np.arange(len(aa), dtype=float)
            self.ax_vol.plot(xx, aa, lw=1.5, label=lab)
            if _np.isfinite(aa).any():
                ymax_v = max(ymax_v, float(_np.nanmax(aa)))
        self.ax_vol.set_title(f"{extent_kind.title()} ({extent_unit}) vs time")
        self.ax_vol.set_xlabel(xlab); self.ax_vol.set_ylabel(extent_unit)
        if len(x) > 1:
            self.ax_vol.set_xlim(float(x[0]), float(x[-1]))
        else:
            self.ax_vol.set_xlim(0, max(T - 1, 1))
        self.ax_vol.set_ylim(0, max(1.0, ymax_v))
        if n_series > 1:
            self.ax_vol.legend(loc='upper right', fontsize=8, frameon=False)
        if t_cursor is not None:
            self._t_cursor_top = self.ax_vol.axvline(t_cursor, ls='--', lw=1)
        self.ax_int.clear(); ymin_i, ymax_i = None, None
        for idx in range(n_series):
            fl = filt_list[idx]; rl = raw_list[idx]; base_label = labels[idx]
            if fl is not None:
                ff = _np.asarray(fl, dtype=float); xx = x[:len(ff)] if len(x) >= len(ff) else _np.arange(len(ff), dtype=float)
                self.ax_int.plot(xx, ff, lw=1.5, label=f"{base_label} (filtered)")
                if ff.size and _np.isfinite(ff).any():
                    lo, hi = float(_np.nanmin(ff)), float(_np.nanmax(ff))
                    if _np.isfinite(lo) and _np.isfinite(hi):
                        ymin_i = lo if ymin_i is None else min(ymin_i, lo); ymax_i = hi if ymax_i is None else max(ymax_i, hi)
            if rl is not None:
                rr = _np.asarray(rl, dtype=float); xx = x[:len(rr)] if len(x) >= len(rr) else _np.arange(len(rr), dtype=float)
                self.ax_int.plot(xx, rr, lw=1.0, ls='--', label=f"{base_label} (raw)")
                if rr.size and _np.isfinite(rr).any():
                    lo, hi = float(_np.nanmin(rr)), float(_np.nanmax(rr))
                    if _np.isfinite(lo) and _np.isfinite(hi):
                        ymin_i = lo if ymin_i is None else min(ymin_i, lo); ymax_i = hi if ymax_i is None else max(ymax_i, hi)
        self.ax_int.set_title('Mean Intensity vs time')
        self.ax_int.set_xlabel(xlab); self.ax_int.set_ylabel('intensity (a.u.)')
        if len(x) > 1:
            self.ax_int.set_xlim(float(x[0]), float(x[-1]))
        else:
            self.ax_int.set_xlim(0, max(T - 1, 1))
        if ymin_i is None or ymax_i is None or not _np.isfinite(ymin_i) or not _np.isfinite(ymax_i):
            ymin_i, ymax_i = 0.0, 1.0
        span_i = float(ymax_i - ymin_i)
        if not np.isfinite(span_i) or span_i <= 1e-12:
            # Perfectly flat traces need a finite display range; plotting only.
            center_i = float(ymin_i) if np.isfinite(ymin_i) else 1.0
            pad = max(0.05 * abs(center_i), 0.05)
        else:
            pad = 0.05 * span_i
        self.ax_int.set_ylim(ymin_i - pad, ymax_i + pad)
        self.ax_int.legend(loc='upper right', fontsize=8, frameon=False)
        if t_cursor is not None:
            self._t_cursor_bot = self.ax_int.axvline(t_cursor, ls='--', lw=1, color='gray')
        self.canvas.draw_idle()
    ROIPlots.update_data = _s8_roiplots_update_data_units

    _S8_PREV_ROIPLOTS_UPDATE_CURSOR_UNITS = ROIPlots.update_cursor
    def _s8_roiplots_update_cursor_units(self, current_t):
        cal = _s8_finalize_calibration(getattr(self, 'calibration', None))
        val = float(current_t) * float(cal['scale_t']) if cal.get('scale_t') is not None else current_t
        if self._t_cursor_top is not None:
            self._t_cursor_top.set_xdata([val, val])
        if self._t_cursor_bot is not None:
            self._t_cursor_bot.set_xdata([val, val])
        self.canvas.draw_idle()
    ROIPlots.update_cursor = _s8_roiplots_update_cursor_units
except Exception as _e:
    print('Physical-units ROI plots patch skipped:', _e)

try:
    def _s8_update_stats_with_units(self):
        if self.current_roi is None or self.sites is None:
            self.stats.setPlainText('')
            return
        cal = _s8_finalize_calibration(getattr(self, 'calibration', None))
        arr = self.sites[self.current_roi]
        duration_frames = int(arr[3]) if len(arr) > 3 else 0
        start_frame = int(arr[6]) if len(arr) > 6 else 0
        dur_val, dur_unit = _s8_time_value(duration_frames, cal)
        start_val, start_unit = _s8_time_value(start_frame, cal)
        amp_series = self._get_roi_amp_series_filtered(self.current_roi)
        amp_max = float(np.nanmax(amp_series)) if np.size(amp_series) else 0.0
        t_now = int(self.viewer.dims.current_step[0])
        amp_now = float(amp_series[t_now]) if (np.size(amp_series) and 0 <= t_now < len(amp_series)) else np.nan
        cname = self.class_of_roi.get(int(self.current_roi), (0, 'Unclassified'))[1]
        members = ', '.join(getattr(self, 'ontology_membership', {}).get(int(self.current_roi), [])) or 'None'
        area_t, _, _ = self._get_roi_area_metrics(self.current_roi)
        extent_scale, extent_unit, extent_kind = _s8_extent_scale_and_label({'shape_TZYX': (self.T, self.Z, self.Y, self.X)}, cal)
        max_extent = float(np.nanmax(np.asarray(area_t, dtype=float))) * float(extent_scale) if np.size(area_t) else 0.0
        raw_extent = float(np.nanmax(np.asarray(area_t, dtype=float))) if np.size(area_t) else 0.0
        lines = [
            f"ROI {self.current_roi}",
            f"Primary ontology: {cname}",
            f"Ontology memberships: {members}",
            f"Duration: {_s8_format_value_with_raw(dur_val, dur_unit, duration_frames, 'frames')}",
            f"Start: {_s8_format_value_with_raw(start_val, start_unit, start_frame, 'frame')}",
            f"Max {extent_kind}: {_s8_format_value_with_raw(max_extent, extent_unit, raw_extent, 'voxels' if self.Z > 1 else 'pixels')}",
            f"Filtered Amp (max): {amp_max:.3f}",
            f"Filtered Amp (t={t_now}): {amp_now:.3f}",
        ]
        try:
            d = (getattr(self, 'disp2d_map', {}) or {}).get(int(self.current_roi))
            if d and _s8_xy_available(cal):
                dx = float(d.get('dx', 0.0)) * float(cal['scale_x'])
                dy = float(d.get('dy', 0.0)) * float(cal['scale_y'])
                lines.insert(6, f"2D displacement: {float(np.hypot(dx, dy)):.4g} {_s8_len_unit(cal)} ({float(d.get('length', 0.0)):.4g} px)")
            elif d:
                lines.insert(6, f"2D displacement: {float(d.get('length', 0.0)):.4g} px")
        except Exception:
            pass
        self.stats.setPlainText('\n'.join(lines))
    ROIPanel.update_stats = _s8_update_stats_with_units
except Exception as _e:
    print('Physical-units ROI stats patch skipped:', _e)


# Export/PDF plotting functions with calibrated labels.
def _s8_plot_overview_units(pdf, meta, metrics):
    cal = _s8_calibration_from_meta(meta)
    disp = _s8_metrics_for_display(metrics, meta)
    fig = plt.figure(figsize=(10, 6), dpi=160)
    title = str(meta.get('export_label', 'Hypervolume Summary'))
    fig.suptitle(title, fontsize=14)
    gs = fig.add_gridspec(2, 3, height_ratios=[1, 2])
    ax0 = fig.add_subplot(gs[0, :]); ax0.axis('off')
    threshold_text = f"Threshold: {meta.get('threshold_method')}"
    if str(meta.get('threshold_method', '')).lower() == 'manual':
        try:
            threshold_text += f" ({int(round(float(meta.get('manual_threshold', 0))))})"
        except Exception:
            threshold_text += f" ({meta.get('manual_threshold', 0)})"
    extent_scale, extent_unit, extent_kind = _s8_extent_scale_and_label(meta, cal)
    t_unit = _s8_time_unit(cal) if cal.get('has_time') else 'frames'
    lines = [
        f"Total hypervolumes (ROIs): {len(metrics['roi_id'])}",
        f"Shape (T,Z,Y,X): {meta.get('shape_TZYX', None)}",
        f"Units: {_s8_calibration_summary(cal)}",
        threshold_text + ' | '
        + f"export={meta.get('export_filter_desc', 'All ROIs')}  "
        + f"spatial={meta.get('use_spatial')} (σ={meta.get('blur_sigma', 0.0)})  "
        + f"savgol={meta.get('use_savgol')} (win={meta.get('savgol_window', 'auto')})  "
        + f"gate={meta.get('use_gate')}  "
        + f"bg_subtract={meta.get('bg_subtract', True)}",
    ]
    if meta.get('export_mode') is not None:
        lines.append(f"Export mode: {meta.get('export_mode')}")
    if meta.get('channel_index') is not None:
        lines.append(f"Channel: {meta.get('channel_index')}")
    if meta.get('n_channels_total') is not None:
        lines.append(f"Total channels in image: {meta.get('n_channels_total')}")
    ax0.text(0.01, 0.88, '\n'.join(lines), va='top', ha='left', family='monospace', fontsize=8.5)
    _hist(fig.add_subplot(gs[1,0]), disp['lifetime'], f"Lifetime ({t_unit})", t_unit)
    _hist(fig.add_subplot(gs[1,1]), disp['max_area'], f"Max {extent_kind} ({extent_unit})", extent_unit)
    _hist(fig.add_subplot(gs[1,2]), metrics['amp_range'], 'Amplitude range', 'intensity')
    pdf.savefig(fig); plt.close(fig)


def _s8_plot_strips_units(pdf, metrics, meta):
    cal = _s8_calibration_from_meta(meta)
    disp = _s8_metrics_for_display(metrics, meta)
    _, extent_unit, extent_kind = _s8_extent_scale_and_label(meta, cal)
    t_unit = _s8_time_unit(cal) if cal.get('has_time') else 'frames'
    fig = plt.figure(figsize=(12, 8), dpi=160); fig.suptitle('Parameter Strip Charts', fontsize=14)
    gs = fig.add_gridspec(2, 3)
    _strip(fig.add_subplot(gs[0,0]), disp['lifetime'], 'Lifetime', t_unit)
    _strip(fig.add_subplot(gs[0,1]), metrics['duty_cycle'], 'Duty Cycle', 'fraction')
    _strip(fig.add_subplot(gs[0,2]), disp['max_area'], f"Max {extent_kind.title()}", extent_unit)
    _strip(fig.add_subplot(gs[1,0]), metrics['amp_range'], 'Amplitude Range', 'intensity')
    _strip(fig.add_subplot(gs[1,1]), metrics['n_active_runs'], 'Active Runs', 'count')
    _strip(fig.add_subplot(gs[1,2]), disp['first_time'], 'First Active Time' if cal.get('has_time') else 'First Active Frame', t_unit if cal.get('has_time') else 'frame')
    pdf.savefig(fig); plt.close(fig)


def _s8_plot_multi_series_units(pdf, rois, T, meta=None):
    meta = meta or {}
    cal = _s8_calibration_from_meta(meta)
    xs, xlab = _s8_time_axis(T, cal)
    scale, extent_unit, extent_kind = _s8_extent_scale_and_label(meta, cal)
    fig = plt.figure(figsize=(12, 6), dpi=160)
    ax = fig.add_subplot(1, 1, 1)
    series = []; site_labels = []
    for rid, arr in sorted(rois.items(), key=lambda kv: str(kv[0])):
        try:
            meta_roi = arr[13]
            area_t = np.array(meta_roi.get('area_t', []), dtype=float) * scale
            site_label = int(meta_roi.get('site_label', 0))
        except Exception:
            area_t = np.array([], dtype=float); site_label = 0
        if area_t.size == 0:
            continue
        series.append(area_t); site_labels.append(site_label)
    if not series:
        ax.text(0.5, 0.5, 'No ROI time series', ha='center', va='center'); ax.set_axis_off()
    else:
        maxT = max(T, max(s.size for s in series)); xvals, xlab = _s8_time_axis(maxT, cal)
        uniq_sites = np.unique(site_labels)
        cmap = plt.get_cmap('tab20')
        site_color = {s: cmap(i % cmap.N) for i, s in enumerate(uniq_sites)}
        for s, lab in zip(series, site_labels):
            y = np.zeros(maxT, dtype=float); y[:s.size] = s
            ax.plot(xvals, y, lw=0.8, alpha=0.5, color=site_color.get(lab, 'k'))
        title = f"All ROIs — {extent_kind.title()} ({extent_unit}) over time"
        if isinstance(meta, dict) and meta.get('channel_index') is not None:
            title = f"Channel {meta.get('channel_index')} — " + title
        ax.set_title(title); ax.set_xlabel(xlab); ax.set_ylabel(extent_unit)
        if len(uniq_sites) <= 12:
            handles = [plt.Line2D([0], [0], color=site_color[s], lw=2) for s in uniq_sites]
            labels = [f"site {int(s)}" for s in uniq_sites]
            ax.legend(handles, labels, loc='upper right', fontsize=8, framealpha=0.7)
    pdf.savefig(fig); plt.close(fig)


def _s8_plot_centroid_displacements_pdf_units(pdf, rois: dict, meta: dict):
    T, Z, Y, X = [int(v) for v in meta.get('shape_TZYX', (0,0,0,0))]
    cal = _s8_calibration_from_meta(meta)
    fig = plt.figure(figsize=(8,8)); ax = fig.add_subplot(111)
    x0,y0,dx,dy,ids = _collect_start_end_displacements(rois, T)
    if _s8_xy_available(cal):
        sx, sy = float(cal['scale_x']), float(cal['scale_y'])
        x0p, y0p, dxp, dyp = x0 * sx, y0 * sy, dx * sx, dy * sy
        ax.set_xlim(0, X * sx); ax.set_ylim(Y * sy, 0)
        ax.set_xlabel(f"X ({_s8_len_unit(cal)})"); ax.set_ylabel(f"Y ({_s8_len_unit(cal)}, down)")
    else:
        x0p, y0p, dxp, dyp = x0, y0, dx, dy
        ax.set_xlim(0, X); ax.set_ylim(Y, 0); ax.set_xlabel('X (px)'); ax.set_ylabel('Y (px, down)')
    ax.set_title('ROI centroid displacement (start→end)')
    if x0.size > 0:
        ax.quiver(x0p, y0p, dxp, dyp, angles='xy', scale_units='xy', scale=1, width=0.002, headwidth=4, headlength=6, color='black')
        if len(ids) <= 40:
            for i, rid in enumerate(ids):
                ax.text(x0p[i], y0p[i], str(rid), fontsize=6, ha='left', va='bottom')
    else:
        ax.text(0.5,0.5,'No valid centroids found', ha='center', va='center', transform=ax.transAxes)
    pdf.savefig(fig); plt.close(fig)


def _s8_plot_centroid_displacements3d_pdf_units(pdf, rois: dict, meta: dict):
    T, Z, Y, X = [int(v) for v in meta.get('shape_TZYX', (0,0,0,0))]
    cal = _s8_calibration_from_meta(meta)
    x0,y0,z0,dx,dy,dz,ids = _collect_start_end_displacements3d(rois, T)
    if _s8_xyz_available(cal):
        sx, sy, sz = float(cal['scale_x']), float(cal['scale_y']), float(cal['scale_z'])
        x0p, y0p, z0p, dxp, dyp, dzp = x0*sx, y0*sy, z0*sz, dx*sx, dy*sy, dz*sz
        xlim, ylim, zlim = (0, X*sx), (Y*sy, 0), (0, Z*sz)
        xlab, ylab, zlab = f"X ({_s8_len_unit(cal)})", f"Y ({_s8_len_unit(cal)})", f"Z ({_s8_len_unit(cal)})"
    else:
        x0p, y0p, z0p, dxp, dyp, dzp = x0, y0, z0, dx, dy, dz
        xlim, ylim, zlim = (0, X), (Y, 0), (0, Z)
        xlab, ylab, zlab = 'X (px)', 'Y (px)', 'Z (slices)'
    fig = plt.figure(figsize=(11, 6.5))
    gs = fig.add_gridspec(1, 2, width_ratios=[1, 1], wspace=0.3)
    ax_xz = fig.add_subplot(gs[0, 0]); ax_yz = fig.add_subplot(gs[0, 1])
    fig.suptitle('ROI centroid displacement — orthographic projections (XZ & YZ)', fontsize=12)
    def quiver2d(ax, x, y, u, v, xlim_, ylim_, title, xlabel, ylabel, ids_):
        ax.set_title(title, fontsize=10); ax.set_xlim(*xlim_); ax.set_ylim(*ylim_)
        ax.set_xlabel(xlabel); ax.set_ylabel(ylabel)
        if x.size > 0:
            ax.quiver(x, y, u, v, angles='xy', scale_units='xy', scale=1, width=0.0018, headwidth=5, headlength=7, headaxislength=6, color='black')
            if len(ids_) <= 40:
                for i, rid in enumerate(ids_):
                    ax.text(x[i], y[i], str(rid), fontsize=6, ha='left', va='bottom')
        else:
            ax.text(0.5,0.5,'No valid displacements', ha='center', va='center', transform=ax.transAxes)
        ax.grid(alpha=0.15)
        for spine in ax.spines.values():
            spine.set_alpha(0.4)
    quiver2d(ax_xz, x0p, z0p, dxp, dzp, xlim, zlim, 'XZ projection', xlab, zlab, ids)
    quiver2d(ax_yz, y0p, z0p, dyp, dzp, ylim, zlim, 'YZ projection (Y down in XY)', ylab, zlab, ids)
    pdf.savefig(fig); plt.close(fig)


def _s8_plot_coherence_pdf_units(pdf, coord_dict, T, meta=None):
    if not coord_dict or 'band_mean' not in coord_dict:
        return
    cal = _s8_calibration_from_meta(meta)
    band_vals = np.asarray([v for v in coord_dict['band_mean'].values() if np.isfinite(v)], float)
    fig = plt.figure(figsize=(10,4), dpi=160); ax = fig.add_subplot(1,1,1)
    if band_vals.size:
        band = coord_dict.get('band_period_frames', (20,200))
        if cal.get('scale_t') is not None:
            title_band = f"period {band[0]*cal['scale_t']:.4g}–{band[1]*cal['scale_t']:.4g} {_s8_time_unit(cal)}"
        else:
            title_band = f"period {band} frames"
        ax.hist(band_vals, bins=30)
        ax.set_title(f"Wavelet Coherence — band mean ({title_band})")
        ax.set_xlabel('R²'); ax.set_ylabel('ROI count')
    else:
        ax.text(0.5,0.5,'No coherence values', ha='center', va='center'); ax.axis('off')
    pdf.savefig(fig); plt.close(fig)


def _s8_plot_velocity_pdf_units(pdf, vel_dict, meta=None):
    if not vel_dict:
        return
    cal = _s8_calibration_from_meta(meta)
    phys = _s8_physical_propagation_from_table(vel_dict, cal)
    fig = plt.figure(figsize=(10,4), dpi=160)
    gs = fig.add_gridspec(1,2); ax0 = fig.add_subplot(gs[0,0]); ax1 = fig.add_subplot(gs[0,1])
    ax0.set_title('Propagation direction'); ax0.set_xlim(-1,1); ax0.set_ylim(-1,1); ax0.set_aspect('equal')
    th = float(phys.get('angle_radians', vel_dict.get('angle_radians', np.nan)))
    if np.isfinite(th):
        ax0.arrow(0,0, np.cos(th), np.sin(th), head_width=0.1, length_includes_head=True)
        ax0.text(-0.95,0.9, f"angle = {th:.2f} rad", ha='left', va='top')
    else:
        ax0.text(0.5,0.5,'N/A', ha='center', va='center'); ax0.axis('off')
    ax1.axis('off')
    npts = int(vel_dict.get('n_points', phys.get('n_points', 0)))
    if phys:
        txt = f"Estimated speed: {phys['speed_length_per_time']:.4g} {phys['speed_unit']}\nSamples used: {npts}"
    else:
        sp = float(vel_dict.get('speed_frames_per_pixel', np.nan))
        txt = f"Estimated speed: {sp:.3f} pixels/frame\nSamples used: {npts}"
    ax1.text(0.02, 0.9, txt, ha='left', va='top', family='monospace')
    pdf.savefig(fig); plt.close(fig)


def _s8_plot_fingerprint_summary_units(pdf, combined):
    fp = combined.get('fingerprint', {}) if isinstance(combined, dict) else {}
    fp_phys = combined.get('fingerprint_physical', {}) if isinstance(combined, dict) else {}
    fp_units = combined.get('fingerprint_physical_units', {}) if isinstance(combined, dict) else {}
    fig = plt.figure(figsize=(10, 6), dpi=160)
    fig.suptitle('Sample fingerprint', fontsize=14)
    gs = fig.add_gridspec(2, 2)
    ax0 = fig.add_subplot(gs[:, 0]); ax0.axis('off')
    if not fp:
        ax0.text(0.02, 0.98, 'No fingerprint computed.', va='top', ha='left', family='monospace')
        ax1 = fig.add_subplot(gs[0, 1]); ax1.axis('off')
        ax2 = fig.add_subplot(gs[1, 1]); ax2.axis('off')
    else:
        preferred = ['n_rois', 'roi_density_per_frame', 'n_sites', 'mean_lifetime', 'median_lifetime', 'mean_max_area', 'median_max_area', 'mean_amp_range', 'mean_disp_len2d', 'mean_duty_cycle', 'mean_n_active_runs', 'mean_coherence_band', 'std_coherence_band', 'propagation_speed_frames_per_pixel']
        lines = []
        for key in preferred:
            if key in fp:
                val = fp[key]
                label = key
                if key in fp_phys:
                    unit = fp_units.get('time') if 'lifetime' in key or 'first_time' in key else fp_units.get('extent') if 'max_area' in key else fp_units.get('length') if 'disp_len' in key else None
                    label = f"{key} ({unit})" if unit else key
                    val = fp_phys[key]
                elif key == 'propagation_speed_frames_per_pixel' and 'propagation_speed' in fp_phys:
                    val = fp_phys['propagation_speed']; label = f"propagation_speed ({fp_units.get('speed')})"
                try:
                    if isinstance(val, (int, np.integer)):
                        lines.append(f"{label}: {int(val)}")
                    else:
                        lines.append(f"{label}: {float(val):.4g}")
                except Exception:
                    lines.append(f"{label}: {val}")
        ax0.text(0.02, 0.98, '\n'.join(lines), va='top', ha='left', family='monospace')
        frac_items = [(k.replace('frac_', ''), float(v)) for k, v in fp.items() if str(k).startswith('frac_')]
        frac_items.sort(key=lambda kv: kv[1], reverse=True)
        ax1 = fig.add_subplot(gs[0, 1])
        if frac_items:
            labels = [k for k, _ in frac_items[:8]]; vals = [v for _, v in frac_items[:8]]
            ax1.bar(np.arange(len(labels)), vals); ax1.set_xticks(np.arange(len(labels)))
            ax1.set_xticklabels(labels, rotation=35, ha='right'); ax1.set_ylabel('fraction'); ax1.set_title('Ontology composition')
        else:
            ax1.text(0.5, 0.5, 'No ontology fractions', ha='center', va='center'); ax1.axis('off')
        ax2 = fig.add_subplot(gs[1, 1]); ax2.axis('off')
        extra_lines = [f"{k}: {float(v):.4g}" for k, v in sorted(fp.items()) if str(k).startswith('frac_')]
        ax2.text(0.02, 0.98, '\n'.join(extra_lines[:12]) if extra_lines else 'No ontology fractions', va='top', ha='left', family='monospace')
    pdf.savefig(fig); plt.close(fig)


def _s8_plot_intersect_channel_series_units(pdf, combined, max_detail_pages=None):
    pairs = list((combined or {}).get('intersect_report_pairs', []) or [])
    meta = (combined or {}).get('metadata', {}) or {}
    if not bool(meta.get('intersect_mode', False)):
        return
    cal = _s8_calibration_from_meta(meta)
    scale, extent_unit, extent_kind = _s8_extent_scale_and_label(meta, cal)
    T = int((meta.get('shape_TZYX', (0, 0, 0, 0)) or (0, 0, 0, 0))[0] or 0)
    fig = plt.figure(figsize=(12, 7), dpi=160)
    fig.suptitle('Intersected ROI pairs - paired channel traces', fontsize=14)
    gs = fig.add_gridspec(2, 1); ax_v = fig.add_subplot(gs[0, 0]); ax_i = fig.add_subplot(gs[1, 0])
    if not pairs:
        ax_v.text(0.5, 0.5, 'No intersected channel pairs available for plotting', ha='center', va='center'); ax_v.axis('off'); ax_i.axis('off')
        pdf.savefig(fig); plt.close(fig); return
    maxT = T
    for p in pairs:
        maxT = max(maxT, len(p.get('series_a', {}).get('area_t', [])), len(p.get('series_b', {}).get('area_t', [])), len(p.get('series_a', {}).get('amp_filt', [])), len(p.get('series_b', {}).get('amp_filt', [])))
    x, xlab = _s8_time_axis(max(1, maxT), cal)
    for p in pairs:
        ch_a = int(p.get('channel_a', 0)); roi_a = int(p.get('roi_a', 0)); ch_b = int(p.get('channel_b', 0)); roi_b = int(p.get('roi_b', 0))
        label_a = f'ch{ch_a} ROI {roi_a}'; label_b = f'ch{ch_b} ROI {roi_b}'
        ya = _pad_series_for_plot(p.get('series_a', {}).get('area_t', []), maxT) * scale
        yb = _pad_series_for_plot(p.get('series_b', {}).get('area_t', []), maxT) * scale
        ia = _pad_series_for_plot(p.get('series_a', {}).get('amp_filt', []), maxT)
        ib = _pad_series_for_plot(p.get('series_b', {}).get('amp_filt', []), maxT)
        ax_v.plot(x, ya, lw=0.8, alpha=0.45, label=label_a); ax_v.plot(x, yb, lw=0.8, alpha=0.45, ls='--', label=label_b)
        ax_i.plot(x, ia, lw=0.8, alpha=0.45, label=label_a); ax_i.plot(x, ib, lw=0.8, alpha=0.45, ls='--', label=label_b)
    ax_v.set_title(f"All intersected ROI pairs ({len(pairs)} pairs): solid=current export channel, dashed=paired channel")
    ax_v.set_xlabel(xlab); ax_v.set_ylabel(extent_unit)
    ax_i.set_title('Filtered mean intensity for intersected ROI pairs'); ax_i.set_xlabel(xlab); ax_i.set_ylabel('intensity (a.u.)')
    if len(pairs) <= 8:
        ax_v.legend(loc='upper right', fontsize=6, framealpha=0.6); ax_i.legend(loc='upper right', fontsize=6, framealpha=0.6)
    pdf.savefig(fig); plt.close(fig)
    for p in pairs:
        ch_a = int(p.get('channel_a', 0)); roi_a = int(p.get('roi_a', 0)); ch_b = int(p.get('channel_b', 0)); roi_b = int(p.get('roi_b', 0))
        ct = int(p.get('overlap_voxels', 0))
        maxT_pair = max(T, len(p.get('series_a', {}).get('area_t', [])), len(p.get('series_b', {}).get('area_t', [])), len(p.get('series_a', {}).get('amp_filt', [])), len(p.get('series_b', {}).get('amp_filt', [])), len(p.get('series_a', {}).get('amp_raw', [])), len(p.get('series_b', {}).get('amp_raw', [])))
        x, xlab = _s8_time_axis(max(1, maxT_pair), cal)
        fig = plt.figure(figsize=(12, 7), dpi=160); fig.suptitle(f'Intersect pair: ch{ch_a} ROI {roi_a} <-> ch{ch_b} ROI {roi_b} ({ct} shared voxels)', fontsize=13)
        gs = fig.add_gridspec(2, 1); ax_v = fig.add_subplot(gs[0, 0]); ax_i = fig.add_subplot(gs[1, 0])
        ax_v.plot(x, _pad_series_for_plot(p.get('series_a', {}).get('area_t', []), maxT_pair) * scale, lw=1.4, label=f'ch{ch_a} ROI {roi_a} {extent_kind}')
        ax_v.plot(x, _pad_series_for_plot(p.get('series_b', {}).get('area_t', []), maxT_pair) * scale, lw=1.4, ls='--', label=f'ch{ch_b} ROI {roi_b} {extent_kind}')
        ax_v.set_xlabel(xlab); ax_v.set_ylabel(extent_unit); ax_v.legend(loc='upper right', fontsize=8, frameon=False)
        ax_i.plot(x, _pad_series_for_plot(p.get('series_a', {}).get('amp_filt', []), maxT_pair), lw=1.4, label=f'ch{ch_a} ROI {roi_a} filtered')
        ax_i.plot(x, _pad_series_for_plot(p.get('series_b', {}).get('amp_filt', []), maxT_pair), lw=1.4, ls='--', label=f'ch{ch_b} ROI {roi_b} filtered')
        raw_a = p.get('series_a', {}).get('amp_raw', []); raw_b = p.get('series_b', {}).get('amp_raw', [])
        if len(raw_a):
            ax_i.plot(x, _pad_series_for_plot(raw_a, maxT_pair), lw=0.9, alpha=0.55, ls=':', label=f'ch{ch_a} ROI {roi_a} raw')
        if len(raw_b):
            ax_i.plot(x, _pad_series_for_plot(raw_b, maxT_pair), lw=0.9, alpha=0.55, ls='-.', label=f'ch{ch_b} ROI {roi_b} raw')
        ax_i.set_xlabel(xlab); ax_i.set_ylabel('intensity (a.u.)'); ax_i.legend(loc='upper right', fontsize=8, frameon=False)
        pdf.savefig(fig); plt.close(fig)


# Override report writer to use calibrated plots.
def write_report_pdf_progress(out_base: str, combined: dict, parent=None):
    combined = _s8_units_enrich_combined(combined)
    rois = combined.get('rois', {})
    meta = combined.get('metadata', {})
    coord = combined.get('coordination', {})
    vel = combined.get('propagation', {})
    T = int(meta.get('shape_TZYX', (0,0,0,0))[0] or 0)
    out_pdf = out_base + '_hypervolume_report.pdf'
    with PdfPages(out_pdf) as pdf:
        metrics = _collect_metrics(rois)
        _s8_plot_overview_units(pdf, meta, metrics)
        _s8_plot_fingerprint_summary_units(pdf, combined)
        _plot_ontology_summary(pdf, combined)
        _s8_plot_strips_units(pdf, metrics, meta)
        _s8_plot_multi_series_units(pdf, rois, T, meta=meta)
        _s8_plot_intersect_channel_series_units(pdf, combined)
        _s8_plot_centroid_displacements_pdf_units(pdf, rois, meta)
        _s8_plot_centroid_displacements3d_pdf_units(pdf, rois, meta)
        _s8_plot_coherence_pdf_units(pdf, coord, T, meta=meta)
        _s8_plot_velocity_pdf_units(pdf, vel, meta=meta)
    print(f"Wrote report: {out_pdf}")

# Replace standalone plot function names too, for any older call paths.
_plot_overview = _s8_plot_overview_units
_plot_strips = lambda pdf, metrics: _s8_plot_strips_units(pdf, metrics, {})
_plot_multi_series_housekeeping = _s8_plot_multi_series_units
_plot_centroid_displacements_pdf = _s8_plot_centroid_displacements_pdf_units
_plot_centroid_displacements3d_pdf = _s8_plot_centroid_displacements3d_pdf_units
_plot_coherence_pdf = lambda pdf, coord_dict, T: _s8_plot_coherence_pdf_units(pdf, coord_dict, T, meta={})
_plot_velocity_pdf = lambda pdf, vel_dict: _s8_plot_velocity_pdf_units(pdf, vel_dict, meta={})
_plot_fingerprint_summary = _s8_plot_fingerprint_summary_units
_plot_intersect_channel_series = _s8_plot_intersect_channel_series_units


