    def _s8_pviz_is_number(x):
        try:
            if isinstance(x, (str, bytes, bytearray, bool)):
                return False
            float(x)
            return True
        except Exception:
            return False

    def _s8_pviz_numeric_1d(value):
        try:
            arr = np.asarray(value)
            if arr.dtype == object:
                return None
            if arr.size == 0:
                return None
            if not np.issubdtype(arr.dtype, np.number):
                return None
            arr = arr.astype(float, copy=False).reshape(-1)
            if arr.size == 0:
                return None
            return arr
        except Exception:
            return None

    def _s8_pviz_add_series(series, name, value, max_len=None):
        arr = _s8_pviz_numeric_1d(value)
        if arr is None:
            return False
        if max_len is not None and arr.size > int(max_len):
            return False
        key = str(name)
        if key in series:
            i = 2
            while f"{key} [{i}]" in series:
                i += 1
            key = f"{key} [{i}]"
        series[key] = arr
        return True

