    def _s8_pviz_friendly_label_for_key(key):
        key = str(key)
        if key in _S8_PVIZ_FRIENDLY_NAMES:
            return _S8_PVIZ_FRIENDLY_NAMES[key]
        if key.startswith('fingerprint.frac_'):
            cls = key[len('fingerprint.frac_'):].replace('_', ' ').strip() or 'ontology class'
            return f'Sample fingerprint: fraction classified as {cls}'
        if key.startswith('roi.'):
            tail = key[4:]
            parts = []
            for chunk in tail.replace('[', '_').replace(']', '').replace(':,', '_').replace(',', '_').replace('.', '_').split('_'):
                if chunk:
                    parts.append(_s8_pviz_humanize_token(chunk))
            label = ' '.join(parts).strip()
            return f'ROI metric: {label}' if label else key
        if key.startswith('fingerprint.'):
            tail = key[len('fingerprint.'):].replace('_', ' ')
            return f'Sample fingerprint: {tail}'
        if key.startswith('pickle.metadata.'):
            tail = key[len('pickle.metadata.'):].replace('_', ' ')
            return f'Acquisition / export metadata: {tail}'
        if key.startswith('pickle.propagation.'):
            tail = key[len('pickle.propagation.'):].replace('_', ' ')
            return f'Sample propagation metric: {tail}'
        if key.startswith('pickle.hierarchy.'):
            tail = key[len('pickle.hierarchy.'):].replace('_', ' ')
            return f'ROI hierarchy / site organization: {tail}'
        if key.startswith('pickle.coordination.'):
            tail = key[len('pickle.coordination.'):].replace('_', ' ')
            return f'Coordination metric: {tail}'
        return 'Raw pickle field: ' + key.replace('_', ' ')

    def _s8_pviz_unique_labels(keys):
        labels = {}
        used = {}
        for key in keys:
            base = _s8_pviz_friendly_label_for_key(key)
            label = base
            if label in used:
                used[label] += 1
                label = f'{base} [{key}]'
            else:
                used[label] = 1
            labels[key] = label
        return labels

    def _s8_qt_role(name, fallback=None):
        try:
            return getattr(Qt, name)
        except Exception:
            try:
                return getattr(Qt.ItemDataRole, name)
            except Exception:
                return fallback

    def _s8_pviz_flatten_generic(obj, series, prefix='pickle', depth=0, max_depth=5, max_series=800):
        if len(series) >= max_series or depth > max_depth:
            return
        try:
            if isinstance(obj, dict):
                for k, v in obj.items():
                    if len(series) >= max_series:
                        return
                    ks = str(k)
                    low = ks.lower()
                    # ROI coordinate payloads can be very large and are better summarized by ROI metrics.
                    if low in ('rois', 'coords', 'coordinates') or 'coords' in low or 'coordinate' in low:
                        continue
                    _s8_pviz_flatten_generic(v, series, f"{prefix}.{ks}", depth + 1, max_depth, max_series)
            elif isinstance(obj, (list, tuple)):
                if len(obj) == 0:
                    return
                arr = _s8_pviz_numeric_1d(obj)
                if arr is not None and arr.size <= 1000000:
                    _s8_pviz_add_series(series, prefix, arr)
                    return
                for i, v in enumerate(obj[:30]):
                    if len(series) >= max_series:
                        return
                    _s8_pviz_flatten_generic(v, series, f"{prefix}[{i}]", depth + 1, max_depth, max_series)
            else:
                arr = np.asarray(obj)
                if arr.dtype != object and np.issubdtype(arr.dtype, np.number):
                    if arr.ndim == 0:
                        _s8_pviz_add_series(series, prefix, np.array([float(arr)]))
                    elif arr.ndim == 1 and arr.size <= 1000000:
                        _s8_pviz_add_series(series, prefix, arr)
                    elif arr.ndim == 2 and arr.shape[1] <= 12 and arr.size <= 1000000:
                        for j in range(arr.shape[1]):
                            _s8_pviz_add_series(series, f"{prefix}[:,{j}]", arr[:, j])
        except Exception:
            return

    def _s8_pviz_roi_rows_from_combined(data):
        rows = []
        rois = data.get('rois', {}) if isinstance(data, dict) else {}
        if not isinstance(rois, dict):
            return rows
        disp2 = (((data.get('displacements', {}) or {}).get('centroid_start_end_2d', {}) or {})
                 if isinstance(data, dict) else {})
        disp3 = (((data.get('displacements', {}) or {}).get('centroid_start_end_3d', {}) or {})
                 if isinstance(data, dict) else {})
        coord = data.get('coordination', {}) if isinstance(data, dict) else {}
        band = coord.get('band_mean', {}) if isinstance(coord, dict) else {}
        ont = data.get('ontology', {}) if isinstance(data, dict) else {}
        primary = ont.get('primary_class_by_roi', {}) if isinstance(ont, dict) else {}
        memberships = ont.get('membership_by_roi', {}) if isinstance(ont, dict) else {}
        for rid, arr in rois.items():
            try:
                rid_int = int(rid)
            except Exception:
                rid_int = rid
            row = {'roi_id': rid_int}
            try:
                row['max_area'] = float(arr[1]) if len(arr) > 1 and _s8_pviz_is_number(arr[1]) else np.nan
            except Exception:
                row['max_area'] = np.nan
            try:
                row['lifetime'] = float(arr[3]) if len(arr) > 3 and _s8_pviz_is_number(arr[3]) else np.nan
            except Exception:
                row['lifetime'] = np.nan
            try:
                _m_amp = arr[13] if len(arr) > 13 and isinstance(arr[13], dict) else {}
                row['peak_ff0'] = float(_m_amp.get('peak_ff0', _m_amp.get('ff0_max', arr[5] if len(arr) > 5 else np.nan)))
                row['amp_range'] = float(_m_amp.get('ff0_range', np.nan))
            except Exception:
                row['peak_ff0'] = np.nan
                row['amp_range'] = np.nan
            try:
                row['first_time'] = float(arr[6]) if len(arr) > 6 and _s8_pviz_is_number(arr[6]) else np.nan
            except Exception:
                row['first_time'] = np.nan
            try:
                coords = np.asarray(arr[8]) if len(arr) > 8 and arr[8] is not None else np.zeros((0, 4))
                row['n_voxels'] = float(coords.reshape(-1, 4).shape[0]) if coords.size and coords.size % 4 == 0 else float(coords.shape[0] if coords.ndim else 0)
            except Exception:
                row['n_voxels'] = np.nan
            meta = {}
            try:
                meta = arr[13] if len(arr) > 13 and isinstance(arr[13], dict) else {}
            except Exception:
                meta = {}
            for mk in ('T', 'Z', 'lifetime_frames', 'duty_cycle', 'n_active_runs', 'site_label'):
                try:
                    mv = meta.get(mk, None)
                    if _s8_pviz_is_number(mv):
                        row[mk] = float(mv)
                except Exception:
                    pass
            try:
                bbox = meta.get('bbox', {}) if isinstance(meta, dict) else {}
                if isinstance(bbox, dict):
                    for bk, bv in bbox.items():
                        if _s8_pviz_is_number(bv):
                            row[f'bbox_{bk}'] = float(bv)
            except Exception:
                pass
            for key, out_name in (
                ('area_t', 'volume'),
                ('meanint_t', 'mean_intensity'),
                ('area_peak2d_t', 'peak2d_area'),
                ('meanint_peak2d_t', 'peak2d_mean_intensity'),
            ):
                try:
                    vals = _s8_pviz_numeric_1d(meta.get(key, None))
                    if vals is not None and vals.size:
                        row[f'{out_name}_mean'] = float(np.nanmean(vals))
                        row[f'{out_name}_median'] = float(np.nanmedian(vals))
                        row[f'{out_name}_max'] = float(np.nanmax(vals))
                        row[f'{out_name}_sum'] = float(np.nansum(vals))
                except Exception:
                    pass
            try:
                d = disp2.get(rid_int, disp2.get(str(rid_int), disp2.get(rid, {}))) if isinstance(disp2, dict) else {}
                if isinstance(d, dict):
                    for dk, dv in d.items():
                        if _s8_pviz_is_number(dv):
                            row[f'disp2d_{dk}'] = float(dv)
            except Exception:
                pass
            try:
                d = disp3.get(rid_int, disp3.get(str(rid_int), disp3.get(rid, {}))) if isinstance(disp3, dict) else {}
                if isinstance(d, dict):
                    for dk, dv in d.items():
                        if _s8_pviz_is_number(dv):
                            row[f'disp3d_{dk}'] = float(dv)
            except Exception:
                pass
            try:
                bv = band.get(rid_int, band.get(str(rid_int), np.nan)) if isinstance(band, dict) else np.nan
                if _s8_pviz_is_number(bv):
                    row['coordination_band_mean'] = float(bv)
            except Exception:
                pass
            try:
                row['primary_ontology'] = str(primary.get(rid_int, primary.get(str(rid_int), 'Unclassified')))
            except Exception:
                row['primary_ontology'] = 'Unclassified'
            try:
                mm = memberships.get(rid_int, memberships.get(str(rid_int), [])) if isinstance(memberships, dict) else []
                row['ontology_membership_count'] = float(len(mm)) if isinstance(mm, (list, tuple, set)) else (1.0 if mm else 0.0)
            except Exception:
                row['ontology_membership_count'] = 0.0
            rows.append(row)
        return rows

    def _s8_pviz_collect_series(data):
        from collections import OrderedDict
        series = OrderedDict()
        categories = OrderedDict()
        rows = _s8_pviz_roi_rows_from_combined(data) if isinstance(data, dict) else []
        if rows:
            keys = sorted({k for r in rows for k in r.keys() if k not in ('primary_ontology',)})
            for key in keys:
                vals = []
                ok = False
                for r in rows:
                    v = r.get(key, np.nan)
                    if _s8_pviz_is_number(v):
                        vals.append(float(v)); ok = True
                    else:
                        vals.append(np.nan)
                if ok:
                    _s8_pviz_add_series(series, f'roi.{key}', vals)
            categories['roi.primary_ontology'] = np.asarray([str(r.get('primary_ontology', 'Unclassified')) for r in rows], dtype=object)
        if isinstance(data, dict):
            fp = data.get('fingerprint', {})
            if isinstance(fp, dict):
                for k, v in fp.items():
                    if _s8_pviz_is_number(v):
                        _s8_pviz_add_series(series, f'fingerprint.{k}', [float(v)])
            # Add generic numeric arrays outside the heavy ROI coordinate payload.
            generic = OrderedDict()
            _s8_pviz_flatten_generic(data, generic, prefix='pickle', max_depth=5, max_series=500)
            for k, v in generic.items():
                if k not in series:
                    series[k] = v
        else:
            _s8_pviz_flatten_generic(data, series, prefix='pickle', max_depth=6, max_series=800)
        return series, categories

