try:
    def _s8_pviz_refresh_intersect_view_channel_colored(self, *_):
        if not hasattr(self, 'fig_intersect_trace'):
            return
        pair = self._s8_pviz_current_intersect_pair()
        self.fig_intersect_trace.clear(); self.fig_intersect_3d.clear()
        ax_v = self.fig_intersect_trace.add_subplot(2, 1, 1)
        ax_i = self.fig_intersect_trace.add_subplot(2, 1, 2)
        ax3 = self.fig_intersect_3d.add_subplot(1, 1, 1, projection='3d')
        if pair is None:
            ax_v.text(0.5, 0.5, 'No intersect pair selected', ha='center', va='center', transform=ax_v.transAxes)
            ax_i.axis('off')
            ax3.text2D(0.5, 0.5, 'Load an intersect export', ha='center', va='center', transform=ax3.transAxes)
            ax3.set_axis_off()
            self.canvas_intersect_trace.draw_idle(); self.canvas_intersect_3d.draw_idle()
            return
        try:
            T = int(max(_s8_pviz_meta_TZYX(self.data)[0],
                        len(np.asarray(pair.get('series_a', {}).get('area_t', []))),
                        len(np.asarray(pair.get('series_b', {}).get('area_t', [])))))
            T = max(T, 1)
            t_now = int(self.spin_intersect_t.value())
            t_now = max(0, min(t_now, T - 1))
            sa = pair.get('series_a', {}) or {}; sb = pair.get('series_b', {}) or {}
            ca = int(pair.get('channel_a', 0)); cb = int(pair.get('channel_b', 1))
            ra = int(pair.get('roi_a', sa.get('roi_id', -1))); rb = int(pair.get('roi_b', sb.get('roi_id', -1)))
            x = np.arange(T)
            av = _s8_pviz_series_vec(sa, 'area_t', T); bv = _s8_pviz_series_vec(sb, 'area_t', T)
            ai = _s8_pviz_series_vec(sa, 'amp_filt', T); bi = _s8_pviz_series_vec(sb, 'amp_filt', T)
            if not np.any(np.isfinite(ai)) or np.nanmax(np.abs(ai)) == 0:
                ai = _s8_pviz_series_vec(sa, 'amp_raw', T)
            if not np.any(np.isfinite(bi)) or np.nanmax(np.abs(bi)) == 0:
                bi = _s8_pviz_series_vec(sb, 'amp_raw', T)

            line_a = ax_v.plot(x, av, lw=1.6, label=f'Ch{ca} ROI {ra}')[0]
            line_b = ax_v.plot(x, bv, lw=1.6, label=f'Ch{cb} ROI {rb}')[0]
            color_a = line_a.get_color(); color_b = line_b.get_color()
            ax_v.axvline(t_now, ls='--', lw=1, color='0.35')
            ax_v.set_title('Multichannel hypervolume voxels vs time')
            ax_v.set_xlabel('time (frame)'); ax_v.set_ylabel('voxels')
            ax_v.legend(loc='best', fontsize=8, frameon=False)
            ax_v.grid(True, alpha=0.2)

            ax_i.plot(x, ai, lw=1.6, color=color_a, label=f'Ch{ca} ROI {ra} mean intensity')
            ax_i.plot(x, bi, lw=1.6, color=color_b, label=f'Ch{cb} ROI {rb} mean intensity')
            ax_i.axvline(t_now, ls='--', lw=1, color='0.35')
            ax_i.set_title('Multichannel mean intensity vs time')
            ax_i.set_xlabel('time (frame)'); ax_i.set_ylabel('intensity (a.u.)')
            ax_i.legend(loc='best', fontsize=8, frameon=False)
            ax_i.grid(True, alpha=0.2)

            coords_a = _s8_pviz_coords_from_pair_or_export(self.data, pair, 'a')
            coords_b = _s8_pviz_coords_from_pair_or_export(self.data, pair, 'b')
            pt_size = int(getattr(self, 'spin_size', QtWidgets.QSpinBox()).value()) if hasattr(self, 'spin_size') else 4
            shown_a, cur_a = _s8_pviz_plot_channel_coords_3d(ax3, coords_a, t_now, color_a, f'Ch{ca} ROI {ra}', pt_size)
            shown_b, cur_b = _s8_pviz_plot_channel_coords_3d(ax3, coords_b, t_now, color_b, f'Ch{cb} ROI {rb}', pt_size)

            if shown_a or shown_b:
                ax3.set_xlabel('X'); ax3.set_ylabel('Y'); ax3.set_zlabel('Z')
                ax3.legend(loc='best', fontsize=8, frameon=False)
                all_sel = []
                for coords, shown in ((coords_a, shown_a), (coords_b, shown_b)):
                    if shown:
                        sel, _ = _s8_pviz_select_coords_for_time(coords, t_now)
                        if sel.size:
                            all_sel.append(sel)
                if all_sel:
                    pts = np.vstack(all_sel)
                    z = pts[:, 1].astype(float); y = pts[:, 2].astype(float); xx = pts[:, 3].astype(float)
                    try:
                        ax3.set_box_aspect((max(1, np.nanmax(xx)-np.nanmin(xx)), max(1, np.nanmax(y)-np.nanmin(y)), max(1, np.nanmax(z)-np.nanmin(z))))
                    except Exception:
                        pass
                if (shown_a and not cur_a) or (shown_b and not cur_b):
                    ax3.set_title(f'ROI voxels in 3D; low alpha = all active voxels (none at t={t_now})')
                else:
                    ax3.set_title(f'Current hypervolumes in 3D at t={t_now}')
            else:
                ax3.text2D(0.5, 0.54, 'No saved coordinates for this pair', ha='center', va='center', transform=ax3.transAxes)
                ax3.text2D(0.5, 0.44, 'Re-export with this build to include both channel coordinate clouds.', ha='center', va='center', transform=ax3.transAxes)
                ax3.set_axis_off()

            missing = []
            if not shown_a:
                missing.append(f'Ch{ca} ROI {ra} coords unavailable')
            if not shown_b:
                missing.append(f'Ch{cb} ROI {rb} coords unavailable')
            try:
                msg = (
                    f'Pair: Ch{ca} ROI {ra} ↔ Ch{cb} ROI {rb}; overlap={int(pair.get("overlap_voxels", 0))} voxels; '
                    f't={t_now}; Ch{ca} voxels={float(av[t_now]):.0f}; Ch{cb} voxels={float(bv[t_now]):.0f}; '
                    f'Ch{ca} intensity={float(ai[t_now]):.3g}; Ch{cb} intensity={float(bi[t_now]):.3g}'
                )
                if missing:
                    msg += ' | ' + '; '.join(missing)
                self.lbl_intersect_hint.setText(msg)
            except Exception:
                pass
        except Exception as e:
            ax_v.text(0.5, 0.5, f'Intersect plot error:\n{e}', ha='center', va='center', transform=ax_v.transAxes, wrap=True)
            ax_i.axis('off')
            ax3.set_axis_off()
        self.canvas_intersect_trace.draw_idle(); self.canvas_intersect_3d.draw_idle()

    S8PickleVisualizationDialog.refresh_intersect_view = _s8_pviz_refresh_intersect_view_channel_colored
except Exception as _e:
    print('Channel-colored intersect 3D refresh patch skipped:', _e)
