try:
    def _s8_count_query_against_index(query_sites, bases, unique_idx, starts_idx, ends_idx, rids_idx,
                                      query_is_a, pair_counts, best_a_to_b, best_b_to_a):
        items = list((query_sites or {}).items())
        n_items = max(1, len(items))
        app = None
        try:
            app = QtWidgets.QApplication.instance()
        except Exception:
            app = None
        for i, (rid_q, arr_q) in enumerate(items):
            rid_q = int(rid_q)
            try:
                src = arr_q[8] if arr_q is not None and len(arr_q) > 8 else None
                keys_q = np.unique(_s8_source_keys_for_bases(src, bases))
            except Exception:
                keys_q = np.zeros(0, dtype=np.int64)
            if keys_q.size == 0:
                continue
            pos = np.searchsorted(unique_idx, keys_q)
            valid = (pos < unique_idx.size)
            if not np.any(valid):
                continue
            pos_valid = pos[valid]
            keys_valid = keys_q[valid]
            hit_mask = (unique_idx[pos_valid] == keys_valid)
            if not np.any(hit_mask):
                continue
            counts = {}
            for p in pos_valid[hit_mask]:
                s = int(starts_idx[p]); e = int(ends_idx[p])
                for rid_idx in rids_idx[s:e]:
                    rid_idx = int(rid_idx)
                    counts[rid_idx] = counts.get(rid_idx, 0) + 1
            for rid_idx, ct in counts.items():
                if query_is_a:
                    rid_a, rid_b = rid_q, int(rid_idx)
                else:
                    rid_a, rid_b = int(rid_idx), rid_q
                ct = int(ct)
                pair_counts[(rid_a, rid_b)] = ct
                _s8_update_best_overlap(best_a_to_b, rid_a, rid_b, ct)
                _s8_update_best_overlap(best_b_to_a, rid_b, rid_a, ct)
            if app is not None and ((i % 8) == 0 or i == n_items - 1):
                try:
                    app.processEvents()
                except Exception:
                    pass
except Exception as _e:
    print('Disk-backed count query patch skipped:', _e)

try:
    def _s8_intersection_keys_for_pair(sites_a, roi_a, sites_b, roi_b, bases):
        try:
            arr_a = (sites_a or {}).get(int(roi_a), (sites_a or {}).get(str(int(roi_a))))
            arr_b = (sites_b or {}).get(int(roi_b), (sites_b or {}).get(str(int(roi_b))))
            src_a = arr_a[8] if arr_a is not None and len(arr_a) > 8 else None
            src_b = arr_b[8] if arr_b is not None and len(arr_b) > 8 else None
            ka = np.unique(_s8_source_keys_for_bases(src_a, bases))
            kb = np.unique(_s8_source_keys_for_bases(src_b, bases))
            if ka.size == 0 or kb.size == 0:
                return np.zeros(0, dtype=np.int64)
            return np.intersect1d(ka, kb, assume_unique=True)
        except Exception:
            return np.zeros(0, dtype=np.int64)
except Exception as _e:
    print('Disk-backed pair-intersection patch skipped:', _e)


# GUI/display compatibility for coordinate refs.  This keeps the original filled
# point-cloud display behavior, but samples directly from sidecar keys instead of
# materializing full coordinate arrays just to build the napari points layer.
def _s8_sample_coords_from_source(src, T, Z, Y, X, max_points=3000):
    if _s8_is_coord_ref(src):
        shp = _s8_coord_ref_shape(src) or (int(T), int(Z), int(Y), int(X))
        keys = _s8_coord_ref_keys(src)
        n = int(getattr(keys, 'shape', [0])[0]) if hasattr(keys, 'shape') else int(len(keys))
        if n <= 0:
            return np.zeros((0, 4), dtype=np.int64)
        if n > int(max_points):
            idx = np.linspace(0, n - 1, int(max_points)).astype(np.int64)
            try:
                keys_s = np.asarray(keys[idx])
            except Exception:
                keys_s = np.asarray(keys)[idx]
        else:
            keys_s = np.asarray(keys)
        return _s8_decode_linear_keys_to_coords(keys_s, shp)
    c = _safe_roi_coords_TZYX(src)
    if c.size == 0:
        return np.zeros((0, 4), dtype=np.int64)
    if c.shape[0] > int(max_points):
        idx = np.linspace(0, c.shape[0] - 1, int(max_points)).astype(int)
        c = c[idx]
    return c[:, :4]

try:
    _S8_PREV_BUILD_POINTS_FROM_COORDS_SIDECAR = build_points_from_coords
    def build_points_from_coords(sites, T, Z, Y, X, max_points_per_roi=3000):
        pts = []
        roi_ids = []
        iterable = sites.items() if hasattr(sites, 'items') else enumerate(sites)
        for roi_key, arr in iterable:
            try:
                src = arr[8] if arr is not None and len(arr) > 8 else None
                c = _s8_sample_coords_from_source(src, int(T), int(Z), int(Y), int(X), max_points=max_points_per_roi)
                if c.size == 0:
                    continue
                t = np.clip(c[:, 0].astype(int), 0, max(int(T) - 1, 0))
                z = np.clip(c[:, 1].astype(int), 0, max(int(Z) - 1, 0))
                y = np.clip(c[:, 2].astype(int), 0, max(int(Y) - 1, 0))
                x = np.clip(c[:, 3].astype(int), 0, max(int(X) - 1, 0))
                pts.append(np.stack([t, z, y, x], axis=1))
                roi_ids.extend([int(roi_key)] * len(t))
            except Exception:
                continue
        if not pts:
            return np.zeros((0, 4), dtype=float), {'roi_id': np.array([], dtype=int)}
        pts = np.vstack(pts).astype(float, copy=False)
        return pts, {'roi_id': np.asarray(roi_ids, dtype=int)}
except Exception as _e:
    print('Disk-backed sampled points patch skipped:', _e)

