# Streaming amplitude helper: if a ref is passed, read only one ROI sidecar at a
# time, not the whole experiment.  This keeps filtered/raw traces compatible.
try:
    _S8_PREV_AMP_FROM_COORDS_SIDECAR = amp_from_coords
    def amp_from_coords(coords, img_TZYX, T):
        if _s8_is_coord_ref(coords):
            amp = np.zeros(int(T), dtype=float)
            shp = _s8_coord_ref_shape(coords)
            if img_TZYX is None or shp is None:
                return amp
            keys = _s8_coord_ref_keys(coords)
            if keys.size == 0:
                return amp
            step = 2_000_000
            sums = np.zeros(int(T), dtype=np.float64)
            counts = np.zeros(int(T), dtype=np.float64)
            n = int(getattr(keys, 'shape', [0])[0]) if hasattr(keys, 'shape') else len(keys)
            for start in range(0, n, step):
                chunk = np.asarray(keys[start:min(start + step, n)])
                c = _s8_decode_linear_keys_to_coords(chunk, shp)
                if c.size == 0:
                    continue
                t = c[:, 0].astype(int); z = c[:, 1].astype(int); y = c[:, 2].astype(int); x = c[:, 3].astype(int)
                good = ((t >= 0) & (t < img_TZYX.shape[0]) & (z >= 0) & (z < img_TZYX.shape[1]) &
                        (y >= 0) & (y < img_TZYX.shape[2]) & (x >= 0) & (x < img_TZYX.shape[3]))
                if not np.any(good):
                    continue
                vals = img_TZYX[t[good], z[good], y[good], x[good]].astype(np.float64, copy=False)
                sums += np.bincount(t[good], weights=vals, minlength=int(T))[:int(T)]
                counts += np.bincount(t[good], minlength=int(T)).astype(np.float64)[:int(T)]
            nz = counts > 0
            amp[nz] = sums[nz] / counts[nz]
            return amp
        return _S8_PREV_AMP_FROM_COORDS_SIDECAR(coords, img_TZYX, T)
except Exception as _e:
    print('Disk-backed amplitude patch skipped:', _e)

try:
    _S8_PREV_COMPUTE_AMP_SERIES_DICT_SIDECAR = compute_amp_series_dict
    def compute_amp_series_dict(sites: dict, T: int, img_amp=None):
        out = {}
        for rid, arr in (sites or {}).items():
            meta = arr[13] if arr is not None and len(arr) > 13 and isinstance(arr[13], dict) else {}
            mt = meta.get('meanint_t', None)
            # For filtered traces, meanint_t is already computed during ROI
            # assembly.  Use it rather than rereading sidecars.
            if mt is not None and len(mt) == int(T) and img_amp is None:
                out[int(rid)] = np.asarray(mt, dtype=float)
                continue
            src = arr[8] if arr is not None and len(arr) > 8 else None
            if src is None or img_amp is None:
                out[int(rid)] = np.asarray(mt, dtype=float) if mt is not None and len(mt) == int(T) else np.zeros(int(T), dtype=float)
            else:
                out[int(rid)] = amp_from_coords(src, img_amp, int(T))
        return out
except Exception as _e:
    print('Disk-backed amp-series patch skipped:', _e)


