def _s8_get_disk_backed_roi_coords(manifest_or_combined, channel, roi_id):
    """Public helper for notebooks/visualizer debugging: exact coords for one ROI."""
    try:
        data = manifest_or_combined or {}
        if isinstance(data, dict) and data.get('format') == 's8_live_disk_backed_manifest':
            data = _s8_manifest_channel_view(data, channel=channel)
        if isinstance(data, dict) and 'channels' in data:
            chd = data['channels'].get(int(channel), data['channels'].get(str(int(channel))))
            if chd and 'rois' in chd:
                rois = chd.get('rois') or {}
                arr = rois.get(int(roi_id), rois.get(str(int(roi_id))))
                if arr is not None and len(arr) > 8:
                    return _safe_roi_coords_TZYX(arr[8])
        if isinstance(data, dict) and 'rois' in data:
            rois = data.get('rois') or {}
            arr = rois.get(int(roi_id), rois.get(str(int(roi_id))))
            if arr is not None and len(arr) > 8:
                return _safe_roi_coords_TZYX(arr[8])
    except Exception:
        pass
    return np.zeros((0, 4), dtype=np.int64)

