# --- BEGIN PATCH: GENERAL-PURPOSE PICKLE ROI VIEWER ---
# The previous dedicated hypervolume viewer was centered on intersect_report_pairs.
# Keep that paired-channel view, but add a normal single-ROI/channel viewer so
# one-channel pickles, channel manifests, and non-intersect exports can inspect
# full coordinate-backed hypervolumes with the same trace + 3D display workflow.

def _s8_pviz_channel_keys_any(data):
    try:
        if not isinstance(data, dict):
            return []
        channels = data.get('channels', None)
        if isinstance(channels, dict) and channels:
            out = []
            for k in channels.keys():
                try:
                    out.append(int(k))
                except Exception:
                    pass
            return sorted(set(out))
        if 'rois' in data:
            meta = data.get('metadata', {}) or {}
            for key in ('channel_index', 'manifest_channel_view', 'export_channel', 'channel'):
                try:
                    return [int(meta.get(key))]
                except Exception:
                    pass
            return [0]
    except Exception:
        pass
    return []


def _s8_pviz_channel_view_any(data, channel=None):
    try:
        if isinstance(data, dict) and data.get('format') == 's8_live_disk_backed_manifest':
            return _s8_manifest_channel_view(data, channel=channel)
    except Exception:
        pass
    try:
        if isinstance(data, dict) and isinstance(data.get('channels', None), dict):
            channels = data.get('channels') or {}
            if channel is None:
                ch = _s8_pviz_channel_keys_any(data)[0]
            else:
                ch = int(channel)
            chd = channels.get(ch, channels.get(str(ch)))
            if isinstance(chd, dict):
                view = dict(data)
                view['metadata'] = dict(chd.get('metadata', {}) or {})
                view['rois'] = chd.get('rois', {}) or {}
                view['coordination'] = chd.get('coordination', {}) or {}
                view['propagation'] = chd.get('propagation', {}) or {}
                view['fingerprint'] = chd.get('fingerprint', {}) or {}
                view['displacements'] = chd.get('displacements', {}) or {}
                view.setdefault('metadata', {})['manifest_channel_view'] = int(ch)
                return view
    except Exception:
        pass
    return data


def _s8_pviz_rois_from_channel_any(data, channel=None):
    try:
        view = _s8_pviz_channel_view_any(data, channel=channel)
        rois = view.get('rois', {}) if isinstance(view, dict) else {}
        return rois or {}
    except Exception:
        return {}


def _s8_pviz_sorted_roi_ids_any(rois):
    ids = []
    try:
        for k in (rois.keys() if hasattr(rois, 'keys') else range(len(rois))):
            try:
                ids.append(int(k))
            except Exception:
                pass
    except Exception:
        pass
    return sorted(set(ids))


def _s8_pviz_get_roi_arr_any(data, channel, roi_id):
    try:
        rois = _s8_pviz_rois_from_channel_any(data, channel=channel)
        rid = int(roi_id)
        if hasattr(rois, 'get'):
            arr = rois.get(rid, rois.get(str(rid)))
        else:
            arr = rois[rid]
        return arr
    except Exception:
        return None


def _s8_pviz_roi_label_any(data, channel, roi_id):
    try:
        arr = _s8_pviz_get_roi_arr_any(data, channel, roi_id)
        if arr is None:
            return f'ROI {int(roi_id)}'
        meta = arr[13] if len(arr) > 13 and isinstance(arr[13], dict) else {}
        life = meta.get('lifetime_frames', arr[3] if len(arr) > 3 else '')
        max_area = arr[1] if len(arr) > 1 else ''
        nvox = meta.get('coords_n_voxels', '')
        pieces = [f'ROI {int(roi_id)}']
        try:
            pieces.append(f'duration={int(life)}')
        except Exception:
            pass
        try:
            pieces.append(f'peak={float(max_area):.0f}')
        except Exception:
            pass
        try:
            if str(nvox) != '':
                pieces.append(f'voxels={int(nvox)}')
        except Exception:
            pass
        return '  '.join(pieces)
    except Exception:
        return f'ROI {roi_id}'


def _s8_pviz_roi_series_any(data, channel, roi_id):
    arr = _s8_pviz_get_roi_arr_any(data, channel, roi_id)
    if arr is None:
        return {}, 0
    try:
        view = _s8_pviz_channel_view_any(data, channel=channel)
        T = int((_s8_pviz_meta_TZYX(view) or (0, 0, 0, 0))[0])
    except Exception:
        T = 0
    meta = {}
    try:
        if len(arr) > 13 and isinstance(arr[13], dict):
            meta = arr[13]
    except Exception:
        meta = {}
    def _vec(v):
        try:
            return np.asarray(v, dtype=float).reshape(-1)
        except Exception:
            return np.zeros(0, dtype=float)
    area_t = _vec(meta.get('area_t', []))
    meanint = _vec(meta.get('meanint_t', []))
    if area_t.size == 0:
        try:
            area_t = _vec(arr[10][1]) if len(arr) > 10 and np.size(arr[10]) else np.zeros(0, dtype=float)
        except Exception:
            area_t = np.zeros(0, dtype=float)
    if meanint.size == 0:
        try:
            meanint = _vec(arr[4])
        except Exception:
            meanint = np.zeros(0, dtype=float)
    T = int(max(T, area_t.size, meanint.size, 1))
    return {'area_t': area_t, 'meanint_t': meanint, 'meta': meta}, T


def _s8_pviz_coord_ref_with_pickle_fallback(ref, data=None, pickle_path=None):
    # If the sidecar folder was moved with the pickle, try resolving ref.relpath
    # next to the pickle before giving up.  Absolute paths still win.
    try:
        if not _s8_is_coord_ref(ref):
            return ref
        if _s8_coord_ref_path(ref) and os.path.exists(str(_s8_coord_ref_path(ref))):
            return ref
        rel = ref.get('relpath') or ref.get('relative_path')
        if not rel:
            return ref
        candidates = []
        if pickle_path:
            pdir = Path(str(pickle_path)).resolve().parent
            candidates.append(pdir / rel)
            candidates.append(pdir.parent / rel)
        try:
            meta = (data or {}).get('metadata', {}) or {}
            root = meta.get('coordinate_sidecar_store_root') or meta.get('coordinate_store_root')
            if root:
                candidates.append(Path(str(root)) / rel)
        except Exception:
            pass
        for cand in candidates:
            try:
                if cand.exists():
                    out = dict(ref)
                    out['path'] = str(cand)
                    out['store_root'] = str(cand.parent.parent if cand.parent.name.startswith('coords_ch') else cand.parent)
                    return out
            except Exception:
                pass
    except Exception:
        pass
    return ref


def _s8_pviz_roi_coords_any(data, channel, roi_id, time=None, pickle_path=None):
    try:
        arr = _s8_pviz_get_roi_arr_any(data, channel, roi_id)
        if arr is None or len(arr) <= 8:
            return np.zeros((0, 4), dtype=float)
        src = arr[8]
        src = _s8_pviz_coord_ref_with_pickle_fallback(src, data=data, pickle_path=pickle_path)
        if _s8_is_coord_ref(src):
            return _s8_coord_ref_to_coords(src, time=time).astype(float, copy=False)
        coords = _safe_roi_coords_TZYX(src).astype(float, copy=False)
        if time is not None and coords.size:
            coords = coords[coords[:, 0].astype(int) == int(time)]
        return coords
    except Exception:
        return np.zeros((0, 4), dtype=float)


def _s8_pviz_install_general_roi_viewer(self):
    try:
        self.roi_view_group = QtWidgets.QGroupBox('General hypervolume / ROI viewer')
        self.roi_view_group.setCheckable(False)
        gv = QtWidgets.QVBoxLayout(self.roi_view_group)
        try:
            gv.setContentsMargins(6, 6, 6, 6)
            gv.setSpacing(4)
        except Exception:
            pass

        row0 = QtWidgets.QHBoxLayout()
        row0.addWidget(QtWidgets.QLabel('Channel:'))
        self.cmb_roi_channel = QtWidgets.QComboBox()
        self.cmb_roi_channel.setMinimumWidth(120)
        row0.addWidget(self.cmb_roi_channel)
        row0.addWidget(QtWidgets.QLabel('ROI:'))
        self.cmb_roi_single = QtWidgets.QComboBox()
        row0.addWidget(self.cmb_roi_single, 1)
        self.chk_roi_alltime = QtWidgets.QCheckBox('Show all active times')
        self.chk_roi_alltime.setChecked(False)
        row0.addWidget(self.chk_roi_alltime)
        self.btn_roi_refresh = QtWidgets.QPushButton('Refresh ROI view')
        row0.addWidget(self.btn_roi_refresh)
        gv.addLayout(row0)

        row1 = QtWidgets.QHBoxLayout()
        row1.addWidget(QtWidgets.QLabel('Time:'))
        self.slider_roi_t = QtWidgets.QSlider(Qt.Horizontal)
        self.slider_roi_t.setRange(0, 0)
        row1.addWidget(self.slider_roi_t, 1)
        self.spin_roi_t = QtWidgets.QSpinBox()
        self.spin_roi_t.setRange(0, 0)
        self.spin_roi_t.setMaximumWidth(90)
        row1.addWidget(self.spin_roi_t)
        self.lbl_roi_hint = QtWidgets.QLabel('Load any S8 pickle or live manifest to inspect ROI traces and voxel coordinates.')
        self.lbl_roi_hint.setWordWrap(True)
        row1.addWidget(self.lbl_roi_hint, 1)
        gv.addLayout(row1)

        split_r = QtWidgets.QSplitter(Qt.Horizontal)
        self.fig_roi_trace = Figure(figsize=(5.4, 3.4), dpi=105, constrained_layout=True)
        self.canvas_roi_trace = FigureCanvas(self.fig_roi_trace)
        self.fig_roi_3d = Figure(figsize=(4.4, 3.4), dpi=105, constrained_layout=True)
        self.canvas_roi_3d = FigureCanvas(self.fig_roi_3d)
        left = QtWidgets.QWidget(); left.setLayout(QtWidgets.QVBoxLayout())
        right = QtWidgets.QWidget(); right.setLayout(QtWidgets.QVBoxLayout())
        left.layout().addWidget(self.canvas_roi_trace)
        right.layout().addWidget(self.canvas_roi_3d)
        try:
            _s8_pviz_add_canvas_toolbar(self, self.canvas_roi_trace, '_s8_roi_trace_toolbar')
            _s8_pviz_add_canvas_toolbar(self, self.canvas_roi_3d, '_s8_roi_3d_toolbar')
        except Exception:
            pass
        split_r.addWidget(left); split_r.addWidget(right); split_r.setSizes([610, 430])
        gv.addWidget(split_r, 1)

        inserted = False
        try:
            if hasattr(self, 'intersect_group'):
                idx = self.layout().indexOf(self.intersect_group)
                if idx >= 0:
                    self.layout().insertWidget(idx, self.roi_view_group, 1)
                    inserted = True
        except Exception:
            inserted = False
        if not inserted:
            try:
                for i in range(self.layout().count()):
                    item = self.layout().itemAt(i)
                    w = item.widget() if item is not None else None
                    if isinstance(w, QtWidgets.QSplitter):
                        self.layout().insertWidget(i, self.roi_view_group, 1)
                        inserted = True
                        break
            except Exception:
                inserted = False
        if not inserted:
            self.layout().addWidget(self.roi_view_group, 1)

        self.cmb_roi_channel.currentIndexChanged.connect(self._s8_pviz_update_roi_list)
        self.cmb_roi_single.currentIndexChanged.connect(self.refresh_roi_view)
        self.btn_roi_refresh.clicked.connect(self.refresh_roi_view)
        self.chk_roi_alltime.toggled.connect(self.refresh_roi_view)
        self.slider_roi_t.valueChanged.connect(self._sync_roi_time_from_slider)
        self.spin_roi_t.valueChanged.connect(self._sync_roi_time_from_spin)
        self._s8_roi_channels = []
    except Exception as e:
        print('General ROI pickle viewer UI install skipped:', e)


def _s8_pviz_selected_channel(self):
    try:
        data = self.cmb_roi_channel.currentData(_s8_qt_role('UserRole'))
    except Exception:
        try:
            data = self.cmb_roi_channel.currentData()
        except Exception:
            data = None
    try:
        return int(data)
    except Exception:
        try:
            return int(str(self.cmb_roi_channel.currentText()).split()[0].replace('Ch', '').replace(':', ''))
        except Exception:
            keys = _s8_pviz_channel_keys_any(getattr(self, 'data', None))
            return int(keys[0]) if keys else 0


def _s8_pviz_selected_roi(self):
    try:
        data = self.cmb_roi_single.currentData(_s8_qt_role('UserRole'))
    except Exception:
        try:
            data = self.cmb_roi_single.currentData()
        except Exception:
            data = None
    try:
        return int(data)
    except Exception:
        try:
            return int(str(self.cmb_roi_single.currentText()).split()[1])
        except Exception:
            return None


def _s8_pviz_update_roi_controls(self):
    try:
        channels = _s8_pviz_channel_keys_any(getattr(self, 'data', None))
        self._s8_roi_channels = channels
        cur = _s8_pviz_selected_channel(self) if self.cmb_roi_channel.count() else (channels[0] if channels else 0)
        self.cmb_roi_channel.blockSignals(True)
        self.cmb_roi_channel.clear()
        for ch in channels:
            rois = _s8_pviz_rois_from_channel_any(self.data, channel=ch)
            label = f'Ch {int(ch)}  ({len(rois)} ROIs)'
            self.cmb_roi_channel.addItem(label)
            idx = self.cmb_roi_channel.count() - 1
            try:
                self.cmb_roi_channel.setItemData(idx, int(ch), _s8_qt_role('UserRole'))
            except Exception:
                pass
        if channels:
            target = cur if cur in channels else channels[0]
            for i, ch in enumerate(channels):
                if int(ch) == int(target):
                    self.cmb_roi_channel.setCurrentIndex(i)
                    break
        self.cmb_roi_channel.blockSignals(False)
        self._s8_pviz_update_roi_list()
    except Exception as e:
        try:
            self.lbl_roi_hint.setText(f'ROI viewer control update error: {e}')
        except Exception:
            pass


def _s8_pviz_update_roi_list(self, *_):
    try:
        ch = _s8_pviz_selected_channel(self)
        rois = _s8_pviz_rois_from_channel_any(getattr(self, 'data', None), channel=ch)
        ids = _s8_pviz_sorted_roi_ids_any(rois)
        cur = _s8_pviz_selected_roi(self)
        self.cmb_roi_single.blockSignals(True)
        self.cmb_roi_single.clear()
        for rid in ids:
            self.cmb_roi_single.addItem(_s8_pviz_roi_label_any(self.data, ch, rid))
            idx = self.cmb_roi_single.count() - 1
            try:
                self.cmb_roi_single.setItemData(idx, int(rid), _s8_qt_role('UserRole'))
            except Exception:
                pass
        if ids:
            target = cur if cur in ids else ids[0]
            for i, rid in enumerate(ids):
                if int(rid) == int(target):
                    self.cmb_roi_single.setCurrentIndex(i)
                    break
        self.cmb_roi_single.blockSignals(False)
        view = _s8_pviz_channel_view_any(getattr(self, 'data', None), channel=ch)
        T = int((_s8_pviz_meta_TZYX(view) or (0, 0, 0, 0))[0])
        rid = _s8_pviz_selected_roi(self)
        if rid is not None:
            _, T2 = _s8_pviz_roi_series_any(self.data, ch, rid)
            T = max(int(T), int(T2))
        T = max(1, int(T or 1))
        old_t = int(self.spin_roi_t.value()) if hasattr(self, 'spin_roi_t') else 0
        self.slider_roi_t.blockSignals(True); self.spin_roi_t.blockSignals(True)
        self.slider_roi_t.setRange(0, max(0, T - 1))
        self.spin_roi_t.setRange(0, max(0, T - 1))
        self.slider_roi_t.setValue(max(0, min(old_t, T - 1)))
        self.spin_roi_t.setValue(max(0, min(old_t, T - 1)))
        self.slider_roi_t.blockSignals(False); self.spin_roi_t.blockSignals(False)
    except Exception:
        pass
    try:
        self.refresh_roi_view()
    except Exception:
        pass


def _s8_pviz_sync_roi_time_from_slider(self, val):
    try:
        self.spin_roi_t.blockSignals(True)
        self.spin_roi_t.setValue(int(val))
        self.spin_roi_t.blockSignals(False)
    except Exception:
        pass
    self.refresh_roi_view()


def _s8_pviz_sync_roi_time_from_spin(self, val):
    try:
        self.slider_roi_t.blockSignals(True)
        self.slider_roi_t.setValue(int(val))
        self.slider_roi_t.blockSignals(False)
    except Exception:
        pass
    self.refresh_roi_view()


def _s8_pviz_refresh_roi_view(self, *_):
    if not hasattr(self, 'fig_roi_trace'):
        return
    self.fig_roi_trace.clear(); self.fig_roi_3d.clear()
    ax_v = self.fig_roi_trace.add_subplot(2, 1, 1)
    ax_i = self.fig_roi_trace.add_subplot(2, 1, 2)
    ax3 = self.fig_roi_3d.add_subplot(1, 1, 1, projection='3d')
    if getattr(self, 'data', None) is None:
        ax_v.text(0.5, 0.5, 'Load an S8 pickle or manifest', ha='center', va='center', transform=ax_v.transAxes)
        ax_i.axis('off'); ax3.set_axis_off()
        try:
            self.lbl_roi_hint.setText('Load any S8 pickle or live manifest to inspect ROI traces and voxel coordinates.')
        except Exception:
            pass
        self.canvas_roi_trace.draw_idle(); self.canvas_roi_3d.draw_idle()
        return
    try:
        ch = _s8_pviz_selected_channel(self)
        rid = _s8_pviz_selected_roi(self)
        if rid is None:
            ax_v.text(0.5, 0.5, 'No ROI available for this channel', ha='center', va='center', transform=ax_v.transAxes)
            ax_i.axis('off'); ax3.set_axis_off()
            self.canvas_roi_trace.draw_idle(); self.canvas_roi_3d.draw_idle()
            return
        ser, T = _s8_pviz_roi_series_any(self.data, ch, rid)
        T = max(1, int(T))
        t_now = int(self.spin_roi_t.value()) if hasattr(self, 'spin_roi_t') else 0
        t_now = max(0, min(t_now, T - 1))
        x = np.arange(T)
        area = _s8_pviz_series_vec(ser, 'area_t', T)
        meanint = _s8_pviz_series_vec(ser, 'meanint_t', T)
        ax_v.plot(x, area, lw=1.6, label=f'Ch{ch} ROI {rid}')
        ax_v.axvline(t_now, ls='--', lw=1)
        ax_v.set_title('Hypervolume voxels vs time')
        ax_v.set_xlabel('time (frame)'); ax_v.set_ylabel('voxels')
        ax_v.legend(loc='best', fontsize=8, frameon=False)
        ax_v.grid(True, alpha=0.2)
        ax_i.plot(x, meanint, lw=1.6, label=f'Ch{ch} ROI {rid} mean intensity')
        ax_i.axvline(t_now, ls='--', lw=1)
        ax_i.set_title('Mean intensity vs time')
        ax_i.set_xlabel('time (frame)'); ax_i.set_ylabel('intensity (a.u.)')
        ax_i.legend(loc='best', fontsize=8, frameon=False)
        ax_i.grid(True, alpha=0.2)

        show_all = bool(self.chk_roi_alltime.isChecked()) if hasattr(self, 'chk_roi_alltime') else False
        coords = _s8_pviz_roi_coords_any(self.data, ch, rid, time=None if show_all else t_now, pickle_path=getattr(self, 'path', None))
        alpha = 0.18 if show_all else 0.75
        title = f'Ch{ch} ROI {rid}: all active voxels' if show_all else f'Ch{ch} ROI {rid}: current voxels at t={t_now}'
        shown = 0
        total = int(coords.shape[0]) if coords is not None and np.asarray(coords).ndim == 2 else 0
        if total:
            coords = np.asarray(coords, dtype=float)
            max_points = 120000 if show_all else 90000
            if coords.shape[0] > max_points:
                idx = np.linspace(0, coords.shape[0] - 1, int(max_points)).astype(int)
                coords = coords[idx]
            shown = int(coords.shape[0])
            z = coords[:, 1].astype(float); y = coords[:, 2].astype(float); xx = coords[:, 3].astype(float)
            cvals = coords[:, 0].astype(float) if show_all else z
            ax3.scatter(xx, y, z, c=cvals, cmap='viridis', s=max(1, min(10, int(self.spin_size.value()))), alpha=alpha)
            ax3.set_xlabel('X'); ax3.set_ylabel('Y'); ax3.set_zlabel('Z')
            try:
                ax3.set_box_aspect((max(1, np.nanmax(xx)-np.nanmin(xx)), max(1, np.nanmax(y)-np.nanmin(y)), max(1, np.nanmax(z)-np.nanmin(z))))
            except Exception:
                pass
        else:
            ax3.text2D(0.5, 0.5, f'No saved coordinates for Ch{ch} ROI {rid}' + ('' if show_all else f' at t={t_now}'), ha='center', va='center', transform=ax3.transAxes)
            ax3.set_axis_off()
        ax3.set_title(title)
        try:
            vox_now = float(area[t_now]) if 0 <= t_now < len(area) else 0.0
            inten_now = float(meanint[t_now]) if 0 <= t_now < len(meanint) else 0.0
            if show_all:
                self.lbl_roi_hint.setText(f'Ch{ch} ROI {rid}; displaying {shown:,} of {total:,} saved voxels across all active times. Coordinates remain disk-backed when available.')
            else:
                self.lbl_roi_hint.setText(f'Ch{ch} ROI {rid}; t={t_now}; voxels={vox_now:.0f}; intensity={inten_now:.3g}; displayed coords={shown:,}.')
        except Exception:
            pass
    except Exception as e:
        ax_v.text(0.5, 0.5, f'ROI viewer error:\n{e}', ha='center', va='center', transform=ax_v.transAxes, wrap=True)
        ax_i.axis('off'); ax3.set_axis_off()
        try:
            self.lbl_roi_hint.setText(f'ROI viewer error: {e}')
        except Exception:
            pass
    self.canvas_roi_trace.draw_idle(); self.canvas_roi_3d.draw_idle()

try:
    _S8_PVIZ_PREV_DIALOG_INIT_GENERAL_ROI = S8PickleVisualizationDialog.__init__
    def _s8_pviz_dialog_init_with_general_roi(self, *args, **kwargs):
        _S8_PVIZ_PREV_DIALOG_INIT_GENERAL_ROI(self, *args, **kwargs)
        _s8_pviz_install_general_roi_viewer(self)
    S8PickleVisualizationDialog.__init__ = _s8_pviz_dialog_init_with_general_roi
    S8PickleVisualizationDialog._s8_pviz_update_roi_controls = _s8_pviz_update_roi_controls
    S8PickleVisualizationDialog._s8_pviz_update_roi_list = _s8_pviz_update_roi_list
    S8PickleVisualizationDialog._sync_roi_time_from_slider = _s8_pviz_sync_roi_time_from_slider
    S8PickleVisualizationDialog._sync_roi_time_from_spin = _s8_pviz_sync_roi_time_from_spin
    S8PickleVisualizationDialog.refresh_roi_view = _s8_pviz_refresh_roi_view

    _S8_PVIZ_PREV_POPULATE_CONTROLS_GENERAL_ROI = S8PickleVisualizationDialog._populate_controls
    def _s8_pviz_populate_controls_with_general_roi(self, *args, **kwargs):
        out = _S8_PVIZ_PREV_POPULATE_CONTROLS_GENERAL_ROI(self, *args, **kwargs)
        try:
            _s8_pviz_update_roi_controls(self)
        except Exception as e:
            print('General ROI pickle viewer controls refresh skipped:', e)
        return out
    S8PickleVisualizationDialog._populate_controls = _s8_pviz_populate_controls_with_general_roi
except Exception as _e:
    print('General-purpose pickle ROI viewer patch skipped:', _e)
# --- END PATCH: GENERAL-PURPOSE PICKLE ROI VIEWER ---


# --- BEGIN PATCH: UNIFIED PICKLE ROI / INTERSECT PAIR VIEWER ---
# Keep one dedicated hypervolume viewer in the pickle visualizer.  Single-channel
# ROI viewing and paired-channel intersect viewing now share the same trace + 3D
# canvases instead of creating a separate multichannel pair plot panel.

def _s8_pviz_pairs_any(data):
    try:
        if isinstance(data, dict):
            pairs = list(data.get('intersect_report_pairs', []) or [])
            return [p for p in pairs if isinstance(p, dict)]
    except Exception:
        pass
    return []


def _s8_pviz_pair_T_any(data, pair):
    T = 0
    try:
        T = int((_s8_pviz_meta_TZYX(data) or (0, 0, 0, 0))[0])
    except Exception:
        T = 0
    try:
        sa = (pair or {}).get('series_a', {}) or {}
        sb = (pair or {}).get('series_b', {}) or {}
        for ser in (sa, sb):
            for key in ('area_t', 'meanint_t', 'amp_filt', 'amp_raw'):
                try:
                    T = max(T, int(np.asarray(ser.get(key, [])).reshape(-1).size))
                except Exception:
                    pass
    except Exception:
        pass
    return max(1, int(T or 1))


def _s8_pviz_current_unified_pair(self):
    try:
        pairs = getattr(self, '_s8_unified_pairs', []) or []
        idx = int(self.cmb_roi_pair.currentIndex())
        if 0 <= idx < len(pairs):
            return pairs[idx]
    except Exception:
        pass
    return None


def _s8_pviz_unified_mode(self):
    try:
        txt = str(self.cmb_roi_view_mode.currentText()).strip().lower()
        if 'pair' in txt:
            return 'pair'
    except Exception:
        pass
    return 'single'


def _s8_pviz_set_unified_time_range(self, T):
    T = max(1, int(T or 1))
    try:
        old_t = int(self.spin_roi_t.value())
    except Exception:
        old_t = 0
    old_t = max(0, min(old_t, T - 1))
    try:
        self.slider_roi_t.blockSignals(True)
        self.spin_roi_t.blockSignals(True)
        self.slider_roi_t.setRange(0, T - 1)
        self.spin_roi_t.setRange(0, T - 1)
        self.slider_roi_t.setValue(old_t)
        self.spin_roi_t.setValue(old_t)
        self.slider_roi_t.blockSignals(False)
        self.spin_roi_t.blockSignals(False)
    except Exception:
        pass


def _s8_pviz_pair_coords_unified(self, pair, side, time=None):
    side = str(side).lower()
    try:
        ch = int((pair or {}).get('channel_a' if side == 'a' else 'channel_b', -1))
        rid = int((pair or {}).get('roi_a' if side == 'a' else 'roi_b', -1))
    except Exception:
        ch, rid = -1, -1
    try:
        coords = _s8_pviz_roi_coords_any(getattr(self, 'data', None), ch, rid, time=time, pickle_path=getattr(self, 'path', None))
        coords = np.asarray(coords, dtype=float)
        if coords.ndim == 2 and coords.shape[0] > 0 and coords.shape[1] >= 4:
            return coords[:, :4], 'roi/channel coordinate store'
    except Exception:
        pass
    try:
        coords, source = _s8_pviz_resolve_pair_coords(self, pair, side)
        coords = np.asarray(coords, dtype=float)
        if coords.ndim == 2 and coords.shape[0] > 0 and coords.shape[1] >= 4:
            coords = coords[:, :4]
            if time is not None:
                coords = coords[coords[:, 0].astype(int) == int(time)]
            return coords, source
    except Exception:
        pass
    try:
        coords = _s8_pviz_coords_from_pair_or_export(getattr(self, 'data', None), pair, side)
        coords = np.asarray(coords, dtype=float)
        if coords.ndim == 2 and coords.shape[0] > 0 and coords.shape[1] >= 4:
            coords = coords[:, :4]
            if time is not None:
                coords = coords[coords[:, 0].astype(int) == int(time)]
            return coords, 'pair/export fallback'
    except Exception:
        pass
    return np.zeros((0, 4), dtype=float), 'unavailable'


def _s8_pviz_plot_coords_unified(ax3, coords, color, label, t_now, show_all, point_size, max_points=80000):
    try:
        coords = np.asarray(coords, dtype=float)
        if coords.ndim == 1 and coords.size % 4 == 0:
            coords = coords.reshape(-1, 4)
        if coords.ndim != 2 or coords.shape[1] < 4 or coords.shape[0] == 0:
            return False, 0, 0, False
        coords = coords[:, :4]
        total = int(coords.shape[0])
        if bool(show_all):
            sel = coords
            is_current = False
            alpha = 0.20
        else:
            sel = coords[coords[:, 0].astype(int) == int(t_now)]
            is_current = bool(sel.size)
            if sel.size == 0:
                sel = coords
                alpha = 0.12
            else:
                alpha = 0.78
        if sel.shape[0] > int(max_points):
            idx = np.linspace(0, sel.shape[0] - 1, int(max_points)).astype(int)
            sel = sel[idx]
        if sel.shape[0] == 0:
            return False, total, 0, is_current
        z = sel[:, 1].astype(float)
        y = sel[:, 2].astype(float)
        x = sel[:, 3].astype(float)
        ax3.scatter(x, y, z, color=color, s=max(1, min(10, int(point_size))), alpha=alpha, label=label)
        return True, total, int(sel.shape[0]), is_current
    except Exception:
        return False, 0, 0, False


def _s8_pviz_hide_legacy_intersect_panel(self):
    try:
        g = getattr(self, 'intersect_group', None)
        if g is not None:
            try:
                self.layout().removeWidget(g)
            except Exception:
                pass
            g.setVisible(False)
            g.setMaximumHeight(0)
    except Exception:
        pass


def _s8_pviz_install_unified_pair_controls(self):
    if getattr(self, '_s8_unified_pair_controls_installed', False):
        return
    if not hasattr(self, 'roi_view_group'):
        return
    try:
        lay = self.roi_view_group.layout()
        self.roi_view_group.setTitle('Hypervolume / ROI viewer')
        row = QtWidgets.QHBoxLayout()
        row.addWidget(QtWidgets.QLabel('View:'))
        self.cmb_roi_view_mode = QtWidgets.QComboBox()
        self.cmb_roi_view_mode.addItem('Single ROI')
        row.addWidget(self.cmb_roi_view_mode)
        row.addWidget(QtWidgets.QLabel('Intersect pair:'))
        self.cmb_roi_pair = QtWidgets.QComboBox()
        row.addWidget(self.cmb_roi_pair, 1)
        lay.insertLayout(0, row)
        self.cmb_roi_view_mode.currentIndexChanged.connect(self._s8_pviz_on_unified_mode_changed)
        self.cmb_roi_pair.currentIndexChanged.connect(self._s8_pviz_on_unified_pair_changed)
        self._s8_unified_pairs = []
        self._s8_unified_pair_controls_installed = True
    except Exception as e:
        print('Unified ROI/pair controls install skipped:', e)


def _s8_pviz_on_unified_mode_changed(self, *_):
    try:
        if _s8_pviz_unified_mode(self) == 'pair':
            pair = _s8_pviz_current_unified_pair(self)
            _s8_pviz_set_unified_time_range(self, _s8_pviz_pair_T_any(getattr(self, 'data', None), pair))
        else:
            self._s8_pviz_update_roi_list()
            return
    except Exception:
        pass
    try:
        self.refresh_roi_view()
    except Exception:
        pass


def _s8_pviz_on_unified_pair_changed(self, *_):
    try:
        pair = _s8_pviz_current_unified_pair(self)
        _s8_pviz_set_unified_time_range(self, _s8_pviz_pair_T_any(getattr(self, 'data', None), pair))
    except Exception:
        pass
    try:
        self.refresh_roi_view()
    except Exception:
        pass


def _s8_pviz_update_unified_pair_controls(self):
    try:
        _s8_pviz_hide_legacy_intersect_panel(self)
        if not getattr(self, '_s8_unified_pair_controls_installed', False):
            _s8_pviz_install_unified_pair_controls(self)
        pairs = _s8_pviz_pairs_any(getattr(self, 'data', None))
        self._s8_unified_pairs = pairs
        if not hasattr(self, 'cmb_roi_view_mode') or not hasattr(self, 'cmb_roi_pair'):
            return
        old_mode = _s8_pviz_unified_mode(self)
        old_pair = int(self.cmb_roi_pair.currentIndex()) if self.cmb_roi_pair.count() else 0
        self.cmb_roi_view_mode.blockSignals(True)
        self.cmb_roi_view_mode.clear()
        self.cmb_roi_view_mode.addItem('Single ROI')
        if pairs:
            self.cmb_roi_view_mode.addItem('Intersect pair')
        default_pair = False
        try:
            meta = (getattr(self, 'data', {}) or {}).get('metadata', {}) or {}
            default_pair = bool(pairs) and bool(meta.get('intersect_mode', False) or meta.get('intersect_pair_count', 0))
        except Exception:
            default_pair = bool(pairs)
        target_mode = 'pair' if (pairs and (old_mode == 'pair' or default_pair)) else 'single'
        self.cmb_roi_view_mode.setCurrentIndex(1 if target_mode == 'pair' and pairs else 0)
        self.cmb_roi_view_mode.blockSignals(False)

        self.cmb_roi_pair.blockSignals(True)
        self.cmb_roi_pair.clear()
        for i, pair in enumerate(pairs):
            self.cmb_roi_pair.addItem(_s8_pviz_pair_label(pair, i))
        if pairs:
            self.cmb_roi_pair.setCurrentIndex(max(0, min(old_pair, len(pairs) - 1)))
        self.cmb_roi_pair.blockSignals(False)
        self.cmb_roi_pair.setEnabled(bool(pairs))
        self.cmb_roi_pair.setVisible(bool(pairs))
        if _s8_pviz_unified_mode(self) == 'pair':
            _s8_pviz_set_unified_time_range(self, _s8_pviz_pair_T_any(getattr(self, 'data', None), _s8_pviz_current_unified_pair(self)))
        try:
            if pairs:
                self.lbl_roi_hint.setText(f'{len(pairs)} intersect pair(s) available. Use the View selector above; paired traces and both channel point clouds appear in this same viewer.')
            else:
                self.lbl_roi_hint.setText('Single-ROI mode. No intersect pairs were found in this pickle.')
        except Exception:
            pass
    except Exception as e:
        print('Unified ROI/pair controls refresh skipped:', e)


def _s8_pviz_refresh_unified_pair_view(self, pair):
    self.fig_roi_trace.clear(); self.fig_roi_3d.clear()
    ax_v = self.fig_roi_trace.add_subplot(2, 1, 1)
    ax_i = self.fig_roi_trace.add_subplot(2, 1, 2)
    ax3 = self.fig_roi_3d.add_subplot(1, 1, 1, projection='3d')
    if pair is None:
        ax_v.text(0.5, 0.5, 'No intersect pair selected', ha='center', va='center', transform=ax_v.transAxes)
        ax_i.axis('off')
        ax3.text2D(0.5, 0.5, 'No intersect pair selected', ha='center', va='center', transform=ax3.transAxes)
        ax3.set_axis_off()
        self.canvas_roi_trace.draw_idle(); self.canvas_roi_3d.draw_idle()
        return
    try:
        T = _s8_pviz_pair_T_any(getattr(self, 'data', None), pair)
        t_now = int(self.spin_roi_t.value()) if hasattr(self, 'spin_roi_t') else 0
        t_now = max(0, min(t_now, T - 1))
        sa = (pair or {}).get('series_a', {}) or {}
        sb = (pair or {}).get('series_b', {}) or {}
        ca = int((pair or {}).get('channel_a', 0)); cb = int((pair or {}).get('channel_b', 1))
        ra = int((pair or {}).get('roi_a', sa.get('roi_id', -1)))
        rb = int((pair or {}).get('roi_b', sb.get('roi_id', -1)))
        x = np.arange(T)
        av = _s8_pviz_series_vec(sa, 'area_t', T); bv = _s8_pviz_series_vec(sb, 'area_t', T)
        ai = _s8_pviz_series_vec(sa, 'amp_filt', T); bi = _s8_pviz_series_vec(sb, 'amp_filt', T)
        if not np.any(np.isfinite(ai)) or np.nanmax(np.abs(ai)) == 0:
            ai = _s8_pviz_series_vec(sa, 'amp_raw', T)
        if not np.any(np.isfinite(bi)) or np.nanmax(np.abs(bi)) == 0:
            bi = _s8_pviz_series_vec(sb, 'amp_raw', T)

        line_a = ax_v.plot(x, av, lw=1.6, label=f'Ch{ca} ROI {ra}')[0]
        line_b = ax_v.plot(x, bv, lw=1.6, label=f'Ch{cb} ROI {rb}')[0]
        color_a = line_a.get_color(); color_b = line_b.get_color()
        ax_v.axvline(t_now, ls='--', lw=1, color='0.35')
        ax_v.set_title('Intersect pair: hypervolume voxels vs time')
        ax_v.set_xlabel('time (frame)'); ax_v.set_ylabel('voxels')
        ax_v.legend(loc='best', fontsize=8, frameon=False)
        ax_v.grid(True, alpha=0.2)

        ax_i.plot(x, ai, lw=1.6, color=color_a, label=f'Ch{ca} ROI {ra} mean intensity')
        ax_i.plot(x, bi, lw=1.6, color=color_b, label=f'Ch{cb} ROI {rb} mean intensity')
        ax_i.axvline(t_now, ls='--', lw=1, color='0.35')
        ax_i.set_title('Intersect pair: mean intensity vs time')
        ax_i.set_xlabel('time (frame)'); ax_i.set_ylabel('intensity (a.u.)')
        ax_i.legend(loc='best', fontsize=8, frameon=False)
        ax_i.grid(True, alpha=0.2)

        show_all = bool(self.chk_roi_alltime.isChecked()) if hasattr(self, 'chk_roi_alltime') else False
        # In paired mode, prefer loading only the current time plane from a
        # disk-backed sidecar.  If that frame has no voxels, fall back to the
        # full ROI so the viewer can still show low-alpha all-time context.
        coords_a, src_a = _s8_pviz_pair_coords_unified(self, pair, 'a', time=None if show_all else t_now)
        coords_b, src_b = _s8_pviz_pair_coords_unified(self, pair, 'b', time=None if show_all else t_now)
        if (not show_all) and (coords_a is None or np.asarray(coords_a).size == 0):
            coords_a, src_a = _s8_pviz_pair_coords_unified(self, pair, 'a', time=None)
        if (not show_all) and (coords_b is None or np.asarray(coords_b).size == 0):
            coords_b, src_b = _s8_pviz_pair_coords_unified(self, pair, 'b', time=None)
        pt_size = int(getattr(self, 'spin_size', QtWidgets.QSpinBox()).value()) if hasattr(self, 'spin_size') else 4
        shown_a, total_a, nshow_a, cur_a = _s8_pviz_plot_coords_unified(ax3, coords_a, color_a, f'Ch{ca} ROI {ra}', t_now, show_all, pt_size)
        shown_b, total_b, nshow_b, cur_b = _s8_pviz_plot_coords_unified(ax3, coords_b, color_b, f'Ch{cb} ROI {rb}', t_now, show_all, pt_size)

        if shown_a or shown_b:
            ax3.set_xlabel('X'); ax3.set_ylabel('Y'); ax3.set_zlabel('Z')
            ax3.legend(loc='best', fontsize=8, frameon=False)
            all_pts = []
            for coords, shown in ((coords_a, shown_a), (coords_b, shown_b)):
                if shown:
                    if show_all:
                        sel = np.asarray(coords, dtype=float)
                    else:
                        sel, _ = _s8_pviz_select_coords_for_time(coords, t_now)
                    if sel.size:
                        all_pts.append(sel[:, :4])
            if all_pts:
                pts = np.vstack(all_pts)
                z = pts[:, 1].astype(float); y = pts[:, 2].astype(float); xx = pts[:, 3].astype(float)
                try:
                    ax3.set_box_aspect((max(1, np.nanmax(xx) - np.nanmin(xx)), max(1, np.nanmax(y) - np.nanmin(y)), max(1, np.nanmax(z) - np.nanmin(z))))
                except Exception:
                    pass
            if show_all:
                ax3.set_title('Intersect pair: all active ROI voxels in 3D')
            elif (shown_a and not cur_a) or (shown_b and not cur_b):
                ax3.set_title(f'Intersect pair: all active voxels shown at low alpha because one ROI has no voxels at t={t_now}')
            else:
                ax3.set_title(f'Intersect pair: current voxels at t={t_now}')
        else:
            ax3.text2D(0.5, 0.54, 'No saved coordinates for this intersect pair', ha='center', va='center', transform=ax3.transAxes)
            ax3.text2D(0.5, 0.44, 'The traces still load; keep the sidecar folder with the pickle for coordinates.', ha='center', va='center', transform=ax3.transAxes)
            ax3.set_axis_off()

        missing = []
        if not shown_a:
            missing.append(f'Ch{ca} ROI {ra} coords unavailable')
        if not shown_b:
            missing.append(f'Ch{cb} ROI {rb} coords unavailable')
        try:
            msg = (
                f'Pair: Ch{ca} ROI {ra} ↔ Ch{cb} ROI {rb}; overlap={int((pair or {}).get("overlap_voxels", 0))} voxels; '
                f't={t_now}; Ch{ca} voxels={float(av[t_now]):.0f}; Ch{cb} voxels={float(bv[t_now]):.0f}; '
                f'Ch{ca} intensity={float(ai[t_now]):.3g}; Ch{cb} intensity={float(bi[t_now]):.3g}; '
                f'displayed={nshow_a:,}/{total_a:,} + {nshow_b:,}/{total_b:,}'
            )
            if missing:
                msg += ' | ' + '; '.join(missing)
            self.lbl_roi_hint.setText(msg)
        except Exception:
            pass
    except Exception as e:
        ax_v.text(0.5, 0.5, f'Unified pair view error:\n{e}', ha='center', va='center', transform=ax_v.transAxes, wrap=True)
        ax_i.axis('off'); ax3.set_axis_off()
        try:
            self.lbl_roi_hint.setText(f'Unified pair view error: {e}')
        except Exception:
            pass
    self.canvas_roi_trace.draw_idle(); self.canvas_roi_3d.draw_idle()


