# --- BEGIN PATCH: EXACT INPUT-STEM LIVE MANIFEST NAME ---
# The live manifest file itself should be named from the analyzed input image,
# not from a generic "s8_live_manifest" prefix/suffix.  For example:
#   /path/my_stack.tif  ->  /path/my_stack_s8_live_analysis/my_stack.p
# Coordinate sidecars remain in the same live-analysis folder.

def _s8_live_input_path_for_manifest(panel):
    try:
        p = getattr(panel, 'last_image_path', None)
        if p:
            return str(p)
    except Exception:
        pass
    try:
        p = globals().get('_S8_LAST_IMAGE_PATH', None)
        if p:
            return str(p)
    except Exception:
        pass
    return None


def _s8_safe_input_stem_for_manifest(panel):
    try:
        src = _s8_live_input_path_for_manifest(panel)
        stem = Path(str(src)).stem if src else ''
        stem = str(stem).strip()
        if not stem:
            stem = 'napari_analysis'
        safe = ''.join(ch if (ch.isalnum() or ch in ('-', '_', '.')) else '_' for ch in stem)
        return safe.strip('._') or 'napari_analysis'
    except Exception:
        return 'napari_analysis'


def _s8_live_manifest_filename(panel):
    """Return the live manifest filename using the input image stem exactly.

    If the analyzed image is `sample.tif`, the manifest is `sample.p`.
    The surrounding folder and metadata still identify it as an S8 live analysis,
    but the pickle filename follows the input file being analyzed.
    """
    return f'{_s8_safe_input_stem_for_manifest(panel)}.p'


def _s8_prepare_live_coord_store(panel):
    try:
        src = _s8_live_input_path_for_manifest(panel)
        if src:
            base_dir = os.path.dirname(str(src)) or getattr(panel, 'last_image_dir', None) or os.getcwd()
            folder = f'{_s8_safe_input_stem_for_manifest(panel)}_s8_live_analysis'
        else:
            base_dir = getattr(panel, 'last_image_dir', None) or os.getcwd()
            folder = 'napari_analysis_s8_live_analysis'
        root = os.path.join(str(base_dir), folder)
        os.makedirs(root, exist_ok=True)
        return root
    except Exception:
        root = os.path.join(os.getcwd(), 'napari_analysis_s8_live_analysis')
        os.makedirs(root, exist_ok=True)
        return root

try:
    _S8_PREV_LOAD_IMAGE_EXACT_INPUT_MANIFEST = PipelinePanel.load_image
    def _s8_load_image_exact_input_manifest(self, *args, **kwargs):
        out = _S8_PREV_LOAD_IMAGE_EXACT_INPUT_MANIFEST(self, *args, **kwargs)
        try:
            p = globals().get('_S8_LAST_IMAGE_PATH', None)
            if p:
                self.last_image_path = str(p)
                self.last_image_dir = os.path.dirname(str(p)) or getattr(self, 'last_image_dir', None)
            self.s8_live_store_dir = _s8_prepare_live_coord_store(self)
            self.s8_live_manifest_path = os.path.join(self.s8_live_store_dir, _s8_live_manifest_filename(self))
        except Exception as e:
            print('Input-named live manifest setup skipped:', e)
        return out
    PipelinePanel.load_image = _s8_load_image_exact_input_manifest
except Exception as _e:
    print('Input-named live manifest load patch skipped:', _e)

try:
    _S8_PREV_BUILD_LIVE_MANIFEST_INPUT_NAMED = _s8_build_live_manifest
    def _s8_build_live_manifest(panel):
        manifest = _S8_PREV_BUILD_LIVE_MANIFEST_INPUT_NAMED(panel)
        try:
            src = _s8_live_input_path_for_manifest(panel)
            if src:
                manifest['input_file'] = str(src)
                manifest.setdefault('metadata', {})['input_file'] = str(src)
            manifest['manifest_filename'] = _s8_live_manifest_filename(panel)
        except Exception:
            pass
        return manifest
except Exception as _e:
    print('Input-named live manifest metadata patch skipped:', _e)
# --- END PATCH: EXACT INPUT-STEM LIVE MANIFEST NAME ---


