# ----- ROI point gating and overlays -----
_S8BOOL_PREV_APPLY_POINTS_COLORS = ROIPanel._apply_points_colors
def _s8bool_apply_points_colors(self, *args, **kwargs):
    if not _s8bool_enabled(self):
        return _S8BOOL_PREV_APPLY_POINTS_COLORS(self, *args, **kwargs)
    if self.points_layer is None or not len(getattr(self.points_layer, 'data', [])):
        return
    pipeline = getattr(self, 'pipeline_panel', None)
    if pipeline is None:
        return _S8BOOL_PREV_APPLY_POINTS_COLORS(self, *args, **kwargs)
    ch_a = int(getattr(self, 'current_channel', getattr(pipeline, 'current_channel', 0)) or 0)
    ch_b = _s8bool_resolve_compare(pipeline, update_selector=False)
    op = _s8bool_op(self)
    roi_prop = self.points_layer.properties.get('roi_id', None)
    if roi_prop is None or len(roi_prop) == 0:
        return
    gate_cache = {}
    names = []
    for rid in roi_prop:
        rid_i = int(rid)
        if rid_i not in gate_cache:
            gate_cache[rid_i] = _s8bool_roi_is_visible(pipeline, ch_a, rid_i, ch_b, op)
        if not gate_cache[rid_i]:
            names.append('__hidden__')
        else:
            names.append(self.class_of_roi.get(rid_i, (0, 'Unclassified'))[1])
    names = np.asarray(names, dtype=object)
    try:
        props = dict(self.points_layer.properties)
        props['class_name'] = names
        self.points_layer.properties = props
        palette = dict(self.class_palette or {})
        palette['__hidden__'] = (0.0, 0.0, 0.0, 0.0)
        self.points_layer.face_color = 'class_name'
        self.points_layer.face_color_cycle = palette
    except Exception:
        pass
    try:
        if '_s8v3i_clear_overlay_caches' in globals():
            _s8v3i_clear_overlay_caches(self)
    except Exception:
        pass
ROIPanel._apply_points_colors = _s8bool_apply_points_colors


_S8BOOL_PREV_UPDATE_ALL_OVERLAY = ROIPanel.update_all_overlay
def _s8bool_update_all_overlay(self, *args, **kwargs):
    if not _s8bool_enabled(self):
        return _S8BOOL_PREV_UPDATE_ALL_OVERLAY(self, *args, **kwargs)
    if self.overlay_all is None or self.sites is None:
        return
    if hasattr(self, 'chk_all') and not self.chk_all.isChecked():
        try:
            self.overlay_all.visible = False
        except Exception:
            pass
        return
    pipeline = getattr(self, 'pipeline_panel', None)
    if pipeline is None:
        return _S8BOOL_PREV_UPDATE_ALL_OVERLAY(self, *args, **kwargs)
    t = int(self.viewer.dims.current_step[0])
    ch_a = int(getattr(self, 'current_channel', getattr(pipeline, 'current_channel', 0)) or 0)
    ch_b = _s8bool_resolve_compare(pipeline, update_selector=False)
    op = _s8bool_op(self)
    if ch_b is None:
        return _S8BOOL_PREV_UPDATE_ALL_OVERLAY(self, *args, **kwargs)

    if op == 'NOT_OVERLAP':
        sites_a = _s8bool_get_sites(pipeline, ch_a)
        idx = _s8bool_active_index(pipeline, ch_a, int(self.T))
        active_rids = idx[t] if 0 <= t < len(idx) else [int(k) for k in sites_a.keys()]
        keep = [rid for rid in active_rids if not _s8bool_has_overlap(pipeline, ch_a, int(rid), ch_b)]
        a = _s8bool_channel_mask(self, ch_a, t, all_time=False, roi_ids=keep)
        b = np.zeros_like(a, dtype=bool)
        labels = _s8bool_operation_labels(a, b, op, roi_has_overlap=False)
    else:
        a = _s8bool_channel_mask(self, ch_a, t, all_time=False)
        b = _s8bool_channel_mask(self, ch_b, t, all_time=False)
        labels = _s8bool_operation_labels(a, b, op)
    labels = _s8bool_apply_thickness(self, labels)

    if _s8bool_layer_is_plane(self.overlay_all):
        data = labels
    else:
        try:
            data = _sinfin_overlay_buffer(self, '_s8bool_all_overlay_buf', (self.T, self.Z, self.Y, self.X))
        except Exception:
            data = np.zeros((self.T, self.Z, self.Y, self.X), dtype=np.uint8)
        data[t] = labels
    try:
        self.overlay_all.color = _s8bool_overlay_colors()
        _s8bool_set_overlay_data(self.overlay_all, data)
        self.overlay_all.visible = True
    except Exception:
        pass
ROIPanel.update_all_overlay = _s8bool_update_all_overlay


_S8BOOL_PREV_UPDATE_SELECTED_OVERLAY = ROIPanel.update_selected_overlay
def _s8bool_update_selected_overlay(self, *args, **kwargs):
    if not _s8bool_enabled(self):
        return _S8BOOL_PREV_UPDATE_SELECTED_OVERLAY(self, *args, **kwargs)
    if self.overlay_sel is None:
        return
    if self.current_roi is None:
        try:
            self.overlay_sel.visible = False
        except Exception:
            pass
        return
    pipeline = getattr(self, 'pipeline_panel', None)
    if pipeline is None:
        return _S8BOOL_PREV_UPDATE_SELECTED_OVERLAY(self, *args, **kwargs)
    op = _s8bool_op(self)
    ch_a = int(getattr(self, 'current_channel', getattr(pipeline, 'current_channel', 0)) or 0)
    ch_b = _s8bool_resolve_compare(pipeline, update_selector=False)
    t_now = int(self.viewer.dims.current_step[0])
    all_time = bool(self.chk_alltime.isChecked()) if hasattr(self, 'chk_alltime') else False
    has_overlap = _s8bool_has_overlap(pipeline, ch_a, int(self.current_roi), ch_b)

    if _s8bool_layer_is_plane(self.overlay_sel):
        a, b = _s8bool_selected_masks(self, t_now, all_time=all_time)
        labels = _s8bool_operation_labels(a, b, op, roi_has_overlap=has_overlap)
        data = _s8bool_apply_thickness(self, labels)
    else:
        try:
            data = _sinfin_overlay_buffer(self, '_s8bool_selected_overlay_buf', (self.T, self.Z, self.Y, self.X))
        except Exception:
            data = np.zeros((self.T, self.Z, self.Y, self.X), dtype=np.uint8)
        times = range(int(self.T)) if all_time else (t_now,)
        for tt in times:
            a, b = _s8bool_selected_masks(self, int(tt), all_time=False)
            data[int(tt)] = _s8bool_apply_thickness(self, _s8bool_operation_labels(a, b, op, roi_has_overlap=has_overlap))
    try:
        self.overlay_sel.color = _s8bool_overlay_colors()
        _s8bool_set_overlay_data(self.overlay_sel, data)
        self.overlay_sel.visible = True
    except Exception:
        pass
ROIPanel.update_selected_overlay = _s8bool_update_selected_overlay


# ----- Paired traces and stats -----
_S8BOOL_PREV_UPDATE_PLOTS = ROIPanel.update_plots
def _s8bool_update_plots(self):
    if not _s8bool_enabled(self):
        return _S8BOOL_PREV_UPDATE_PLOTS(self)
    if self.current_roi is None or self.sites is None:
        self.plots.clear()
        return
    pipeline = getattr(self, 'pipeline_panel', None)
    if pipeline is None:
        return _S8BOOL_PREV_UPDATE_PLOTS(self)
    t_now = int(self.viewer.dims.current_step[0])
    ch_a = int(getattr(self, 'current_channel', getattr(pipeline, 'current_channel', 0)) or 0)
    ch_b = _s8bool_resolve_compare(pipeline, update_selector=False)
    op = _s8bool_op(self)
    area_t, _, _ = self._get_roi_area_metrics(self.current_roi)
    amp_filt = self._get_roi_amp_series_filtered(self.current_roi)
    amp_raw = self._get_roi_amp_series_raw(self.current_roi)
    area_list = [area_t]
    filt_list = [amp_filt]
    raw_list = [amp_raw]
    labels = [f'ch{ch_a} ROI {int(self.current_roi)}']
    if op in ('AND', 'OR', 'XOR') and ch_b is not None:
        for match in pipeline.get_overlapping_rois(ch_a, int(self.current_roi), ch_b=int(ch_b)):
            roi_b = int(match['roi_id'])
            st_b = pipeline._get_channel_state(int(ch_b))
            arr_b = (st_b.get('sites', {}) or {}).get(roi_b)
            if arr_b is None:
                continue
            try:
                area_list.append(np.asarray(arr_b[13].get('area_t', []), dtype=float))
            except Exception:
                area_list.append(np.asarray([], dtype=float))
            filt_list.append(np.asarray((st_b.get('amp_dict_filt', {}) or {}).get(roi_b, []), dtype=float))
            raw_list.append(np.asarray((st_b.get('amp_dict_raw', {}) or {}).get(roi_b, []), dtype=float))
            labels.append(f'ch{int(ch_b)} ROI {roi_b}')
    self.plots.update_data(area_list, filt_list, raw_list, current_t=t_now, labels=labels)
ROIPanel.update_plots = _s8bool_update_plots


_S8BOOL_PREV_UPDATE_STATS = ROIPanel.update_stats
def _s8bool_update_stats(self):
    _S8BOOL_PREV_UPDATE_STATS(self)
    if not _s8bool_enabled(self) or self.current_roi is None:
        return
    pipeline = getattr(self, 'pipeline_panel', None)
    if pipeline is None:
        return
    ch_a = int(getattr(self, 'current_channel', getattr(pipeline, 'current_channel', 0)) or 0)
    ch_b = _s8bool_resolve_compare(pipeline, update_selector=False)
    op = _s8bool_op(self)
    info = _s8bool_info(op)
    overlap_n = _s8bool_overlap_key_count(pipeline, ch_a, int(self.current_roi), ch_b)
    total_n = _s8bool_roi_total_count(pipeline, ch_a, int(self.current_roi))
    exclusive_n = max(0, int(total_n) - int(overlap_n))
    matches = _s8bool_matched_rids(pipeline, ch_a, int(self.current_roi), ch_b)
    extra = [
        '',
        f"Boolean operation: {info['name']} ({info['formula']})",
        f'Channels: active ch{ch_a} vs compare ch{ch_b}',
        f'ROI voxels: total {total_n} | shared {overlap_n} | active-only {exclusive_n}',
        f'Matched comparison ROIs: {len(matches)}' + (f" ({', '.join(str(v) for v in matches[:8])}{'…' if len(matches) > 8 else ''})" if matches else ''),
    ]
    try:
        current = str(self.stats.toPlainText())
        self.stats.setPlainText(current + '\n'.join(extra))
    except Exception:
        pass
ROIPanel.update_stats = _s8bool_update_stats


# ----- Boolean compact export -----
def _s8bool_keep_ids(panel, ch_a, ch_b, op):
    sites = _s8bool_get_sites(panel, ch_a)
    out = []
    for rid in sites.keys():
        rid_i = int(rid)
        if _s8bool_roi_is_visible(panel, int(ch_a), rid_i, int(ch_b), op):
            out.append(rid_i)
    return sorted(out)


def _s8bool_filter_ontology(ontology, keep_ids):
    ontology = dict(ontology or {})
    keep = {int(v) for v in keep_ids}
    for key in ('primary_class_by_roi', 'membership_by_roi'):
        src = ontology.get(key, {}) or {}
        ontology[key] = {int(rid): val for rid, val in src.items() if int(rid) in keep}
    counts = {}
    for _rid, name in (ontology.get('primary_class_by_roi', {}) or {}).items():
        counts[str(name)] = counts.get(str(name), 0) + 1
    ontology['summary_counts'] = counts
    try:
        membership = ontology.get('membership_by_roi', {}) or {}
        for cls in ontology.get('classes', []) or []:
            name = str(cls.get('name', ''))
            cls['count'] = int(sum(1 for names in membership.values() if name in (names or [])))
    except Exception:
        pass
    return ontology


def _s8bool_filter_bundle(panel, combined, keep_ids):
    keep = {int(v) for v in keep_ids}
    rois_all = dict(combined.get('rois', {}) or {})
    rois = {int(rid): arr for rid, arr in rois_all.items() if int(rid) in keep}
    combined['rois'] = rois
    site_to_rois = {}
    for rid, arr in rois.items():
        try:
            sid = int(arr[13].get('site_label', 0))
        except Exception:
            sid = 0
        site_to_rois.setdefault(sid, []).append(int(rid))
    combined['hierarchy'] = {'site_to_rois': site_to_rois, 'n_sites': len(site_to_rois)}
    try:
        combined['coordination'] = _s8_filter_coordination_for_rois(combined.get('coordination', {}) or {}, rois)
    except Exception:
        coord = dict(combined.get('coordination', {}) or {})
        if isinstance(coord.get('band_mean'), dict):
            coord['band_mean'] = {int(rid): val for rid, val in coord['band_mean'].items() if int(rid) in keep}
        combined['coordination'] = coord
    meta = combined.setdefault('metadata', {})
    T = int((meta.get('shape_TZYX', (0,0,0,0)) or (0,0,0,0))[0] or 0)
    try:
        combined['propagation'] = estimate_propagation_velocity(rois, T)
    except Exception:
        combined['propagation'] = {}
    combined['ontology'] = _s8bool_filter_ontology(combined.get('ontology', {}) or {}, keep)
    try:
        combined['fingerprint'] = _compute_sample_fingerprint(
            rois,
            ontology=combined.get('ontology', {}),
            coordination=combined.get('coordination', {}),
            propagation=combined.get('propagation', {}),
            T=T,
        )
    except Exception:
        pass
    disp = combined.get('displacements', {}) or {}
    for key in ('centroid_start_end_2d', 'centroid_start_end_3d'):
        if isinstance(disp.get(key), dict):
            disp[key] = {int(rid): val for rid, val in disp[key].items() if int(rid) in keep}
    combined['displacements'] = disp
    meta['n_rois_exported'] = int(len(rois))
    return combined


def _s8bool_comparison_keep_ids(panel, ch_a, ch_b, op):
    sites_b = _s8bool_get_sites(panel, ch_b)
    if op == 'OR':
        return sorted(int(k) for k in sites_b.keys())
    if op == 'AND':
        return sorted(int(k) for k in sites_b.keys() if _s8bool_has_overlap(panel, ch_b, int(k), ch_a))
    if op == 'XOR':
        return sorted(int(k) for k in sites_b.keys() if _s8bool_has_exclusive_voxels(panel, ch_b, int(k), ch_a))
    return []


def _s8bool_compact_comparison_rois(panel, ch_b, keep_ids):
    st_b = panel._get_channel_state(int(ch_b))
    sites_b = st_b.get('sites', {}) or {}
    subset = {int(rid): sites_b[int(rid)] for rid in keep_ids if int(rid) in sites_b}
    try:
        return _s8_compact_rois_for_storage(panel, int(ch_b), st_b, subset)
    except Exception:
        return subset


def _s8bool_build_export_bundle(panel, ch_a, ch_b, op):
    combined, _old_suffix = _s8_build_compact_export_bundle_hard(panel, int(ch_a), intersect=False)
    active_keep = _s8bool_keep_ids(panel, int(ch_a), int(ch_b), op)
    combined = _s8bool_filter_bundle(panel, combined, active_keep)
    compare_keep = _s8bool_comparison_keep_ids(panel, int(ch_a), int(ch_b), op)
    comparison_rois = _s8bool_compact_comparison_rois(panel, int(ch_b), compare_keep)
    info = _s8bool_info(op)
    meta = combined.setdefault('metadata', {})
    meta.update({
        'export_scope': 'channel_boolean',
        'export_mode': f'boolean_{str(op).lower()}',
        'export_label': f"Channel Boolean {info['name']}: ch{int(ch_a)} vs ch{int(ch_b)}",
        'export_filter_desc': f"{info['name']} ({info['formula']}): {len(active_keep)} active-channel ROI(s); {len(compare_keep)} comparison-channel ROI(s)",
        'channel_boolean_enabled': True,
        'channel_boolean_operation': str(op),
        'channel_boolean_formula': info['formula'],
        'channel_boolean_description': info['description'],
        'channel_boolean_active_channel': int(ch_a),
        'channel_boolean_comparison_channel': int(ch_b),
        'intersect_mode': bool(op == 'AND'),
        'n_rois_exported': int(len(active_keep)),
        'n_comparison_rois_referenced': int(len(compare_keep)),
    })
    combined['channel_boolean'] = {
        'operation': str(op),
        'name': info['name'],
        'formula': info['formula'],
        'description': info['description'],
        'active_channel': int(ch_a),
        'comparison_channel': int(ch_b),
        'active_roi_ids': [int(v) for v in active_keep],
        'comparison_roi_ids': [int(v) for v in compare_keep],
        'comparison_rois': comparison_rois,
        'result_coordinate_storage': 'reconstruct_from_ROI_sidecar_refs',
        'reconstruction_note': 'Apply the recorded boolean formula to the exact T,Z,Y,X coordinate sidecar references in active rois and channel_boolean.comparison_rois. Result coordinate clouds are not duplicated inside the pickle.',
        'selected_comparison_only': True,
    }
    if op == 'AND':
        try:
            pairs = _s8_build_intersect_report_pairs_hard(panel, int(ch_a), combined.get('rois', {}))
            pairs = [p for p in pairs if int(p.get('channel_b', -1)) == int(ch_b)]
        except Exception:
            pairs = []
        combined['intersect_report_pairs'] = pairs
        meta['intersect_pair_count'] = int(len(pairs))
        meta['intersect_matched_channels'] = [int(ch_b)] if pairs else []
        meta['intersect_full_coordinate_export'] = False
        meta['intersect_export_coords_omitted'] = True
    suffix = f"_{info['suffix']}_ch{int(ch_a)}_ch{int(ch_b)}"
    try:
        combined = _s8_deep_sanitize_for_pickle(combined)
    except Exception:
        pass
    return combined, suffix


def _s8bool_plot_report_summary(pdf, combined):
    meta = (combined or {}).get('metadata', {}) or {}
    payload = (combined or {}).get('channel_boolean', {}) or {}
    fig = plt.figure(figsize=(10, 6), dpi=160)
    fig.suptitle('Channel Boolean Operation', fontsize=14)
    ax = fig.add_subplot(1, 1, 1)
    ax.axis('off')
    lines = [
        f"Operation: {payload.get('name', meta.get('channel_boolean_operation', ''))}",
        f"Formula: {payload.get('formula', meta.get('channel_boolean_formula', ''))}",
        f"Active channel: {payload.get('active_channel', meta.get('channel_boolean_active_channel', ''))}",
        f"Comparison channel: {payload.get('comparison_channel', meta.get('channel_boolean_comparison_channel', ''))}",
        f"Active-channel ROIs retained: {len(payload.get('active_roi_ids', []) or [])}",
        f"Comparison-channel ROIs referenced: {len(payload.get('comparison_roi_ids', []) or [])}",
        '',
        str(payload.get('description', meta.get('channel_boolean_description', ''))),
        '',
        str(payload.get('reconstruction_note', '')),
    ]
    ax.text(0.03, 0.95, '\n'.join(lines), va='top', ha='left', family='monospace', wrap=True)
    pdf.savefig(fig)
    plt.close(fig)


_S8BOOL_PREV_WRITE_REPORT = write_report_pdf_progress
def write_report_pdf_progress(out_base: str, combined: dict, parent=None):
    meta0 = (combined or {}).get('metadata', {}) or {}
    if not bool(meta0.get('channel_boolean_enabled', False)):
        return _S8BOOL_PREV_WRITE_REPORT(out_base, combined, parent=parent)
    combined = _s8_units_enrich_combined(combined)
    rois = combined.get('rois', {})
    meta = combined.get('metadata', {})
    coord = combined.get('coordination', {})
    vel = combined.get('propagation', {})
    T = int(meta.get('shape_TZYX', (0, 0, 0, 0))[0] or 0)
    out_pdf = out_base + '_hypervolume_report.pdf'
    with PdfPages(out_pdf) as pdf:
        metrics = _collect_metrics(rois)
        _s8_plot_overview_units(pdf, meta, metrics)
        _s8bool_plot_report_summary(pdf, combined)
        _s8_plot_fingerprint_summary_units(pdf, combined)
        _plot_ontology_summary(pdf, combined)
        _s8_plot_strips_units(pdf, metrics, meta)
        _s8_plot_multi_series_units(pdf, rois, T, meta=meta)
        _s8v3k_plot_intensity_series_pdf(pdf, rois, T, meta=meta)
        _s8_plot_intersect_channel_series_units(pdf, combined)
        _s8_plot_centroid_displacements_pdf_units(pdf, rois, meta)
        _s8_plot_centroid_displacements3d_pdf_units(pdf, rois, meta)
        _s8_plot_coherence_pdf_units(pdf, coord, T, meta=meta)
        _s8_plot_velocity_pdf_units(pdf, vel, meta=meta)
    print(f'Wrote report: {out_pdf}')


_S8BOOL_PREV_DO_EXPORT = PipelinePanel.do_export
def _s8bool_do_export(self, *args, **kwargs):
    if not _s8bool_enabled(self):
        return _S8BOOL_PREV_DO_EXPORT(self, *args, **kwargs)
    ch_a = int(getattr(self, 'current_channel', 0) or 0)
    ch_b = _s8bool_resolve_compare(self, update_selector=True)
    if ch_b is None:
        QtWidgets.QMessageBox.information(self, 'Export', 'Choose an analyzed comparison channel before exporting a Boolean result.')
        return
    op = _s8bool_op(self)
    base_dir = QtWidgets.QFileDialog.getExistingDirectory(self, 'Select output directory')
    if not base_dir:
        return
    _s8_param_path = _s8_write_input_parameters_text(self, base_dir)
    info = _s8bool_info(op)
    pprog = StepProgress('Exporting channel Boolean result', maximum=2, parent=self)
    pprog.set_text(f"Building {info['name']} compact pickle...")
    combined, suffix = _s8bool_build_export_bundle(self, ch_a, int(ch_b), op)
    input_stem = _s8_safe_input_stem_for_manifest(self)
    base = os.path.join(base_dir, f'{input_stem}{suffix}_Output')
    pickle_path = base + '.p'
    try:
        combined.setdefault('metadata', {})['estimated_pickle_payload_bytes_before_write'] = _s8_estimate_pickle_payload_bytes(combined)
    except Exception:
        pass
    with open(pickle_path, 'wb') as f:
        pkl.dump(combined, f, protocol=pkl.HIGHEST_PROTOCOL)
    pprog.step(1)
    pprog.set_text('Writing Boolean-operation PDF report...')
    write_report_pdf_progress(base, combined, parent=self)
    report_generated = base + '_hypervolume_report.pdf'
    report_path = base + '.pdf'
    if report_generated != report_path and os.path.exists(report_generated):
        os.replace(report_generated, report_path)
    pprog.step(2)
    pprog.close()
    QtWidgets.QMessageBox.information(
        self,
        'Export',
        f"Wrote:\n{pickle_path}\n{report_path}"
        + (f"\n{_s8_param_path}" if _s8_param_path else "")
        + f"\n\nOperation: {info['name']} ({info['formula']})"
    )
PipelinePanel.do_export = _s8bool_do_export

# --- END PATCH: V3Q CHANNEL BOOLEAN OPERATIONS ---



# --- BEGIN PATCH: V3R FINGERPRINT VARIABILITY + LDA ---
# Fingerprint-workspace-only changes:
#   1) Disable the distance-between-fingerprints heatmap/UI.
#   2) Add condition-wise 1-SD covariance clouds to the X/Y sample fingerprint plot.
#   3) Replace the distance plot with regularized LDA of enabled sample fingerprints,
#      grouped by experimental Condition, including an interpretable feature-weight ranking.
# Meta fingerprints are displayed in the X/Y plot but are excluded from SD-cloud estimation and LDA training.

_S8V3R_PREV_MF_INIT = MultiFingerprintDialog.__init__
_S8V3R_PREV_MF_REFRESH_SCATTER = MultiFingerprintDialog.refresh_scatter
_S8V3R_PREV_MF_REFRESH_SUMMARY = MultiFingerprintDialog.refresh_summary


def _s8v3r_mf_init(self, parent=None):
    _S8V3R_PREV_MF_INIT(self, parent)
    self.last_lda_result = {}

    # Distance view is intentionally disabled for now.
    for name in ('cmb_distance', 'chk_annotate', 'chk_cluster'):
        w = getattr(self, name, None)
        if w is not None:
            try:
                w.setVisible(False)
                w.setEnabled(False)
            except Exception:
                pass
    try:
        for lbl in self.findChildren(QtWidgets.QLabel):
            if str(lbl.text()).strip().lower() == 'distance:':
                lbl.setVisible(False)
    except Exception:
        pass

    # Variability/LDA controls.  Insert directly below the X/Y feature row.
    analysis_row = QtWidgets.QHBoxLayout()
    analysis_row.addWidget(QtWidgets.QLabel('Variability:'))
    self.chk_sd_cloud = QtWidgets.QCheckBox('Show condition SD cloud')
    self.chk_sd_cloud.setChecked(True)
    analysis_row.addWidget(self.chk_sd_cloud)
    analysis_row.addWidget(QtWidgets.QLabel('SD scale:'))
    self.spin_sd_cloud = QtWidgets.QDoubleSpinBox()
    self.spin_sd_cloud.setRange(0.25, 4.0)
    self.spin_sd_cloud.setSingleStep(0.25)
    self.spin_sd_cloud.setDecimals(2)
    self.spin_sd_cloud.setValue(1.0)
    self.spin_sd_cloud.setSuffix('×')
    self.spin_sd_cloud.setMaximumWidth(85)
    analysis_row.addWidget(self.spin_sd_cloud)
    analysis_row.addSpacing(14)
    self.lbl_lda_mode = QtWidgets.QLabel('LDA: enabled samples grouped by Condition')
    analysis_row.addWidget(self.lbl_lda_mode)
    analysis_row.addStretch(1)
    try:
        self.layout().insertLayout(2, analysis_row)
    except Exception:
        self.layout().addLayout(analysis_row)

    self.chk_sd_cloud.toggled.connect(self.refresh_scatter)
    self.spin_sd_cloud.valueChanged.connect(self.refresh_scatter)

    # Reuse the former distance-plot canvas for LDA projection + feature weights.
    try:
        self.fig_heat.clear()
        self.ax_lda_space = self.fig_heat.add_subplot(1, 2, 1)
        self.ax_lda_weights = self.fig_heat.add_subplot(1, 2, 2)
        self.ax_heat = self.ax_lda_space  # compatibility with any legacy references
        self.canvas_heat.draw_idle()
    except Exception:
        self.ax_lda_space = getattr(self, 'ax_heat', None)
        self.ax_lda_weights = None


MultiFingerprintDialog.__init__ = _s8v3r_mf_init


def _s8v3r_condition_sample_xy(self, xkey, ykey):
    groups = {}
    for rec in self._enabled_records():
        if str(rec.get('kind', 'sample')).lower() == 'meta':
            continue
        cond = str(rec.get('condition', '')).strip()
        if not cond or cond == '(unlabeled)' or cond.upper().startswith('META-'):
            continue
        try:
            xv = float((rec.get('fingerprint', {}) or {}).get(xkey, np.nan))
            yv = float((rec.get('fingerprint', {}) or {}).get(ykey, np.nan))
        except Exception:
            continue
        if np.isfinite(xv) and np.isfinite(yv):
            groups.setdefault(cond, []).append((xv, yv))
    return groups


def _s8v3r_refresh_scatter(self):
    # Preserve the existing sample/meta plotting behavior, then add condition variability.
    _S8V3R_PREV_MF_REFRESH_SCATTER(self)
    if not bool(getattr(getattr(self, 'chk_sd_cloud', None), 'isChecked', lambda: False)()):
        return
    if str(getattr(self, 'cmb_color', None).currentText() if getattr(self, 'cmb_color', None) is not None else '').lower() != 'condition':
        return
    xkey = self.cmb_x.currentText()
    ykey = self.cmb_y.currentText()
    if not xkey or not ykey:
        return

    groups = _s8v3r_condition_sample_xy(self, xkey, ykey)
    if not groups:
        return
    try:
        from matplotlib.patches import Ellipse
    except Exception:
        return

    # Match the existing tab20 condition order used by the scatter plot.
    enabled = self._enabled_records()
    display_order = []
    for rec in enabled:
        grp = self._group_value(rec)
        if grp not in display_order:
            display_order.append(grp)
    palette = plt.get_cmap('tab20')
    color_map = {grp: palette(i % palette.N) for i, grp in enumerate(display_order)}
    scale = float(self.spin_sd_cloud.value()) if getattr(self, 'spin_sd_cloud', None) is not None else 1.0

    for cond, pts in groups.items():
        if len(pts) < 2:
            continue
        P = np.asarray(pts, dtype=float)
        center = np.mean(P, axis=0)
        cov = np.cov(P.T, ddof=1)
        if np.ndim(cov) != 2 or np.shape(cov) != (2, 2) or not np.all(np.isfinite(cov)):
            continue
        try:
            vals, vecs = np.linalg.eigh(cov)
        except Exception:
            continue
        vals = np.maximum(np.asarray(vals, dtype=float), 0.0)
        order = np.argsort(vals)[::-1]
        vals = vals[order]
        vecs = vecs[:, order]
        if not np.any(vals > 0):
            continue
        theta = float(np.degrees(np.arctan2(vecs[1, 0], vecs[0, 0])))
        width = float(2.0 * scale * np.sqrt(vals[0]))
        height = float(2.0 * scale * np.sqrt(vals[1]))
        col = color_map.get(cond, (0.5, 0.5, 0.5, 1.0))
        ell = Ellipse(
            xy=(float(center[0]), float(center[1])),
            width=width,
            height=height,
            angle=theta,
            facecolor=col,
            edgecolor=col,
            alpha=0.16,
            linewidth=1.6,
            zorder=1,
        )
        self.ax_scatter.add_patch(ell)
        self.ax_scatter.scatter([center[0]], [center[1]], marker='+', s=85, linewidths=1.6, color=[col], zorder=4)

    self.ax_scatter.set_title(f'Sample fingerprints — condition covariance cloud ({scale:g} SD)')
    self.canvas_scatter.draw_idle()


MultiFingerprintDialog.refresh_scatter = _s8v3r_refresh_scatter


def _s8v3r_lda_records(self):
    out = []
    for rec in self._enabled_records():
        if str(rec.get('kind', 'sample')).lower() == 'meta':
            continue
        cond = str(rec.get('condition', '')).strip()
        if not cond or cond == '(unlabeled)' or cond.upper().startswith('META-'):
            continue
        out.append(rec)
    return out


def _s8v3r_compute_lda(self):
    records = _s8v3r_lda_records(self)
    if len(records) < 3:
        return {'ok': False, 'message': 'LDA needs at least 3 enabled, condition-labeled sample fingerprints.'}

    classes = []
    for rec in records:
        cond = str(rec.get('condition', '')).strip()
        if cond not in classes:
            classes.append(cond)
    if len(classes) < 2:
        return {'ok': False, 'message': 'LDA needs at least 2 experimental conditions.'}

    # Use numeric fingerprint features present in actual sample records only.
    keys = set()
    for rec in records:
        keys.update(_fingerprint_numeric_keys(rec.get('fingerprint', {}) or {}))
    keys = sorted(keys)
    if not keys:
        return {'ok': False, 'message': 'No numeric fingerprint features are available for LDA.'}

    M = []
    y = []
    labels = []
    for rec in records:
        fp = rec.get('fingerprint', {}) or {}
        row = []
        for key in keys:
            try:
                if key in fp:
                    row.append(float(fp.get(key, np.nan)))
                elif str(key).startswith('frac_'):
                    # An absent ontology fraction means that class contributed zero.
                    row.append(0.0)
                else:
                    row.append(np.nan)
            except Exception:
                row.append(np.nan)
        M.append(row)
        y.append(str(rec.get('condition', '')).strip())
        labels.append(str(rec.get('label', 'sample')))
    M = np.asarray(M, dtype=float)
    y = np.asarray(y, dtype=object)

    # Remove unusable features, mean-impute remaining sporadic missing values,
    # and standardize so LDA weights are comparable across physical units.
    keep_cols = []
    for j in range(M.shape[1]):
        finite = np.isfinite(M[:, j])
        if int(finite.sum()) < 2:
            continue
        vals = M[finite, j]
        if float(np.nanstd(vals)) < 1e-12:
            continue
        keep_cols.append(j)
    if not keep_cols:
        return {'ok': False, 'message': 'All available fingerprint features are constant or insufficient for LDA.'}
    M = M[:, keep_cols]
    keys = [keys[j] for j in keep_cols]

    for j in range(M.shape[1]):
        finite = np.isfinite(M[:, j])
        mean_j = float(np.mean(M[finite, j])) if np.any(finite) else 0.0
        M[~finite, j] = mean_j
    mu = np.mean(M, axis=0)
    sd = np.std(M, axis=0, ddof=0)
    sd[sd < 1e-12] = 1.0
    X = (M - mu) / sd

    n, p = X.shape
    c = len(classes)
    overall = np.mean(X, axis=0)
    Sw = np.zeros((p, p), dtype=float)
    Sb = np.zeros((p, p), dtype=float)
    class_counts = {}
    class_means = {}
    for cls in classes:
        idx = np.where(y == cls)[0]
        Xc = X[idx]
        class_counts[cls] = int(len(idx))
        mc = np.mean(Xc, axis=0)
        class_means[cls] = mc
        centered = Xc - mc
        Sw += centered.T @ centered
        dm = (mc - overall).reshape(-1, 1)
        Sb += float(len(idx)) * (dm @ dm.T)

    residual_dof = max(1, n - c)
    Sw /= float(residual_dof)
    # Adaptive diagonal shrinkage keeps LDA defined when fingerprints contain
    # more correlated features than biological replicates.
    alpha = 0.10
    if p > residual_dof:
        alpha = min(0.80, max(0.10, float(p - residual_dof) / float(max(1, p))))
    diag = np.diag(np.diag(Sw))
    if not np.any(np.diag(diag) > 1e-12):
        diag = np.eye(p, dtype=float)
    Sw_reg = (1.0 - alpha) * Sw + alpha * diag + (1e-6 * np.eye(p, dtype=float))

    try:
        from scipy.linalg import eigh
        evals, evecs = eigh(Sb, Sw_reg, check_finite=False)
    except Exception as e:
        return {'ok': False, 'message': f'LDA could not solve the discriminant system: {e}'}
    order = np.argsort(evals)[::-1]
    evals = np.asarray(evals[order], dtype=float)
    evecs = np.asarray(evecs[:, order], dtype=float)
    positive = np.where(evals > 1e-10)[0]
    ncomp = min(c - 1, p, len(positive))
    if ncomp < 1:
        return {'ok': False, 'message': 'No positive discriminant axis was found; conditions are not separable in the available features.'}
    evals = evals[:ncomp]
    W = evecs[:, :ncomp]

    # Orient LD1 for binary experiments so positive direction points from the
    # first listed condition toward the second; absolute feature importance is
    # used for condition-agnostic ranking.
    scores = X @ W
    if c == 2 and ncomp >= 1:
        m0 = float(np.mean(scores[y == classes[0], 0]))
        m1 = float(np.mean(scores[y == classes[1], 0]))
        if m1 < m0:
            W[:, 0] *= -1.0
            scores[:, 0] *= -1.0

    power = np.maximum(evals, 0.0)
    if float(np.sum(power)) > 0:
        explained = power / float(np.sum(power))
    else:
        explained = np.ones_like(power) / float(len(power))
    importance = np.sqrt(np.sum((W ** 2) * power[None, :], axis=1))
    if np.max(importance) > 0:
        importance = importance / np.max(importance)
    rank = np.argsort(importance)[::-1]

    warning = ''
    min_rep = min(class_counts.values()) if class_counts else 0
    if min_rep < 2:
        warning = 'At least one condition has n=1; LDA is exploratory.'
    elif p >= residual_dof:
        warning = f'High feature/replicate ratio; diagonal shrinkage={alpha:.2f} was applied.'

    return {
        'ok': True,
        'records': records,
        'labels': labels,
        'conditions': y,
        'classes': classes,
        'class_counts': class_counts,
        'feature_keys': keys,
        'scores': scores,
        'weights': W,
        'eigenvalues': evals,
        'explained': explained,
        'importance': importance,
        'rank': rank,
        'shrinkage': float(alpha),
        'warning': warning,
    }


def _s8v3r_refresh_lda(self):
    try:
        self.fig_heat.clear()
        self.ax_lda_space = self.fig_heat.add_subplot(1, 2, 1)
        self.ax_lda_weights = self.fig_heat.add_subplot(1, 2, 2)
        self.ax_heat = self.ax_lda_space
    except Exception:
        return

    result = _s8v3r_compute_lda(self)
    self.last_lda_result = result
    if not result.get('ok', False):
        self.ax_lda_space.text(0.5, 0.5, result.get('message', 'LDA unavailable'), ha='center', va='center', wrap=True)
        self.ax_lda_space.axis('off')
        self.ax_lda_weights.text(0.5, 0.5, 'Feature weights appear here when LDA is available.', ha='center', va='center', wrap=True)
        self.ax_lda_weights.axis('off')
        self.canvas_heat.draw_idle()
        try:
            self.refresh_summary()
        except Exception:
            pass
        return

    scores = np.asarray(result['scores'], dtype=float)
    y = np.asarray(result['conditions'], dtype=object)
    classes = list(result['classes'])
    labels = list(result['labels'])
    explained = np.asarray(result['explained'], dtype=float)
    palette = plt.get_cmap('tab20')

    if scores.shape[1] >= 2:
        for i, cls in enumerate(classes):
            idx = np.where(y == cls)[0]
            self.ax_lda_space.scatter(scores[idx, 0], scores[idx, 1], s=45, alpha=0.85, label=cls, color=palette(i % palette.N))
            for j in idx:
                self.ax_lda_space.text(scores[j, 0], scores[j, 1], labels[j], fontsize=7, ha='left', va='bottom')
        self.ax_lda_space.set_xlabel(f'LD1 ({100.0 * explained[0]:.1f}% discrim. power)')
        self.ax_lda_space.set_ylabel(f'LD2 ({100.0 * explained[1]:.1f}% discrim. power)')
    else:
        for i, cls in enumerate(classes):
            idx = np.where(y == cls)[0]
            yy = np.full(len(idx), float(i))
            self.ax_lda_space.scatter(scores[idx, 0], yy, s=45, alpha=0.85, label=cls, color=palette(i % palette.N))
            for loc, j in enumerate(idx):
                self.ax_lda_space.text(scores[j, 0], yy[loc], labels[j], fontsize=7, ha='left', va='bottom')
        self.ax_lda_space.set_yticks(np.arange(len(classes), dtype=float))
        self.ax_lda_space.set_yticklabels(classes)
        self.ax_lda_space.set_xlabel('LD1 (100% discriminant power)')
        self.ax_lda_space.set_ylabel('Condition')
    self.ax_lda_space.set_title('Linear discriminant projection')
    if len(classes) <= 12 and scores.shape[1] >= 2:
        self.ax_lda_space.legend(loc='best', fontsize=8, framealpha=0.7)

    rank = np.asarray(result['rank'], dtype=int)
    keys = list(result['feature_keys'])
    importance = np.asarray(result['importance'], dtype=float)
    top = rank[:min(12, len(rank))]
    top = top[::-1]
    names = [keys[i] for i in top]
    vals = [float(importance[i]) for i in top]
    self.ax_lda_weights.barh(np.arange(len(top)), vals)
    self.ax_lda_weights.set_yticks(np.arange(len(top)))
    self.ax_lda_weights.set_yticklabels(names, fontsize=8)
    self.ax_lda_weights.set_xlim(0, max(1.0, max(vals) * 1.05 if vals else 1.0))
    self.ax_lda_weights.set_xlabel('relative discriminant weight')
    self.ax_lda_weights.set_title('Features maximizing condition separation')
    self.canvas_heat.draw_idle()
    try:
        self.refresh_summary()
    except Exception:
        pass


# Keep the legacy refresh_views pipeline intact: its final refresh_heatmap() call
# is redirected to LDA rather than computing pairwise fingerprint distances.
MultiFingerprintDialog.refresh_heatmap = _s8v3r_refresh_lda


def _s8v3r_refresh_summary(self):
    _S8V3R_PREV_MF_REFRESH_SUMMARY(self)
    result = getattr(self, 'last_lda_result', {}) or {}
    try:
        base = str(self.summary.toPlainText())
    except Exception:
        base = ''
    lines = []
    if result.get('ok', False):
        counts = result.get('class_counts', {}) or {}
        lines.append('')
        lines.append('LDA condition separation:')
        lines.append('  ' + ', '.join(f'{k}: n={v}' for k, v in counts.items()))
        rank = np.asarray(result.get('rank', []), dtype=int)
        keys = list(result.get('feature_keys', []))
        importance = np.asarray(result.get('importance', []), dtype=float)
        lines.append('  top discriminating fingerprint features:')
        for idx in rank[:min(8, len(rank))]:
            lines.append(f'    {keys[int(idx)]}: {float(importance[int(idx)]):.3f}')
        warning = str(result.get('warning', '') or '').strip()
        if warning:
            lines.append(f'  note: {warning}')
    elif result:
        lines.append('')
        lines.append('LDA: ' + str(result.get('message', 'unavailable')))
    self.summary.setPlainText(base + ('\n'.join(lines) if lines else ''))


MultiFingerprintDialog.refresh_summary = _s8v3r_refresh_summary

# --- END PATCH: V3R FINGERPRINT VARIABILITY + LDA ---

# --- BEGIN PATCH: V3S META-FINGERPRINT COVARIANCE RETENTION ---
# Meta-fingerprint-only extension:
#   1) Retain a full feature-by-feature sample covariance matrix in each meta profile.
#   2) Persist covariance, feature order, SD, SEM, membership, and condition when saving.
#   3) Reload saved meta profiles as meta records (never as biological samples / LDA inputs).
#   4) Reconstruct the saved covariance cloud for any selected X/Y fingerprint features.

_S8V3S_PREV_COMPUTE_META_PROFILE = _compute_meta_profile
_S8V3S_PREV_LOAD_FINGERPRINT_RECORD = _load_fingerprint_record
_S8V3S_PREV_MF_LOAD_FILES = MultiFingerprintDialog.load_files
_S8V3S_PREV_MF_SAVE_META = MultiFingerprintDialog.save_meta_profile
_S8V3S_PREV_MF_REFRESH_SCATTER = MultiFingerprintDialog.refresh_scatter


def _s8v3s_compute_meta_profile(records, name='Meta fingerprint', aggregate='mean'):
    profile = _S8V3S_PREV_COMPUTE_META_PROFILE(records, name=name, aggregate=aggregate)
    if not profile:
        return profile

    records = list(records or [])
    keys = list((profile.get('fingerprint', {}) or {}).keys())
    if not keys:
        profile['covariance_features'] = []
        profile['feature_covariance'] = np.zeros((0, 0), dtype=float)
        profile['covariance_ddof'] = 1
        return profile

    M = []
    for rec in records:
        fp = rec.get('fingerprint', {}) or {}
        row = []
        for key in keys:
            try:
                row.append(float(fp.get(key, np.nan)))
            except Exception:
                row.append(np.nan)
        M.append(row)
    M = np.asarray(M, dtype=float)

    if M.ndim != 2 or M.shape[1] != len(keys) or M.shape[0] == 0:
        cov = np.zeros((len(keys), len(keys)), dtype=float)
    else:
        # Match the existing meta-profile missing-value treatment: mean-impute
        # sporadic missing values before calculating across-sample variability.
        for j in range(M.shape[1]):
            finite = np.isfinite(M[:, j])
            fill = float(np.mean(M[finite, j])) if np.any(finite) else 0.0
            M[~finite, j] = fill
        if M.shape[0] >= 2:
            cov = np.asarray(np.cov(M, rowvar=False, ddof=1), dtype=float)
            if cov.ndim == 0:
                cov = cov.reshape(1, 1)
            elif cov.ndim == 1:
                cov = np.diag(cov)
        else:
            cov = np.zeros((len(keys), len(keys)), dtype=float)
        if cov.shape != (len(keys), len(keys)) or not np.all(np.isfinite(cov)):
            cov = np.zeros((len(keys), len(keys)), dtype=float)

    profile['covariance_features'] = list(keys)
    profile['feature_covariance'] = cov
    profile['covariance_ddof'] = 1
    return profile


_compute_meta_profile = _s8v3s_compute_meta_profile


def _s8v3s_load_fingerprint_record(path: str):
    # Saved meta profiles are self-contained statistical objects and should
    # reload as meta records, not ordinary samples.
    try:
        with open(path, 'rb') as f:
            data = pkl.load(f)
        if isinstance(data, dict) and bool(data.get('meta_fingerprint', False)):
            profile = {
                'name': str(data.get('name', Path(path).stem)),
                'aggregate': str(data.get('aggregate', 'mean')),
                'n_members': int(data.get('n_members', 0) or 0),
                'member_labels': list(data.get('member_labels', []) or []),
                'member_conditions': list(data.get('member_conditions', []) or []),
                'fingerprint': dict(data.get('fingerprint', {}) or {}),
                'feature_std': dict(data.get('feature_std', {}) or {}),
                'feature_sem': dict(data.get('feature_sem', {}) or {}),
                'top_classes': list(data.get('top_classes', []) or []),
                'source_paths': list(data.get('source_paths', []) or []),
                'covariance_features': list(data.get('covariance_features', []) or []),
                'feature_covariance': np.asarray(data.get('feature_covariance', np.zeros((0, 0))), dtype=float),
                'covariance_ddof': int(data.get('covariance_ddof', 1) or 1),
            }
            condition = str(data.get('condition', '') or 'META')
            return {
                'path': str(path),
                'label': profile['name'],
                'condition': condition,
                'fingerprint': dict(profile.get('fingerprint', {}) or {}),
                'metadata': {
                    'meta_profile': True,
                    'aggregate': profile.get('aggregate', 'mean'),
                    'n_members': profile.get('n_members', 0),
                },
                'ontology': {},
                'enabled': True,
                'kind': 'meta',
                'meta_profile': profile,
            }
    except Exception:
        pass
    return _S8V3S_PREV_LOAD_FINGERPRINT_RECORD(path)


_load_fingerprint_record = _s8v3s_load_fingerprint_record


def _s8v3s_load_files(self):
    paths, _ = QtWidgets.QFileDialog.getOpenFileNames(
        self,
        'Select exported combined pickles or fingerprint dictionaries',
        '',
        'Pickle (*.p *.pkl);;All files (*)'
    )
    if not paths:
        return
    loaded = 0
    failed = []
    for path in paths:
        try:
            rec = _load_fingerprint_record(path)
            rec['enabled'] = True
            # Respect saved meta-fingerprint identity; ordinary exported sample
            # fingerprints continue to default to sample exactly as before.
            rec['kind'] = str(rec.get('kind', 'sample') or 'sample')
            self.records.append(rec)
            if rec['kind'].lower() == 'meta':
                self.last_meta_profile = dict(rec.get('meta_profile', {}) or {})
            loaded += 1
        except Exception as e:
            failed.append(f'{Path(path).name}: {e}')
    self.refresh_views()
    if failed:
        QtWidgets.QMessageBox.warning(
            self,
            'Fingerprint workspace',
            f'Loaded {loaded} file(s).\n\nFailed:\n' + '\n'.join(failed[:12])
        )


MultiFingerprintDialog.load_files = _s8v3s_load_files


def _s8v3s_save_meta_profile(self):
    selected = self._selected_records()
    profile = None
    selected_condition = 'META'
    if selected:
        rec = selected[0]
        if str(rec.get('kind', 'sample')).lower() == 'meta':
            selected_condition = str(rec.get('condition', '') or 'META')
            profile = dict(rec.get('meta_profile', {}) or {})
            if not profile and rec.get('fingerprint'):
                profile = {
                    'name': rec.get('label', 'Meta fingerprint'),
                    'aggregate': rec.get('metadata', {}).get('aggregate', 'mean'),
                    'n_members': rec.get('metadata', {}).get('n_members', 0),
                    'fingerprint': dict(rec.get('fingerprint', {}) or {}),
                }
    if not profile:
        profile = dict(self.last_meta_profile or {})
    if not profile:
        QtWidgets.QMessageBox.information(self, 'Meta fingerprint', 'Create or select a meta fingerprint first.')
        return

    out_path, _ = QtWidgets.QFileDialog.getSaveFileName(
        self,
        'Save meta fingerprint profile',
        f"{profile.get('name', 'meta_fingerprint').replace(' ', '_')}.pkl",
        'Pickle (*.pkl *.p)'
    )
    if not out_path:
        return

    cov = np.asarray(profile.get('feature_covariance', np.zeros((0, 0))), dtype=float)
    payload = {
        'meta_fingerprint': True,
        'name': profile.get('name', 'Meta fingerprint'),
        'condition': selected_condition,
        'aggregate': profile.get('aggregate', 'mean'),
        'n_members': profile.get('n_members', 0),
        'member_labels': profile.get('member_labels', []),
        'member_conditions': profile.get('member_conditions', []),
        'fingerprint': dict(profile.get('fingerprint', {}) or {}),
        'feature_std': dict(profile.get('feature_std', {}) or {}),
        'feature_sem': dict(profile.get('feature_sem', {}) or {}),
        'covariance_features': list(profile.get('covariance_features', []) or []),
        'feature_covariance': cov,
        'covariance_ddof': int(profile.get('covariance_ddof', 1) or 1),
        'top_classes': list(profile.get('top_classes', []) or []),
        'source_paths': list(profile.get('source_paths', []) or []),
    }
    with open(out_path, 'wb') as f:
        pkl.dump(payload, f, protocol=pkl.HIGHEST_PROTOCOL)
    QtWidgets.QMessageBox.information(self, 'Meta fingerprint', f'Saved meta fingerprint profile:\n{out_path}')


MultiFingerprintDialog.save_meta_profile = _s8v3s_save_meta_profile


def _s8v3s_meta_xy_covariance(rec, xkey, ykey):
    profile = dict(rec.get('meta_profile', {}) or {})
    fp = dict(rec.get('fingerprint', {}) or profile.get('fingerprint', {}) or {})
    try:
        cx = float(fp.get(xkey, np.nan))
        cy = float(fp.get(ykey, np.nan))
    except Exception:
        return None
    if not (np.isfinite(cx) and np.isfinite(cy)):
        return None

    features = list(profile.get('covariance_features', []) or [])
    cov_full = np.asarray(profile.get('feature_covariance', np.zeros((0, 0))), dtype=float)
    if xkey in features and ykey in features and cov_full.shape == (len(features), len(features)):
        ix = features.index(xkey)
        iy = features.index(ykey)
        cov = cov_full[np.ix_([ix, iy], [ix, iy])]
        if cov.shape == (2, 2) and np.all(np.isfinite(cov)):
            return np.asarray([cx, cy], dtype=float), np.asarray(cov, dtype=float), 'covariance'

    # Backward-compatible fallback for older meta profiles: independent SDs
    # reconstruct an axis-aligned cloud, but cannot recover historical tilt.
    stds = dict(profile.get('feature_std', {}) or {})
    try:
        sx = float(stds.get(xkey, np.nan))
        sy = float(stds.get(ykey, np.nan))
    except Exception:
        return None
    if np.isfinite(sx) and np.isfinite(sy):
        cov = np.asarray([[max(0.0, sx * sx), 0.0], [0.0, max(0.0, sy * sy)]], dtype=float)
        return np.asarray([cx, cy], dtype=float), cov, 'sd-only'
    return None


def _s8v3s_refresh_scatter(self):
    # First draw ordinary samples, live condition covariance clouds, and meta points.
    _S8V3S_PREV_MF_REFRESH_SCATTER(self)
    if not bool(getattr(getattr(self, 'chk_sd_cloud', None), 'isChecked', lambda: False)()):
        return

    xkey = self.cmb_x.currentText()
    ykey = self.cmb_y.currentText()
    if not xkey or not ykey:
        return
    try:
        from matplotlib.patches import Ellipse
    except Exception:
        return

    enabled = self._enabled_records()
    display_order = []
    for rec in enabled:
        grp = self._group_value(rec)
        if grp not in display_order:
            display_order.append(grp)
    palette = plt.get_cmap('tab20')
    color_map = {grp: palette(i % palette.N) for i, grp in enumerate(display_order)}
    scale = float(self.spin_sd_cloud.value()) if getattr(self, 'spin_sd_cloud', None) is not None else 1.0

    drew_meta = False
    for rec in enabled:
        if str(rec.get('kind', 'sample')).lower() != 'meta':
            continue
        parsed = _s8v3s_meta_xy_covariance(rec, xkey, ykey)
        if parsed is None:
            continue
        center, cov, source = parsed
        try:
            vals, vecs = np.linalg.eigh(cov)
        except Exception:
            continue
        vals = np.maximum(np.asarray(vals, dtype=float), 0.0)
        order = np.argsort(vals)[::-1]
        vals = vals[order]
        vecs = vecs[:, order]
        if not np.any(vals > 0):
            continue
        theta = float(np.degrees(np.arctan2(vecs[1, 0], vecs[0, 0])))
        width = float(2.0 * scale * np.sqrt(vals[0]))
        height = float(2.0 * scale * np.sqrt(vals[1]))
        grp = self._group_value(rec)
        col = color_map.get(grp, (0.45, 0.45, 0.45, 1.0))
        ell = Ellipse(
            xy=(float(center[0]), float(center[1])),
            width=width,
            height=height,
            angle=theta,
            facecolor=col,
            edgecolor=col,
            alpha=0.09,
            linewidth=2.0,
            linestyle='--',
            zorder=0.8,
        )
        self.ax_scatter.add_patch(ell)
        drew_meta = True

    if drew_meta:
        title = str(self.ax_scatter.get_title() or 'Sample fingerprints')
        if 'saved meta variability' not in title.lower():
            self.ax_scatter.set_title(title + ' + saved meta variability')
        self.canvas_scatter.draw_idle()


MultiFingerprintDialog.refresh_scatter = _s8v3s_refresh_scatter

# --- END PATCH: V3S META-FINGERPRINT COVARIANCE RETENTION ---


# --- BEGIN PATCH: V3T BOOLEAN UNDO + FAST/CORRECT SAVITZKY-GOLAY ---
# Targeted changes only:
#   1) Add an explicit Undo Boolean control that restores the ordinary active-channel view.
#      Boolean operations remain non-destructive; undo disables the applied comparison state.
#   2) Accelerate temporal Savitzky-Golay filtering by parallelizing independent Z/Y stripes,
#      including Z=1 time series, and fuse background subtraction into each stripe.
#   3) Prevent unsigned-integer wraparound from negative Savitzky-Golay overshoot by filtering
#      in floating point and clipping only at the final write to the image dtype.


def _s8v3t_find_button_layout(root_layout, target_button):
    """Return (layout, index) containing target_button, recursively."""
    if root_layout is None or target_button is None:
        return None, -1
    try:
        for i in range(root_layout.count()):
            item = root_layout.itemAt(i)
            if item is None:
                continue
            if item.widget() is target_button:
                return root_layout, i
            child = item.layout()
            if child is not None:
                found, idx = _s8v3t_find_button_layout(child, target_button)
                if found is not None:
                    return found, idx
    except Exception:
        pass
    return None, -1


def _s8v3t_undo_channel_boolean(self, *_args, **_kwargs):
    """Disable the currently applied channel Boolean operation without deleting analysis data."""
    try:
        self.channel_boolean_enabled = False
        self.intersect_mode = False
    except Exception:
        pass
    try:
        if getattr(self, 'btn_intersect', None) is not None:
            self.btn_intersect.blockSignals(True)
            self.btn_intersect.setChecked(False)
            self.btn_intersect.blockSignals(False)
    except Exception:
        try:
            self.btn_intersect.blockSignals(False)
        except Exception:
            pass
    try:
        if '_s8bool_refresh' in globals():
            _s8bool_refresh(self)
        else:
            if getattr(self, 'roi_panel', None) is not None:
                self.roi_panel.intersect_mode = False
                self.roi_panel.update_both_overlays()
                self.roi_panel.update_plots()
                self.roi_panel.update_stats()
                self.roi_panel._apply_points_colors()
            self._update_channel_status()
    except Exception as e:
        print('Undo Boolean refresh warning:', e)
    try:
        if getattr(self, 'btn_undo_boolean', None) is not None:
            self.btn_undo_boolean.setEnabled(False)
    except Exception:
        pass


_S8V3T_PREV_PIPELINE_INIT = PipelinePanel.__init__
def _s8v3t_pipeline_init(self, viewer):
    _S8V3T_PREV_PIPELINE_INIT(self, viewer)
    self.btn_undo_boolean = QtWidgets.QPushButton('Undo Boolean')
    self.btn_undo_boolean.setEnabled(False)
    self.btn_undo_boolean.setToolTip(
        'Disable the applied channel Boolean operation and restore the uncombined active-channel view. '
        'ROI analyses and overlap caches are not deleted.'
    )
    inserted = False
    try:
        lay, idx = _s8v3t_find_button_layout(self.channel_group.layout(), getattr(self, 'btn_intersect', None))
        if lay is not None:
            lay.insertWidget(int(idx) + 1, self.btn_undo_boolean)
            inserted = True
    except Exception:
        inserted = False
    if not inserted:
        try:
            row = QtWidgets.QHBoxLayout()
            row.addWidget(self.btn_undo_boolean)
            row.addStretch(1)
            self.channel_group.layout().addLayout(row)
        except Exception:
            pass
    self.btn_undo_boolean.clicked.connect(self.undo_channel_boolean)
PipelinePanel.__init__ = _s8v3t_pipeline_init
PipelinePanel.undo_channel_boolean = _s8v3t_undo_channel_boolean


_S8V3T_PREV_UPDATE_CHANNEL_STATUS = PipelinePanel._update_channel_status
def _s8v3t_update_channel_status(self, *args, **kwargs):
    out = _S8V3T_PREV_UPDATE_CHANNEL_STATUS(self, *args, **kwargs)
    try:
        btn = getattr(self, 'btn_undo_boolean', None)
        if btn is not None:
            btn.setEnabled(bool(getattr(self, 'channel_boolean_enabled', False)))
    except Exception:
        pass
    return out
PipelinePanel._update_channel_status = _s8v3t_update_channel_status


_S8V3T_PREV_FILTER_TEMPORAL_PROGRESS = filter_temporal_progress

def _s8v3t_savgol_tasks(T, Z, Y, X, work_itemsize, worker_hint):
    """Create independent full-time Z/Y stripes sized for memory and CPU parallelism."""
    T = max(1, int(T)); Z = max(1, int(Z)); Y = max(1, int(Y)); X = max(1, int(X))
    worker_hint = max(1, int(worker_hint))
    # Aim for at least ~2 tasks/worker when Z alone does not expose enough parallelism.
    parts_per_z = max(1, int(math.ceil((worker_hint * 2.0) / float(Z))))
    rows_for_parallel = max(1, int(math.ceil(Y / float(parts_per_z))))
    # Bound the working set per task. Savitzky-Golay typically needs input/output plus scratch.
    target_bytes = int(96 * 1024 * 1024)
    bytes_per_y = max(1, int(T) * int(X) * int(work_itemsize) * 3)
    rows_for_memory = max(1, int(target_bytes // bytes_per_y))
    y_chunk = max(1, min(Y, rows_for_parallel, rows_for_memory))
    tasks = []
    for z in range(Z):
        for y0 in range(0, Y, y_chunk):
            tasks.append((int(z), int(y0), int(min(Y, y0 + y_chunk))))
    return tasks


def filter_temporal_progress(TZYX, use_savgol: bool, win_req: int = None, do_bg_subtract: bool = True, parent=None):
    shape = tuple(int(v) for v in TZYX.shape)
    if len(shape) != 4:
        return _S8V3T_PREV_FILTER_TEMPORAL_PROGRESS(
            TZYX, use_savgol=use_savgol, win_req=win_req,
            do_bg_subtract=do_bg_subtract, parent=parent
        )
    T, Z, Y, X = shape
    dtype = np.dtype(getattr(TZYX, 'dtype', np.float32))
    win = _normalize_savgol_window(int(win_req) if win_req is not None else 49, T)
    do_sg = bool(use_savgol) and int(win) >= 5
    if not do_sg:
        return _S8V3T_PREV_FILTER_TEMPORAL_PROGRESS(
            TZYX, use_savgol=use_savgol, win_req=win_req,
            do_bg_subtract=do_bg_subtract, parent=parent
        )

    spill = bool(_s8_should_spill(shape, dtype)) if '_s8_should_spill' in globals() else False
    out_path = None
    if spill and '_s8_open_work_memmap' in globals():
        out, out_path = _s8_open_work_memmap(parent, 'filtered', shape, dtype)
    else:
        out = np.empty(shape, dtype=dtype)

    # Float32 is sufficient for integer/float32 image signals and halves Savitzky-Golay
    # temporary memory versus SciPy's default float64 conversion for integer input.
    work_dtype = np.float64 if dtype == np.dtype(np.float64) else np.float32
    worker_hint = (_s8v3h_worker_count(default_cap=32, env_name='SINFIN_ANALYSIS_WORKERS')
                   if '_s8v3h_worker_count' in globals() else _sinfin_max_workers(default_cap=32))
    tasks = _s8v3t_savgol_tasks(T, Z, Y, X, np.dtype(work_dtype).itemsize, worker_hint)
    if not tasks:
        return out
    max_rows = max(int(y1) - int(y0) for _z, y0, y1 in tasks)
    task_mem = int(T) * int(max_rows) * int(X) * int(np.dtype(work_dtype).itemsize) * 3
    workers = (_s8v3h_worker_count(len(tasks), default_cap=32, memory_per_worker_bytes=task_mem,
                                   env_name='SINFIN_ANALYSIS_WORKERS')
               if '_s8v3h_worker_count' in globals()
               else min(len(tasks), _sinfin_max_workers(default_cap=32)))

    prog = StepProgress('Filtering (temporal)', maximum=max(1, len(tasks)), parent=parent)
    mode_text = 'disk-backed' if spill else 'in-memory'
    if workers > 1:
        prog.set_text(f'Applying Savitzky–Golay ({mode_text}, {workers} workers, window={win})...')
    else:
        prog.set_text(f'Applying Savitzky–Golay ({mode_text}, window={win})...')

    int_output = np.issubdtype(dtype, np.integer)
    dtype_info = np.iinfo(dtype) if int_output else None

    def _filter_stripe(task):
        z, y0, y1 = task
        src = np.asarray(TZYX[:, z, y0:y1, :], dtype=work_dtype)
        arr = savgol_filter(src, int(win), 3, axis=0, mode='mirror')
        # Background subtraction is pixelwise across time, so it can be fused here
        # without a second full-volume pass through a memmap.
        if bool(do_bg_subtract):
            baseline = np.amin(arr, axis=0)
            np.subtract(arr, baseline[None, ...], out=arr)
        if int_output:
            # The previous integer-buffer path could wrap negative SG overshoot into
            # very large unsigned values before its final clip. Clip while still float.
            np.clip(arr, dtype_info.min, dtype_info.max, out=arr)
        out[:, z, y0:y1, :] = arr.astype(dtype, copy=False)
        return 1

    done = 0
    parallel_ok = bool(workers > 1 and len(tasks) > 1)
    if parallel_ok and '_s8v3h_parallel_enabled' in globals():
        parallel_ok = bool(_s8v3h_parallel_enabled())
    if parallel_ok and '_S8V3HThreadPoolExecutor' in globals() and _S8V3HThreadPoolExecutor is not None:
        with _S8V3HThreadPoolExecutor(max_workers=int(workers)) as ex:
            futures = [ex.submit(_filter_stripe, task) for task in tasks]
            iterator = _s8v3h_as_completed(futures) if '_s8v3h_as_completed' in globals() and _s8v3h_as_completed is not None else futures
            for fut in iterator:
                fut.result()
                done += 1
                prog.step(done)
    else:
        for task in tasks:
            _filter_stripe(task)
            done += 1
            prog.step(done)
    prog.close()

    if spill and '_s8_flush_array' in globals():
        _s8_flush_array(out)
    if out_path:
        try:
            print(f'S8 V3T: Savitzky-Golay filtered stack spilled to {out_path}')
        except Exception:
            pass
    return out

# --- END PATCH: V3T BOOLEAN UNDO + FAST/CORRECT SAVITZKY-GOLAY ---


# --- BEGIN PATCH: V3V GEOMETRY-MATCHED F/F0 AMPLITUDE FOR DYNAMIC ROIS ---
#
# Amplitude is now normalized against the baseline brightness of the SAME
# changing spatial footprint used at each timepoint.  For ROI footprint R_t:
#
#       F(t)  = mean raw input intensity over R_t at t
#       F0(t) = mean baseline-image intensity over R_t
#       F/F0  = F(t) / F0(t)
#
# The baseline image is estimated voxelwise from ALL frames outside the ROI's
# complete active interval: every frame before first activity plus every frame
# after final activity.  These quiet flanks are pooled and summarized by their
# voxelwise median.  The active interval itself (including any internal gaps) is
# excluded so event fluorescence cannot contaminate its own F0 estimate.  If an
# ROI spans the entire recording and therefore has no outside-baseline frames,
# F/F0 is reported as unavailable rather than switching to a different estimator.
# Because F(t) and F0(t) use identical R_t, changes in mask size/shape do not by
# themselves change the normalization denominator.
#
# Existing processed meanint_t and absolute meanint_raw_t are retained for
# compatibility/diagnostics.  The user-facing amplitude trace, amp_range metric,
# fingerprint amplitude feature, ontology "Intense" metric, pickle viewer, and
# PDF amplitude plots use geometry-matched F/F0.
#
_S8V3V_FF0_KEY = 'ff0_t'
_S8V3V_DFF0_KEY = 'dff0_t'
_S8V3V_F0_KEY = 'f0_t'
_S8V3V_RAW_KEY = globals().get('_S8V3K_RAW_INTENSITY_KEY', 'meanint_raw_t')


def _s8v3v_shape4_from_state(st, rois=None):
    try:
        if '_s8_shape_from_state_or_rois' in globals():
            shp = _s8_shape_from_state_or_rois(st or {}, rois=rois or {})
            if shp and len(shp) == 4:
                return tuple(int(v) for v in shp)
    except Exception:
        pass
    for key in ('img', 'filtered', '_s8_absolute_raw_source_tzyx'):
        try:
            a = (st or {}).get(key, None)
            if a is not None and len(a.shape) == 4:
                return tuple(int(v) for v in a.shape)
        except Exception:
            pass
    return None


def _s8v3v_raw_source(panel, ch, st, rois=None):
    try:
        if '_s8v3o_resolve_raw_source' in globals():
            _name, img = _s8v3o_resolve_raw_source(panel, int(ch), st or {}, rois=rois or {})
            if img is not None:
                return str(_name or 'original_input_channel'), img
    except Exception:
        pass
    try:
        img = (st or {}).get('_s8_absolute_raw_source_tzyx', None)
        if img is not None:
            return str((st or {}).get('_s8_absolute_raw_source_name', 'original_input_channel')), img
    except Exception:
        pass
    try:
        img = (st or {}).get('img', None)
        if img is not None:
            return 'channel_state.img', img
    except Exception:
        pass
    return None, None


def _s8v3v_spatial_stride(shape):
    T, Z, Y, X = [int(v) for v in shape]
    return int(Z) * int(Y) * int(X)


def _s8v3v_spatial_keys_from_source(src, shape, time=None):
    """Return flattened ZYX keys, optionally for one ROI timepoint."""
    if src is None or shape is None:
        return np.zeros(0, dtype=np.int64)
    T, Z, Y, X = [int(v) for v in shape]
    stride_t = _s8v3v_spatial_stride(shape)
    try:
        if '_s8_is_coord_ref' in globals() and _s8_is_coord_ref(src):
            keys = _s8_coord_ref_keys(src, time=None if time is None else int(time))
            if keys is None or getattr(keys, 'size', 0) == 0:
                return np.zeros(0, dtype=np.int64)
            k = np.asarray(keys, dtype=np.uint64).reshape(-1)
            return np.asarray(k % np.uint64(stride_t), dtype=np.int64)
    except Exception:
        pass
    try:
        c = np.asarray(src)
        if c.size == 0:
            return np.zeros(0, dtype=np.int64)
        c = c.reshape(-1, c.shape[-1] if c.ndim > 1 else 4)
        if c.shape[1] < 4:
            return np.zeros(0, dtype=np.int64)
        if time is not None:
            c = c[c[:, 0].astype(np.int64, copy=False) == int(time)]
            if c.size == 0:
                return np.zeros(0, dtype=np.int64)
        z = c[:, 1].astype(np.int64, copy=False)
        y = c[:, 2].astype(np.int64, copy=False)
        x = c[:, 3].astype(np.int64, copy=False)
        good = (z >= 0) & (z < Z) & (y >= 0) & (y < Y) & (x >= 0) & (x < X)
        if not np.any(good):
            return np.zeros(0, dtype=np.int64)
        return ((z[good] * int(Y) + y[good]) * int(X) + x[good]).astype(np.int64, copy=False)
    except Exception:
        return np.zeros(0, dtype=np.int64)


def _s8v3v_active_times(arr, T):
    T = int(T)
    try:
        meta = arr[13] if arr is not None and len(arr) > 13 and isinstance(arr[13], dict) else {}
        area = np.asarray(meta.get('area_t', []), dtype=float).reshape(-1)
        if area.size:
            n = min(T, int(area.size))
            return np.where(area[:n] > 0)[0].astype(np.int64)
    except Exception:
        pass
    try:
        src = arr[8] if arr is not None and len(arr) > 8 else None
        if '_s8_is_coord_ref' in globals() and _s8_is_coord_ref(src):
            tt = np.asarray(src.get('time_index_t', []), dtype=np.int64).reshape(-1)
            if tt.size:
                return tt[(tt >= 0) & (tt < T)]
    except Exception:
        pass
    try:
        src = arr[8] if arr is not None and len(arr) > 8 else None
        c = np.asarray(src)
        if c.size:
            c = c.reshape(-1, 4)
            tt = np.unique(c[:, 0].astype(np.int64))
            return tt[(tt >= 0) & (tt < T)]
    except Exception:
        pass
    return np.zeros(0, dtype=np.int64)


def _s8v3v_decode_spatial_keys(spatial_keys, shape):
    _, Z, Y, X = [int(v) for v in shape]
    k = np.asarray(spatial_keys, dtype=np.int64).reshape(-1)
    z = k // (int(Y) * int(X))
    rem = k % (int(Y) * int(X))
    y = rem // int(X)
    x = rem % int(X)
    return z.astype(np.intp, copy=False), y.astype(np.intp, copy=False), x.astype(np.intp, copy=False)


def _s8v3v_baseline_image_on_roi_support(raw_img, spatial_keys, baseline_frames,
                                         percentile=None, shape=None):
    """Estimate one baseline value per unique spatial voxel in the ROI support."""
    keys = np.unique(np.asarray(spatial_keys, dtype=np.int64).reshape(-1))
    frames = np.asarray(baseline_frames, dtype=np.int64).reshape(-1)
    if keys.size == 0 or frames.size == 0 or raw_img is None or shape is None:
        return keys, np.zeros(keys.size, dtype=np.float32)
    frames = frames[(frames >= 0) & (frames < int(shape[0]))]
    if frames.size == 0:
        return keys, np.zeros(keys.size, dtype=np.float32)

    # Keep each temporary frame-by-voxel block around ~24 MiB.
    bytes_target = 24 * 1024 * 1024
    chunk = max(1024, int(bytes_target // max(4, int(frames.size) * 4)))
    chunk = min(chunk, 100000)
    baseline = np.empty(keys.size, dtype=np.float32)

    for start in range(0, int(keys.size), int(chunk)):
        stop = min(int(keys.size), start + int(chunk))
        z, y, x = _s8v3v_decode_spatial_keys(keys[start:stop], shape)
        vals = np.empty((int(frames.size), int(stop - start)), dtype=np.float32)
        for j, tt in enumerate(frames):
            vals[j] = np.asarray(raw_img[int(tt), z, y, x], dtype=np.float32)
        if percentile is None:
            b = np.nanmedian(vals, axis=0)
        else:
            b = np.nanpercentile(vals, float(percentile), axis=0)
        baseline[start:stop] = np.asarray(b, dtype=np.float32)
    return keys, baseline


def _s8v3v_raw_trace_for_roi(arr, raw_img, T):
    T = int(T)
    try:
        meta = arr[13] if arr is not None and len(arr) > 13 and isinstance(arr[13], dict) else {}
        raw = np.asarray(meta.get(_S8V3V_RAW_KEY, []), dtype=np.float32).reshape(-1)
        if raw.size == T and np.any(np.isfinite(raw)):
            return raw
    except Exception:
        pass
    try:
        if '_s8v3o_trace_from_original' in globals():
            raw = _s8v3o_trace_from_original(arr, raw_img, T)
            raw = np.asarray(raw, dtype=np.float32).reshape(-1)
            if raw.size == T:
                return raw
    except Exception:
        pass
    try:
        src = arr[8] if arr is not None and len(arr) > 8 else None
        if src is not None and raw_img is not None:
            raw = np.asarray(amp_from_coords(src, raw_img, T), dtype=np.float32).reshape(-1)
            if raw.size == T:
                return raw
    except Exception:
        pass
    return np.full(T, np.nan, dtype=np.float32)


def _s8v3v_compute_geometry_matched_ff0(arr, raw_img, shape):
    """Geometry-matched F/F0 using every quiet frame before and after the event."""
    T = int(shape[0])
    active_times = _s8v3v_active_times(arr, T)
    ff0 = np.full(T, np.nan, dtype=np.float32)
    dff0 = np.full(T, np.nan, dtype=np.float32)
    f0_t = np.full(T, np.nan, dtype=np.float32)
    raw = _s8v3v_raw_trace_for_roi(arr, raw_img, T)
    if active_times.size == 0:
        return ff0, dff0, f0_t, raw, {
            'baseline_method': 'unavailable_no_active_times',
            'baseline_frames': [],
            'baseline_frame_count': 0,
        }

    src = arr[8] if arr is not None and len(arr) > 8 else None
    all_spatial = _s8v3v_spatial_keys_from_source(src, shape, time=None)
    if all_spatial.size == 0:
        return ff0, dff0, f0_t, raw, {
            'baseline_method': 'unavailable_no_roi_coordinates',
            'baseline_frames': [],
            'baseline_frame_count': 0,
        }

    onset = int(active_times[0])
    offset = int(active_times[-1])
    pre = np.arange(0, onset, dtype=np.int64)
    post = np.arange(offset + 1, T, dtype=np.int64)
    if pre.size and post.size:
        baseline_frames = np.concatenate((pre, post))
        quality = 'pre_and_post_event'
    elif pre.size:
        baseline_frames = pre
        quality = 'pre_event_only'
    elif post.size:
        baseline_frames = post
        quality = 'post_event_only'
    else:
        baseline_frames = np.zeros(0, dtype=np.int64)
        quality = 'no_outside_event_frames'

    method = 'all_outside_event_frames_voxelwise_median'
    if baseline_frames.size == 0:
        return ff0, dff0, f0_t, raw, {
            'baseline_method': 'unavailable_no_outside_event_frames',
            'baseline_quality': quality,
            'baseline_frames': [],
            'baseline_frame_count': 0,
            'pre_baseline_frame_count': int(pre.size),
            'post_baseline_frame_count': int(post.size),
            'onset_frame': int(onset),
            'offset_frame': int(offset),
            'normalization': 'geometry_matched_dynamic_footprint',
        }

    base_keys, base_vals = _s8v3v_baseline_image_on_roi_support(
        raw_img, all_spatial, baseline_frames,
        percentile=None, shape=shape
    )
    if base_keys.size == 0 or base_vals.size == 0:
        return ff0, dff0, f0_t, raw, {
            'baseline_method': 'unavailable_baseline_estimation_failed',
            'baseline_quality': quality,
            'baseline_frames': [int(v) for v in baseline_frames],
            'baseline_frame_count': int(len(baseline_frames)),
            'pre_baseline_frame_count': int(pre.size),
            'post_baseline_frame_count': int(post.size),
            'onset_frame': int(onset),
            'offset_frame': int(offset),
            'normalization': 'geometry_matched_dynamic_footprint',
        }

    tiny = max(float(np.finfo(np.float32).tiny), 1e-12)
    for tt in active_times:
        tt = int(tt)
        sp = _s8v3v_spatial_keys_from_source(src, shape, time=tt)
        if sp.size == 0:
            continue
        pos = np.searchsorted(base_keys, sp)
        good = (pos >= 0) & (pos < base_keys.size)
        if np.any(good):
            pg = pos[good]
            sg = sp[good]
            exact = base_keys[pg] == sg
            if np.any(exact):
                vals0 = np.asarray(base_vals[pg[exact]], dtype=np.float64)
                vals0 = vals0[np.isfinite(vals0)]
                if vals0.size:
                    f0 = float(np.mean(vals0))
                    if np.isfinite(f0) and abs(f0) > tiny:
                        f0_t[tt] = f0
                        ft = float(raw[tt]) if tt < raw.size else np.nan
                        if not np.isfinite(ft):
                            z, y, x = _s8v3v_decode_spatial_keys(sp, shape)
                            try:
                                ft = float(np.nanmean(np.asarray(raw_img[tt, z, y, x], dtype=np.float64)))
                            except Exception:
                                ft = np.nan
                        if np.isfinite(ft):
                            if tt < raw.size:
                                raw[tt] = float(ft)
                            ratio = float(ft / f0)
                            ff0[tt] = ratio
                            dff0[tt] = ratio - 1.0

    return ff0, dff0, f0_t, raw, {
        'baseline_method': method,
        'baseline_quality': quality,
        'baseline_frames': [int(v) for v in baseline_frames],
        'baseline_frame_count': int(len(baseline_frames)),
        'pre_baseline_frame_count': int(pre.size),
        'post_baseline_frame_count': int(post.size),
        'onset_frame': int(onset),
        'offset_frame': int(offset),
        'normalization': 'geometry_matched_dynamic_footprint',
    }

def _s8v3v_attach_channel_amplitude(panel, ch):
    ch = int(ch)
    try:
        st = panel._get_channel_state(ch)
    except Exception:
        return {}
    rois = st.get('sites', {}) or {}
    if not rois:
        return {}
    shape = _s8v3v_shape4_from_state(st, rois=rois)
    if shape is None:
        return {}
    source_name, raw_img = _s8v3v_raw_source(panel, ch, st, rois=rois)
    if raw_img is None:
        return {}
    T = int(shape[0])

    old_amp = st.get('amp_dict_filt', None)
    if old_amp is not None and 'amp_dict_processed_legacy' not in st:
        st['amp_dict_processed_legacy'] = old_amp

    ff0_map = {}
    dff0_map = {}
    f0_map = {}
    raw_map_small = {}
    failures = 0
    prog = StepProgress('Amplitude normalization', maximum=max(1, len(rois)), parent=panel)
    prog.set_text('Computing geometry-matched F/F₀ for dynamic ROIs...')
    for i, (rid, arr) in enumerate(rois.items(), start=1):
        try:
            ff0, dff0, f0_t, raw, info = _s8v3v_compute_geometry_matched_ff0(
                arr, raw_img, shape
            )
            rid_i = int(rid)
            ff0_map[rid_i] = ff0
            dff0_map[rid_i] = dff0
            f0_map[rid_i] = f0_t
            raw_map_small[rid_i] = raw
            if arr is not None and len(arr) > 13:
                meta = dict(arr[13]) if isinstance(arr[13], dict) else {}
                meta[_S8V3V_FF0_KEY] = ff0.astype(np.float32, copy=False)
                meta[_S8V3V_DFF0_KEY] = dff0.astype(np.float32, copy=False)
                meta[_S8V3V_F0_KEY] = f0_t.astype(np.float32, copy=False)
                # Preserve the true raw trace alongside the normalized trace.
                meta[_S8V3V_RAW_KEY] = raw.astype(np.float32, copy=False)
                meta['amplitude_trace_field'] = _S8V3V_FF0_KEY
                meta['amplitude_definition'] = 'F/F0 using the same dynamic ROI footprint in F and voxelwise F0.'
                meta['f0_definition'] = 'Voxelwise baseline projected onto each time-varying ROI footprint.'
                meta['f0_baseline_method'] = str(info.get('baseline_method', 'unknown'))
                meta['f0_baseline_quality'] = str(info.get('baseline_quality', 'unknown'))
                meta['f0_baseline_frames'] = list(info.get('baseline_frames', []))
                meta['f0_baseline_frame_count'] = int(info.get('baseline_frame_count', 0) or 0)
                meta['f0_pre_baseline_frame_count'] = int(info.get('pre_baseline_frame_count', 0) or 0)
                meta['f0_post_baseline_frame_count'] = int(info.get('post_baseline_frame_count', 0) or 0)
                meta['f0_onset_frame'] = int(info.get('onset_frame', -1))
                meta['f0_offset_frame'] = int(info.get('offset_frame', -1))
                meta['f0_geometry_matched'] = True
                finite_ff0 = ff0[np.isfinite(ff0)]
                finite_dff0 = dff0[np.isfinite(dff0)]
                if finite_ff0.size:
                    ff0_range = float(np.max(finite_ff0) - np.min(finite_ff0))
                    meta['ff0_min'] = float(np.min(finite_ff0))
                    meta['ff0_max'] = float(np.max(finite_ff0))
                    meta['ff0_range'] = ff0_range
                    # Preserve legacy array slots while updating their amplitude
                    # meaning to the new normalized signal.
                    try:
                        arr[4] = finite_ff0.astype(float, copy=False)
                        arr[5] = ff0_range
                    except Exception:
                        pass
                else:
                    meta['ff0_range'] = 0.0
                    try:
                        arr[4] = np.zeros(0, dtype=float)
                        arr[5] = 0.0
                    except Exception:
                        pass
                if finite_dff0.size:
                    meta['peak_dff0'] = float(np.max(finite_dff0))
                    meta['min_dff0'] = float(np.min(finite_dff0))
                else:
                    meta['peak_dff0'] = np.nan
                    meta['min_dff0'] = np.nan
                arr[13] = meta
        except Exception as e:
            failures += 1
            try:
                print(f'F/F0 normalization failed for ROI {rid}:', e)
            except Exception:
                pass
        prog.step(i)
    prog.close()

    st['amp_dict_ff0'] = ff0_map
    st['amp_dict_dff0'] = dff0_map
    st['f0_dict'] = f0_map
    # The existing amp_dict_filt is the generic analysis-amplitude channel used by
    # plots and paired-channel displays.  Point it to normalized amplitude while
    # retaining the legacy processed trace above.
    st['amp_dict_filt'] = ff0_map
    st['amplitude_mode'] = 'geometry_matched_ff0'
    st['amplitude_raw_source'] = source_name
    st['amplitude_baseline_method'] = 'all_outside_event_frames_voxelwise_median'
    st['amplitude_normalization_failures'] = int(failures)
    return ff0_map


# No amplitude-specific GUI controls: baseline selection is automatic.


# Attach normalized amplitude immediately after the established Step 3 pipeline.
_S8V3V_PREV_DO_ANALYZE = PipelinePanel.do_analyze
def _s8v3v_do_analyze(self, *args, **kwargs):
    out = _S8V3V_PREV_DO_ANALYZE(self, *args, **kwargs)
    try:
        ch = int(getattr(self, 'current_channel', 0))
        ff0_map = _s8v3v_attach_channel_amplitude(self, ch)
        st = self._get_channel_state(ch)
        self.amp_dict_filt = st.get('amp_dict_filt', ff0_map)
        rp = getattr(self, 'roi_panel', None)
        if rp is not None and int(getattr(rp, 'current_channel', ch)) == ch:
            rp.amp_dict_filt = st.get('amp_dict_filt', ff0_map)
            try:
                rp._build_metrics_cache()
            except Exception:
                pass
            try:
                rp.update_classification()
            except Exception:
                pass
            try:
                if '_refresh_fingerprint' in globals():
                    _refresh_fingerprint(rp)
            except Exception:
                pass
            try:
                rp.update_plots()
                rp.update_stats()
            except Exception:
                pass
        try:
            self._update_channel_status()
        except Exception:
            pass
    except Exception as e:
        print('F/F0 post-analysis normalization warning:', e)
    return out
PipelinePanel.do_analyze = _s8v3v_do_analyze


# When switching channels, ensure the live panel points at that channel's
# normalized amplitude dictionary if Step 3 has already been run there.
_S8V3V_PREV_ACTIVATE_CHANNEL = PipelinePanel._activate_channel
def _s8v3v_activate_channel(self, ch, *args, **kwargs):
    out = _S8V3V_PREV_ACTIVATE_CHANNEL(self, ch, *args, **kwargs)
    try:
        st = self._get_channel_state(int(ch))
        if st.get('amp_dict_ff0'):
            st['amp_dict_filt'] = st.get('amp_dict_ff0')
            self.amp_dict_filt = st.get('amp_dict_ff0')
            rp = getattr(self, 'roi_panel', None)
            if rp is not None:
                rp.amp_dict_filt = st.get('amp_dict_ff0')
    except Exception:
        pass
    return out
PipelinePanel._activate_channel = _s8v3v_activate_channel


# The "filtered amplitude" accessor is the normalized analysis amplitude.
_S8V3V_PREV_GET_AMP_FILTERED = ROIPanel._get_roi_amp_series_filtered
def _s8v3v_get_roi_amp_series_filtered(self, roi_id):
    try:
        arr = self.sites[int(roi_id)]
        meta = arr[13] if len(arr) > 13 and isinstance(arr[13], dict) else {}
        ff0 = np.asarray(meta.get(_S8V3V_FF0_KEY, []), dtype=float).reshape(-1)
        if ff0.size:
            return ff0
    except Exception:
        pass
    try:
        if self.amp_dict_filt is not None and int(roi_id) in self.amp_dict_filt:
            return np.asarray(self.amp_dict_filt[int(roi_id)], dtype=float)
    except Exception:
        pass
    return _S8V3V_PREV_GET_AMP_FILTERED(self, roi_id)
ROIPanel._get_roi_amp_series_filtered = _s8v3v_get_roi_amp_series_filtered


# Live ROI plot: keep the established volume panel and replace the intensity
# panel with the geometry-matched F/F0 trace.  Raw absolute values remain stored.
_S8V3V_PREV_ROIPLOTS_UPDATE = ROIPlots.update_data
def _s8v3v_roiplots_update(self, area_t, amp_filt=None, amp_raw=None,
                           current_t=None, labels=None):
    # V3P's routine displays its amp_raw argument. Feed normalized amplitude into
    # that existing plotting path so all established axis/time behavior is kept.
    out = _S8V3V_PREV_ROIPLOTS_UPDATE(
        self, area_t, None, amp_filt, current_t=current_t, labels=labels
    )
    try:
        self.ax_int.set_title('Distribution-matched F/F₀ vs time')
        self.ax_int.set_ylabel('F/F₀ (baseline = 1)')
        for line in self.ax_int.get_lines():
            lab = str(line.get_label() or '')
            if lab and not lab.startswith('_'):
                lab = lab.replace('(raw absolute)', '(F/F₀)').replace('(raw)', '(F/F₀)')
                line.set_label(lab)
        self.ax_int.axhline(1.0, lw=0.8, ls=':', alpha=0.55)
        handles, labs = self.ax_int.get_legend_handles_labels()
        if handles:
            self.ax_int.legend(handles, labs, loc='upper right', fontsize=8, frameon=False)
        self.canvas.draw_idle()
    except Exception:
        pass
    return out
ROIPlots.update_data = _s8v3v_roiplots_update


# Stats: preserve all established stats/boolean text and relabel the amplitude
# values now returned by the normalized accessor.
_S8V3V_PREV_UPDATE_STATS = ROIPanel.update_stats
def _s8v3v_update_stats(self):
    _S8V3V_PREV_UPDATE_STATS(self)
    try:
        txt = str(self.stats.toPlainText())
        txt = txt.replace('Filtered Amp (max):', 'F/F₀ (max):')
        txt = txt.replace('Filtered Amp (t=', 'F/F₀ (t=')
        if self.current_roi is not None and self.sites is not None:
            arr = self.sites[int(self.current_roi)]
            meta = arr[13] if len(arr) > 13 and isinstance(arr[13], dict) else {}
            peak = meta.get('peak_dff0', np.nan)
            method = str(meta.get('f0_baseline_method', 'unknown'))
            quality = str(meta.get('f0_baseline_quality', ''))
            extra = []
            if np.isfinite(float(peak)) if peak is not None else False:
                extra.append(f'Peak ΔF/F₀: {float(peak):.3f}')
            extra.append(f'F₀: {method}' + (f' ({quality})' if quality else ''))
            txt = txt.rstrip() + '\n' + '\n'.join(extra)
        self.stats.setPlainText(txt)
    except Exception:
        pass
ROIPanel.update_stats = _s8v3v_update_stats


# Pair-series export carries explicit normalized fields and uses F/F0 as the
# generic amp_filt compatibility field.
try:
    _S8V3V_PREV_LIGHT_PAIR_SERIES = _s8_light_pair_series_from_compact_roi
    def _s8_light_pair_series_from_compact_roi(st, rois_compact, roi_id):
        ser = _S8V3V_PREV_LIGHT_PAIR_SERIES(st, rois_compact, roi_id)
        if ser is None:
            return None
        try:
            rid = int(roi_id)
            arr = (rois_compact or {}).get(rid, (rois_compact or {}).get(str(rid)))
            meta = arr[13] if arr is not None and len(arr) > 13 and isinstance(arr[13], dict) else {}
            ff0 = np.asarray(meta.get(_S8V3V_FF0_KEY, []), dtype=np.float32)
            dff0 = np.asarray(meta.get(_S8V3V_DFF0_KEY, []), dtype=np.float32)
            f0 = np.asarray(meta.get(_S8V3V_F0_KEY, []), dtype=np.float32)
            if ff0.size:
                ser['amp_ff0'] = ff0
                ser['amp_dff0'] = dff0
                ser['f0_t'] = f0
                ser['amp_filt'] = ff0
                ser['amplitude_mode'] = 'geometry_matched_ff0'
        except Exception:
            pass
        return ser
except Exception as _e:
    print('F/F0 pair-series patch skipped:', _e)


# General pickle ROI-series accessor: expose normalized traces from ROI metadata.
try:
    _S8V3V_PREV_PVIZ_ROI_SERIES = _s8_pviz_roi_series_any
    def _s8_pviz_roi_series_any(data, channel, roi_id):
        ser, T = _S8V3V_PREV_PVIZ_ROI_SERIES(data, channel, roi_id)
        try:
            meta = ser.get('meta', {}) or {}
            ff0 = np.asarray(meta.get(_S8V3V_FF0_KEY, ser.get('amp_ff0', [])), dtype=float).reshape(-1)
            dff0 = np.asarray(meta.get(_S8V3V_DFF0_KEY, ser.get('amp_dff0', [])), dtype=float).reshape(-1)
            f0 = np.asarray(meta.get(_S8V3V_F0_KEY, ser.get('f0_t', [])), dtype=float).reshape(-1)
            T = int(max(int(T), ff0.size, dff0.size, f0.size, 1))
            ser[_S8V3V_FF0_KEY] = ff0
            ser[_S8V3V_DFF0_KEY] = dff0
            ser[_S8V3V_F0_KEY] = f0
            ser['ff0_available'] = bool(ff0.size)
        except Exception:
            pass
        return ser, T
except Exception as _e:
    print('F/F0 pickle series accessor patch skipped:', _e)


# Pickle visualizer: new exports show F/F0. Legacy exports without F/F0 retain
# the established raw-absolute trace rather than inventing a baseline.
try:
    _S8V3V_PREV_PVIZ_REFRESH = S8PickleVisualizationDialog.refresh_roi_view
    def _s8v3v_pviz_refresh(self, *args, **kwargs):
        out = _S8V3V_PREV_PVIZ_REFRESH(self, *args, **kwargs)
        try:
            fig = getattr(self, 'fig_roi_trace', None)
            axes = list(fig.axes) if fig is not None else []
            if len(axes) < 2 or getattr(self, 'data', None) is None:
                return out
            ax_i = axes[1]
            t_now = int(self.spin_roi_t.value()) if hasattr(self, 'spin_roi_t') else 0
            pair = None
            try:
                if _s8_pviz_unified_mode(self) == 'pair':
                    pair = _s8_pviz_current_unified_pair(self)
            except Exception:
                pair = None

            if pair is not None:
                T = max(1, int(_s8_pviz_pair_T_any(self.data, pair)))
                x = np.arange(T)
                plotted = 0
                ax_i.clear()
                sa = pair.get('series_a', {}) or {}
                sb = pair.get('series_b', {}) or {}
                ca = int(pair.get('channel_a', 0)); cb = int(pair.get('channel_b', 1))
                ra = int(pair.get('roi_a', sa.get('roi_id', -1)))
                rb = int(pair.get('roi_b', sb.get('roi_id', -1)))
                for ser, ch, rid, ls in ((sa, ca, ra, '-'), (sb, cb, rb, '--')):
                    ff0 = np.asarray(ser.get('amp_ff0', ser.get(_S8V3V_FF0_KEY, [])), dtype=float).reshape(-1)
                    if ff0.size:
                        y = _s8v3k_pad_trace(ff0, T, float)
                        ax_i.plot(x, y, lw=1.6, ls=ls, label=f'Ch{ch} ROI {rid} F/F₀')
                        plotted += 1
                if plotted:
                    ax_i.axhline(1.0, lw=0.8, ls=':', alpha=0.55)
                    ax_i.axvline(max(0, min(t_now, T - 1)), ls='--', lw=1, color='0.35')
                    ax_i.set_title('Intersect pair: distribution-matched F/F₀ vs time')
                    ax_i.set_xlabel('time (frame)')
                    ax_i.set_ylabel('F/F₀ (baseline = 1)')
                    ax_i.grid(True, alpha=0.2)
                    ax_i.legend(loc='best', fontsize=8, frameon=False)
            else:
                ch = _s8_pviz_selected_channel(self)
                rid = _s8_pviz_selected_roi(self)
                if rid is not None:
                    ser, T = _s8_pviz_roi_series_any(self.data, ch, rid)
                    ff0 = np.asarray(ser.get(_S8V3V_FF0_KEY, []), dtype=float).reshape(-1)
                    if ff0.size:
                        T = max(1, int(T)); x = np.arange(T)
                        ax_i.clear()
                        ax_i.plot(x, _s8v3k_pad_trace(ff0, T, float), lw=1.6,
                                  label=f'Ch{ch} ROI {rid} F/F₀')
                        ax_i.axhline(1.0, lw=0.8, ls=':', alpha=0.55)
                        ax_i.axvline(max(0, min(t_now, T - 1)), ls='--', lw=1, color='0.35')
                        ax_i.set_title('Distribution-matched F/F₀ vs time')
                        ax_i.set_xlabel('time (frame)')
                        ax_i.set_ylabel('F/F₀ (baseline = 1)')
                        ax_i.grid(True, alpha=0.2)
                        ax_i.legend(loc='best', fontsize=8, frameon=False)
            self.canvas_roi_trace.draw_idle()
        except Exception as e:
            try:
                print('F/F0 pickle visualizer refresh warning:', e)
            except Exception:
                pass
        return out
    S8PickleVisualizationDialog.refresh_roi_view = _s8v3v_pviz_refresh
except Exception as _e:
    print('F/F0 pickle visualizer patch skipped:', _e)


# Main PDF amplitude page.
_S8V3V_PREV_INTENSITY_PDF = _s8v3k_plot_intensity_series_pdf
def _s8v3k_plot_intensity_series_pdf(pdf, rois, T, meta=None):
    meta = meta or {}
    found = False
    for arr in (rois or {}).values():
        try:
            mr = arr[13] if len(arr) > 13 and isinstance(arr[13], dict) else {}
            if np.asarray(mr.get(_S8V3V_FF0_KEY, [])).size:
                found = True
                break
        except Exception:
            pass
    if not found:
        return _S8V3V_PREV_INTENSITY_PDF(pdf, rois, T, meta=meta)

    cal = _s8_calibration_from_meta(meta)
    maxT = max(1, int(T))
    for arr in (rois or {}).values():
        try:
            mr = arr[13] if len(arr) > 13 and isinstance(arr[13], dict) else {}
            maxT = max(maxT, len(mr.get(_S8V3V_FF0_KEY, [])))
        except Exception:
            pass
    x, xlab = _s8_time_axis(maxT, cal)
    fig = plt.figure(figsize=(12, 7), dpi=160)
    ax = fig.add_subplot(1, 1, 1)
    cmap = plt.get_cmap('tab20')
    plotted = 0
    for idx, (rid, arr) in enumerate(sorted((rois or {}).items(), key=lambda kv: str(kv[0]))):
        try:
            mr = arr[13] if len(arr) > 13 and isinstance(arr[13], dict) else {}
            ff0 = np.asarray(mr.get(_S8V3V_FF0_KEY, []), dtype=float).reshape(-1)
            if not ff0.size:
                continue
            y = _s8v3k_pad_trace(ff0, maxT, float)
            ax.plot(x, y, lw=0.9, alpha=0.6, color=cmap(idx % cmap.N),
                    label=f'ROI {rid}' if len(rois) <= 8 else None)
            plotted += 1
        except Exception:
            continue
    if plotted:
        title = 'ROI distribution-matched F/F₀ over time'
        if meta.get('channel_index') is not None:
            title = f"Channel {meta.get('channel_index')} — " + title
        ax.set_title(title)
        ax.set_xlabel(xlab)
        ax.set_ylabel('F/F₀ (baseline = 1)')
        ax.axhline(1.0, lw=0.9, ls=':', color='0.35', alpha=0.7)
        ax.grid(True, alpha=0.2)
        if len(rois) <= 8:
            ax.legend(loc='best', fontsize=7, frameon=False)
    else:
        ax.text(0.5, 0.5, 'No F/F₀ traces', ha='center', va='center')
        ax.set_axis_off()
    pdf.savefig(fig)
    plt.close(fig)


# Intersect-pair PDF amplitude pages.
_S8V3V_PREV_INTERSECT_PDF = _s8_plot_intersect_channel_series_units
def _s8_plot_intersect_channel_series_units(pdf, combined, max_detail_pages=None):
    pairs = list((combined or {}).get('intersect_report_pairs', []) or [])
    has_ff0 = any(
        np.asarray((p.get(side, {}) or {}).get('amp_ff0', [])).size
        for p in pairs for side in ('series_a', 'series_b')
    )
    if not has_ff0:
        return _S8V3V_PREV_INTERSECT_PDF(pdf, combined, max_detail_pages=max_detail_pages)
    meta = (combined or {}).get('metadata', {}) or {}
    if not bool(meta.get('intersect_mode', False)):
        return
    cal = _s8_calibration_from_meta(meta)
    scale, extent_unit, extent_kind = _s8_extent_scale_and_label(meta, cal)
    T = int((meta.get('shape_TZYX', (0, 0, 0, 0)) or (0, 0, 0, 0))[0] or 0)
    maxT = max([1, T] + [
        len((p.get(side, {}) or {}).get('amp_ff0', []))
        for p in pairs for side in ('series_a', 'series_b')
    ])
    x, xlab = _s8_time_axis(maxT, cal)
    fig = plt.figure(figsize=(12, 7), dpi=160)
    fig.suptitle('Intersected ROI pairs — paired channel traces', fontsize=14)
    gs = fig.add_gridspec(2, 1)
    ax_v = fig.add_subplot(gs[0, 0]); ax_i = fig.add_subplot(gs[1, 0])
    for p in pairs:
        ca = int(p.get('channel_a', 0)); ra = int(p.get('roi_a', 0))
        cb = int(p.get('channel_b', 0)); rb = int(p.get('roi_b', 0))
        for side, ch, rid, ls in (('series_a', ca, ra, '-'), ('series_b', cb, rb, '--')):
            s = p.get(side, {}) or {}
            ax_v.plot(x, _pad_series_for_plot(s.get('area_t', []), maxT) * scale,
                      lw=0.8, alpha=0.45, ls=ls, label=f'ch{ch} ROI {rid}')
            ff0 = np.asarray(s.get('amp_ff0', []), dtype=float).reshape(-1)
            if ff0.size:
                ax_i.plot(x, _pad_series_for_plot(ff0, maxT), lw=0.9, alpha=0.55,
                          ls=ls, label=f'ch{ch} ROI {rid} F/F₀')
    ax_v.set_title(f'All intersected ROI pairs ({len(pairs)} pairs)')
    ax_v.set_xlabel(xlab); ax_v.set_ylabel(extent_unit)
    _s8v3k_apply_report_voxel_scale(ax_v, meta, one_voxel=scale)
    ax_i.set_title('Distribution-matched F/F₀ for intersected ROI pairs')
    ax_i.set_xlabel(xlab); ax_i.set_ylabel('F/F₀ (baseline = 1)')
    ax_i.axhline(1.0, lw=0.8, ls=':', color='0.35', alpha=0.7)
    if len(pairs) <= 8:
        ax_v.legend(loc='upper right', fontsize=6, framealpha=0.6)
        ax_i.legend(loc='upper right', fontsize=6, framealpha=0.6)
    pdf.savefig(fig); plt.close(fig)

    limit = len(pairs) if max_detail_pages is None else min(len(pairs), int(max_detail_pages))
    for p in pairs[:limit]:
        ca = int(p.get('channel_a', 0)); ra = int(p.get('roi_a', 0))
        cb = int(p.get('channel_b', 0)); rb = int(p.get('roi_b', 0))
        ct = int(p.get('overlap_voxels', 0))
        sa = p.get('series_a', {}) or {}; sb = p.get('series_b', {}) or {}
        maxTp = max(1, T, len(sa.get('area_t', [])), len(sb.get('area_t', [])),
                    len(sa.get('amp_ff0', [])), len(sb.get('amp_ff0', [])))
        xp, xlabp = _s8_time_axis(maxTp, cal)
        fig = plt.figure(figsize=(12, 7), dpi=160)
        fig.suptitle(f'Intersect pair: ch{ca} ROI {ra} ↔ ch{cb} ROI {rb} ({ct} shared voxels)', fontsize=13)
        gs = fig.add_gridspec(2, 1)
        ax_v = fig.add_subplot(gs[0, 0]); ax_i = fig.add_subplot(gs[1, 0])
        ax_v.plot(xp, _pad_series_for_plot(sa.get('area_t', []), maxTp) * scale,
                  lw=1.4, label=f'ch{ca} ROI {ra} {extent_kind}')
        ax_v.plot(xp, _pad_series_for_plot(sb.get('area_t', []), maxTp) * scale,
                  lw=1.4, ls='--', label=f'ch{cb} ROI {rb} {extent_kind}')
        ax_v.set_xlabel(xlabp); ax_v.set_ylabel(extent_unit)
        ax_v.legend(loc='upper right', fontsize=8, frameon=False)
        _s8v3k_apply_report_voxel_scale(ax_v, meta, one_voxel=scale)
        for s, ch, rid, ls in ((sa, ca, ra, '-'), (sb, cb, rb, '--')):
            ff0 = np.asarray(s.get('amp_ff0', []), dtype=float).reshape(-1)
            if ff0.size:
                ax_i.plot(xp, _pad_series_for_plot(ff0, maxTp), lw=1.4, ls=ls,
                          label=f'ch{ch} ROI {rid} F/F₀')
        ax_i.set_title('Distribution-matched F/F₀')
        ax_i.set_xlabel(xlabp); ax_i.set_ylabel('F/F₀ (baseline = 1)')
        ax_i.axhline(1.0, lw=0.8, ls=':', color='0.35', alpha=0.7)
        ax_i.legend(loc='upper right', fontsize=8, frameon=False)
        pdf.savefig(fig); plt.close(fig)

_plot_intersect_channel_series = _s8_plot_intersect_channel_series_units


# Fingerprint: keep mean_amp_range for compatibility (its units are now F/F0
# range) and add direct peak ΔF/F0 summaries.
_S8V3V_PREV_SAMPLE_FINGERPRINT = _compute_sample_fingerprint
def _compute_sample_fingerprint(rois: dict, ontology: dict=None, coordination: dict=None,
                                propagation: dict=None, T: int=0):
    fp = _S8V3V_PREV_SAMPLE_FINGERPRINT(
        rois, ontology=ontology, coordination=coordination,
        propagation=propagation, T=T
    )
    peaks = []
    ranges = []
    for arr in (rois or {}).values():
        try:
            mr = arr[13] if len(arr) > 13 and isinstance(arr[13], dict) else {}
            p = float(mr.get('peak_dff0', np.nan))
            r = float(mr.get('ff0_range', np.nan))
            if np.isfinite(p):
                peaks.append(p)
            if np.isfinite(r):
                ranges.append(r)
        except Exception:
            continue
    fp['mean_peak_dff0'] = float(np.mean(peaks)) if peaks else 0.0
    fp['median_peak_dff0'] = float(np.median(peaks)) if peaks else 0.0
    fp['mean_ff0_range'] = float(np.mean(ranges)) if ranges else 0.0
    fp['median_ff0_range'] = float(np.median(ranges)) if ranges else 0.0
    fp['amplitude_normalization_version'] = 2.0
    return fp


