# --- BEGIN BUGFIX: PRESERVE NORMALIZED AMPLITUDE THROUGH COMPACT EXPORT ---
# The compact metadata reducer predates geometry-matched F/F0 and intentionally
# keeps only a small whitelist of per-ROI fields.  Without this wrapper, ff0_t,
# dff0_t and f0_t are dropped before the PDF is assembled, causing the report's
# intensity page to fall back to the legacy absolute-intensity trace.  Preserve
# the compact T-length normalized traces and their provenance; no GUI changes.
try:
    _S8V3V_PREV_COMPACT_META_FF0 = _s8_compact_meta_for_storage
    def _s8_compact_meta_for_storage(meta):
        out = _S8V3V_PREV_COMPACT_META_FF0(meta)
        try:
            if isinstance(meta, dict) and isinstance(out, dict):
                for key in (_S8V3V_FF0_KEY, _S8V3V_DFF0_KEY, _S8V3V_F0_KEY):
                    if key in meta:
                        out[key] = _s8v3k_vec(meta.get(key), np.float32)
                # Raw absolute intensity remains diagnostic data only.  The V3K
                # compact wrapper already preserves it, but retain it here too in
                # case this wrapper is used with another compact path.
                if _S8V3V_RAW_KEY in meta:
                    out[_S8V3V_RAW_KEY] = _s8v3k_vec(meta.get(_S8V3V_RAW_KEY), np.float32)
                for key in (
                    'amplitude_trace_field', 'amplitude_definition',
                    'f0_definition', 'f0_baseline_method', 'f0_baseline_quality',
                    'f0_baseline_frames', 'f0_baseline_frame_count',
                    'f0_pre_baseline_frame_count', 'f0_post_baseline_frame_count',
                    'f0_onset_frame', 'f0_offset_frame', 'f0_geometry_matched',
                    'ff0_min', 'ff0_max', 'peak_ff0', 'ff0_range', 'canonical_amplitude_metric', 'peak_dff0', 'min_dff0'
                ):
                    if key in meta:
                        out[key] = meta[key]
        except Exception:
            pass
        return out
except Exception as _e:
    print('F/F0 compact-export retention patch skipped:', _e)
# --- END BUGFIX: PRESERVE NORMALIZED AMPLITUDE THROUGH COMPACT EXPORT ---

# Relabel the two report summary amplitude axes. The underlying amp_range data
