# --- BEGIN PATCH: V3Z CANONICAL PEAK F/F0 AMPLITUDE METRIC ---
# Peak F/F0 is the canonical scalar amplitude descriptor, analogous to max_area.
# F/F0 range remains available as a secondary descriptor in roi metadata and
# fingerprint fields. Legacy filter rules named amp_range are interpreted as
# peak_ff0 so older ontologies continue to behave sensibly.

_S8V3Z_PREV_METRIC_VALUES = ROIPanel._metric_values
def _s8v3z_metric_values(self, name: str):
    if str(name) == 'amp_range':
        name = 'peak_ff0'
    return _S8V3Z_PREV_METRIC_VALUES(self, name)
ROIPanel._metric_values = _s8v3z_metric_values

_S8V3Z_PREV_SAMPLE_FINGERPRINT = _compute_sample_fingerprint
def _compute_sample_fingerprint(rois: dict, ontology: dict=None, coordination: dict=None,
                                propagation: dict=None, T: int=0):
    fp = _S8V3Z_PREV_SAMPLE_FINGERPRINT(
        rois, ontology=ontology, coordination=coordination,
        propagation=propagation, T=T
    )
    peaks = []
    ranges = []
    for arr in (rois or {}).values():
        try:
            meta = arr[13] if len(arr) > 13 and isinstance(arr[13], dict) else {}
            pk = float(meta.get('peak_ff0', meta.get('ff0_max', arr[5] if len(arr) > 5 else np.nan)))
            rg = float(meta.get('ff0_range', np.nan))
            if np.isfinite(pk): peaks.append(pk)
            if np.isfinite(rg): ranges.append(rg)
        except Exception:
            pass
    fp['mean_peak_ff0'] = float(np.mean(peaks)) if peaks else 0.0
    fp['median_peak_ff0'] = float(np.median(peaks)) if peaks else 0.0
    # Preserve the historical names as the secondary F/F0-range descriptor.
    fp['mean_amp_range'] = float(np.mean(ranges)) if ranges else 0.0
    fp['median_amp_range'] = float(np.median(ranges)) if ranges else 0.0
    fp['canonical_amplitude_metric'] = 'peak_ff0'
    fp['amplitude_normalization_version'] = 5.0
    return fp

# Keep default ontology semantics explicit for newly created defaults.
_S8V3Z_PREV_DEFAULT_ONTOLOGY = _build_default_ontology
def _build_default_ontology(panel):
    _S8V3Z_PREV_DEFAULT_ONTOLOGY(panel)
    changed = False
    for ont in getattr(panel, 'ontology_classes', []) or []:
        if str(ont.get('name', '')).strip().lower() == 'intense':
            for row in ont.get('rows', []) or []:
                if row.get('metric') == 'amp_range':
                    row['metric'] = 'peak_ff0'; changed = True
            if changed:
                ont['description'] = _describe_filter_rows(ont.get('rows', []) or [])
    if changed:
        _apply_ontology(panel)

# Rename amplitude metric entries in stacked-filter rows as they are created.
_S8V3Z_PREV_ROI_INIT = ROIPanel.__init__
def _s8v3z_roi_init(self, *args, **kwargs):
    _S8V3Z_PREV_ROI_INIT(self, *args, **kwargs)
    def _rename_amp_metric_items():
        try:
            combos = [getattr(self, 'cmb_metric', None)] + [r.get('metric') for r in getattr(self, '_sf_rows', []) or []]
            for combo in combos:
                if combo is None: continue
                idx = combo.findText('amp_range')
                if idx >= 0: combo.setItemText(idx, 'peak_ff0')
        except Exception:
            pass
    _rename_amp_metric_items()
    try:
        self.btn_add_filter.clicked.connect(lambda *_: QtCore.QTimer.singleShot(0, _rename_amp_metric_items))
    except Exception:
        pass
ROIPanel.__init__ = _s8v3z_roi_init

