# --- BEGIN PATCH: LEMNIS OPTIONAL GENERIC PICKLE SCATTER ---
# Keep the ROI/intersect viewer uncluttered by allowing the legacy generic
# 2D/3D pickle-scatter controls and canvas to be hidden.  This only changes UI
# visibility; the generic plotting code remains intact and can be restored at
# any time with the checkbox.

def _lemnis_pviz_set_generic_scatter_visible(self, visible):
    visible = bool(visible)
    # Generic scatter-only top-row actions.
    for name in ('btn_plot', 'btn_color', 'btn_png'):
        try:
            getattr(self, name).setVisible(visible)
        except Exception:
            pass

    # Hide/show the generic plotting configuration grid while preserving the
    # ROI/intersect controls added elsewhere in the dialog.
    cfg = getattr(self, '_lemnis_generic_scatter_config_layout', None)
    if cfg is not None:
        try:
            for i in range(cfg.count()):
                item = cfg.itemAt(i)
                w = item.widget() if item is not None else None
                if w is not None:
                    w.setVisible(visible)
        except Exception:
            pass

    try:
        self._lemnis_generic_scatter_label_box.setVisible(visible)
    except Exception:
        pass
    try:
        self._lemnis_generic_scatter_splitter.setVisible(visible)
    except Exception:
        pass


def _lemnis_pviz_find_generic_scatter_widgets(self):
    # The original dialog did not retain local layout variables as attributes,
    # so resolve them once from the widgets that uniquely belong to that module.
    try:
        target = getattr(self, 'cmb_plot_type', None)
        for i in range(self.layout().count()):
            item = self.layout().itemAt(i)
            lay = item.layout() if item is not None else None
            if lay is None:
                continue
            found = False
            for j in range(lay.count()):
                sub = lay.itemAt(j)
                if sub is not None and sub.widget() is target:
                    found = True
                    break
            if found:
                self._lemnis_generic_scatter_config_layout = lay
                break
    except Exception:
        pass

    try:
        for gb in self.findChildren(QtWidgets.QGroupBox):
            if str(gb.title()).strip() == 'Labels and axis limits':
                self._lemnis_generic_scatter_label_box = gb
                break
    except Exception:
        pass

    try:
        canvas = getattr(self, 'canvas', None)
        w = canvas.parentWidget() if canvas is not None else None
        while w is not None and not isinstance(w, QtWidgets.QSplitter):
            w = w.parentWidget()
        if isinstance(w, QtWidgets.QSplitter):
            self._lemnis_generic_scatter_splitter = w
    except Exception:
        pass


def _lemnis_pviz_install_scatter_visibility(self):
    if getattr(self, '_lemnis_scatter_visibility_installed', False):
        return
    self._lemnis_scatter_visibility_installed = True
    _lemnis_pviz_find_generic_scatter_widgets(self)

    self.chk_lemnis_show_generic_scatter = QtWidgets.QCheckBox('Show generic 2D/3D pickle scatter tools')
    self.chk_lemnis_show_generic_scatter.setChecked(False)
    self.chk_lemnis_show_generic_scatter.setToolTip('Show the legacy generic pickle scatter controls, parameter list, and scatter canvas.')

    inserted = False
    try:
        top = self.layout().itemAt(0).layout()
        if top is not None:
            # Keep Load and the file label visible; put the optional-scatter
            # switch beside the file controls.
            top.insertWidget(max(1, top.count() - 1), self.chk_lemnis_show_generic_scatter)
            inserted = True
    except Exception:
        inserted = False
    if not inserted:
        try:
            self.layout().insertWidget(1, self.chk_lemnis_show_generic_scatter)
        except Exception:
            self.layout().addWidget(self.chk_lemnis_show_generic_scatter)

    self.chk_lemnis_show_generic_scatter.toggled.connect(lambda checked: _lemnis_pviz_set_generic_scatter_visible(self, checked))
    _lemnis_pviz_set_generic_scatter_visible(self, False)


