# --- BEGIN PATCH: LEMNIS INTERSECT FINGERPRINT SOURCE ---
# Fingerprint-workspace extension for dual-channel intersect pickles.
# Ordinary single-channel/sample fingerprint files are unchanged.  For an
# intersect pickle, the workspace can derive a temporal/spatial fingerprint
# from the trigger channel, the causally filtered response channel, or both.
# Response fingerprints intentionally use only metrics supported by the paired
# series/coordinates carried in the pickle; unavailable site/coherence/ontology
# values are not fabricated.

def _lemnis_fp_pair_channels(data):
    data = data if isinstance(data, dict) else {}
    filt = data.get('lemnis_pair_filter', {}) or {}
    meta = data.get('metadata', {}) or {}
    pairs = list(data.get('intersect_report_pairs', []) or [])
    chans = set()
    for pair in pairs:
        try: chans.add(int(pair.get('channel_a', -1)))
        except Exception: pass
        try: chans.add(int(pair.get('channel_b', -1)))
        except Exception: pass
    chans = sorted(c for c in chans if c >= 0)

    def _maybe_int(*vals):
        for val in vals:
            if val is None:
                continue
            try:
                return int(val)
            except Exception:
                continue
        return None

    trigger = _maybe_int(
        filt.get('trigger_channel', None),
        meta.get('pair_filter_trigger_channel', None),
    )
    response = _maybe_int(
        filt.get('response_channel', None),
        meta.get('pair_filter_response_channel', None),
    )
    if trigger is None or trigger not in chans:
        trigger = 0 if 0 in chans else (chans[0] if chans else 0)
    if response is None or response not in chans or response == trigger:
        if 1 in chans and 1 != trigger:
            response = 1
        else:
            response = next((c for c in chans if c != trigger), trigger)
    return int(trigger), int(response), chans


def _lemnis_fp_pair_series(pair, channel):
    pair = pair or {}
    try:
        ca = int(pair.get('channel_a', -1))
    except Exception:
        ca = -1
    try:
        cb = int(pair.get('channel_b', -1))
    except Exception:
        cb = -1
    channel = int(channel)
    if ca == channel:
        ser = pair.get('series_a', {}) or {}
        try: rid = int(pair.get('roi_a', ser.get('roi_id', -1)))
        except Exception: rid = -1
        return ser, rid
    if cb == channel:
        ser = pair.get('series_b', {}) or {}
        try: rid = int(pair.get('roi_b', ser.get('roi_id', -1)))
        except Exception: rid = -1
        return ser, rid
    return None, -1


def _lemnis_fp_area(series):
    try:
        return np.asarray((series or {}).get('area_t', []), dtype=float).reshape(-1)
    except Exception:
        return np.zeros(0, dtype=float)


def _lemnis_fp_amp(series):
    series = series or {}
    # Newer LEMNIS exports carry explicit F/F0 and use amp_filt as its
    # compatibility field.  Prefer the explicit normalized field when present.
    for key in ('amp_ff0', 'ff0_t', 'amp_filt', 'amp_raw', 'meanint_t'):
        try:
            arr = np.asarray(series.get(key, []), dtype=float).reshape(-1)
        except Exception:
            arr = np.zeros(0, dtype=float)
        if arr.size and np.isfinite(arr).any():
            return arr
    return np.zeros(0, dtype=float)


def _lemnis_fp_first_active_from_area(area):
    area = np.asarray(area, dtype=float).reshape(-1)
    idx = np.where(np.isfinite(area) & (area > 0))[0]
    return int(idx[0]) if idx.size else None


def _lemnis_fp_n_runs(active):
    active = np.asarray(active, dtype=bool).reshape(-1)
    if active.size == 0 or not np.any(active):
        return 0
    return int(np.sum(active & np.concatenate(([True], ~active[:-1]))))


def _lemnis_fp_disp_len2d(series, active_times=None):
    try:
        coords = np.asarray((series or {}).get('coords', []), dtype=float)
    except Exception:
        return np.nan
    if coords.size == 0:
        return np.nan
    if coords.ndim == 1:
        if coords.size % 4 != 0:
            return np.nan
        coords = coords.reshape(-1, 4)
    if coords.ndim != 2 or coords.shape[1] < 4:
        return np.nan
    coords = coords[:, :4]
    finite = np.all(np.isfinite(coords), axis=1)
    coords = coords[finite]
    if coords.size == 0:
        return np.nan
    if active_times is not None:
        at = np.asarray(active_times, dtype=int).reshape(-1)
        if at.size:
            coords = coords[np.isin(coords[:, 0].astype(int), at)]
    if coords.size == 0:
        return np.nan
    times = coords[:, 0].astype(int)
    t0 = int(np.min(times)); t1 = int(np.max(times))
    c0 = coords[times == t0]
    c1 = coords[times == t1]
    if c0.size == 0 or c1.size == 0:
        return np.nan
    y0 = float(np.mean(c0[:, 2])); x0 = float(np.mean(c0[:, 3]))
    y1 = float(np.mean(c1[:, 2])); x1 = float(np.mean(c1[:, 3]))
    return float(np.hypot(x1 - x0, y1 - y0))


def _lemnis_fp_pair_latency(pair, trigger_ch, response_ch):
    trig, _ = _lemnis_fp_pair_series(pair, trigger_ch)
    resp, _ = _lemnis_fp_pair_series(pair, response_ch)
    if trig is None or resp is None:
        return np.nan
    t0 = _lemnis_fp_first_active_from_area(_lemnis_fp_area(trig))
    if t0 is None:
        return np.nan
    ra = _lemnis_fp_area(resp)
    if ra.size == 0:
        return np.nan
    idx = np.where(np.isfinite(ra) & (ra > 0) & (np.arange(ra.size) >= int(t0)))[0]
    if idx.size == 0:
        return np.nan
    return float(int(idx[0]) - int(t0))


def _lemnis_fp_temporal_summary(data, channel, role='response'):
    data = data if isinstance(data, dict) else {}
    pairs = list(data.get('intersect_report_pairs', []) or [])
    meta = data.get('metadata', {}) or {}
    role = str(role).strip().lower()
    try:
        T = int((meta.get('shape_TZYX', (0, 0, 0, 0)) or (0, 0, 0, 0))[0] or 0)
    except Exception:
        T = 0
    if T <= 0:
        for pair in pairs:
            ser, _ = _lemnis_fp_pair_series(pair, channel)
            if ser is not None:
                T = max(T, len(_lemnis_fp_area(ser)), len(_lemnis_fp_amp(ser)))
    T = max(1, int(T))

    lifetimes = []
    max_areas = []
    amp_ranges = []
    duties = []
    runs = []
    first_times = []
    disps = []
    roi_ids = []
    seen_trigger_rois = set()
    n_pair_events = 0

    for pair in pairs:
        ser, rid = _lemnis_fp_pair_series(pair, channel)
        if ser is None:
            continue
        # A trigger ROI may overlap more than one response ROI.  Count it once
        # when describing the trigger population.  Response windows remain
        # pair-specific because causal censoring can differ by trigger onset.
        if role == 'trigger' and rid >= 0:
            if rid in seen_trigger_rois:
                continue
            seen_trigger_rois.add(rid)
        n_pair_events += 1
        if rid >= 0:
            roi_ids.append(int(rid))

        area = _lemnis_fp_area(ser)
        if area.size < T:
            tmp = np.zeros(T, dtype=float)
            tmp[:area.size] = area
            area = tmp
        elif area.size > T:
            area = area[:T]
        active = np.isfinite(area) & (area > 0)
        active_idx = np.where(active)[0]
        lifetime = int(active_idx.size)
        first_t = int(active_idx[0]) if active_idx.size else np.nan
        max_area = float(np.nanmax(area[active])) if active_idx.size else 0.0
        duty = float(lifetime) / float(T)
        nruns = _lemnis_fp_n_runs(active)

        amp = _lemnis_fp_amp(ser)
        if amp.size:
            use_idx = active_idx[active_idx < amp.size]
            vals = amp[use_idx] if use_idx.size else amp
            vals = vals[np.isfinite(vals)]
            amp_range = float(np.max(vals) - np.min(vals)) if vals.size else 0.0
        else:
            amp_range = 0.0

        disp = _lemnis_fp_disp_len2d(ser, active_times=active_idx)
        lifetimes.append(float(lifetime))
        max_areas.append(float(max_area))
        amp_ranges.append(float(amp_range))
        duties.append(float(duty))
        runs.append(float(nruns))
        if np.isfinite(first_t):
            first_times.append(float(first_t))
        if np.isfinite(disp):
            disps.append(float(disp))

    unique_rois = len(set(roi_ids)) if roi_ids else int(n_pair_events)

    def _mean(vals):
        vals = np.asarray(vals, dtype=float)
        return float(np.nanmean(vals)) if vals.size else 0.0
    def _median(vals):
        vals = np.asarray(vals, dtype=float)
        return float(np.nanmedian(vals)) if vals.size else 0.0

    return {
        'n_rois': int(unique_rois),
        'n_pair_events': int(n_pair_events),
        'roi_density_per_frame': float(unique_rois / float(T)),
        'mean_lifetime': _mean(lifetimes),
        'median_lifetime': _median(lifetimes),
        'mean_max_area': _mean(max_areas),
        'median_max_area': _median(max_areas),
        'mean_amp_range': _mean(amp_ranges),
        'median_amp_range': _median(amp_ranges),
        'mean_duty_cycle': _mean(duties),
        'mean_n_active_runs': _mean(runs),
        'mean_first_time': _mean(first_times),
        'mean_disp_len2d': _mean(disps),
        'median_disp_len2d': _median(disps),
    }


def _lemnis_fp_pair_summary(data, trigger_ch, response_ch):
    pairs = list((data or {}).get('intersect_report_pairs', []) or [])
    overlaps = []
    latencies = []
    for pair in pairs:
        try:
            v = float(pair.get('overlap_voxels', np.nan))
            if np.isfinite(v): overlaps.append(v)
        except Exception:
            pass
        lat = _lemnis_fp_pair_latency(pair, trigger_ch, response_ch)
        if np.isfinite(lat): latencies.append(float(lat))
    return {
        'n_pairs': int(len(pairs)),
        'mean_overlap_voxels': float(np.mean(overlaps)) if overlaps else 0.0,
        'median_overlap_voxels': float(np.median(overlaps)) if overlaps else 0.0,
        'mean_response_latency_frames': float(np.mean(latencies)) if latencies else 0.0,
        'median_response_latency_frames': float(np.median(latencies)) if latencies else 0.0,
    }


def _lemnis_fp_from_intersect_data(data, source_mode='Response'):
    if not isinstance(data, dict):
        return None, {}
    pairs = list(data.get('intersect_report_pairs', []) or [])
    if not pairs:
        return None, {}
    trigger_ch, response_ch, chans = _lemnis_fp_pair_channels(data)
    mode = str(source_mode or 'Response').strip().lower()
    if mode not in ('trigger', 'response', 'both'):
        mode = 'response'
    pair_fp = _lemnis_fp_pair_summary(data, trigger_ch, response_ch)
    info = {
        'mode': mode,
        'trigger_channel': int(trigger_ch),
        'response_channel': int(response_ch),
        'channels': list(chans),
        'n_pairs': int(len(pairs)),
    }
    if mode == 'trigger':
        fp = _lemnis_fp_temporal_summary(data, trigger_ch, role='trigger')
        fp.update(pair_fp)
        return fp, info
    if mode == 'response':
        fp = _lemnis_fp_temporal_summary(data, response_ch, role='response')
        fp.update(pair_fp)
        return fp, info

    trig = _lemnis_fp_temporal_summary(data, trigger_ch, role='trigger')
    resp = _lemnis_fp_temporal_summary(data, response_ch, role='response')
    fp = dict(pair_fp)
    for key, value in trig.items():
        fp['trigger_' + str(key)] = value
    for key, value in resp.items():
        fp['response_' + str(key)] = value
    return fp, info


_LEMNIS_MF_PREV_LOAD_RECORD_SOURCE = _load_fingerprint_record

def _lemnis_mf_load_record_with_source(path, source_mode='Response'):
    rec = _LEMNIS_MF_PREV_LOAD_RECORD_SOURCE(path)
    if str(rec.get('kind', 'sample')).lower() == 'meta':
        return rec
    try:
        with open(path, 'rb') as f:
            data = pkl.load(f)
    except Exception:
        return rec
    fp, info = _lemnis_fp_from_intersect_data(data, source_mode=source_mode)
    if fp is None:
        return rec
    rec['fingerprint_original_export'] = dict(rec.get('fingerprint', {}) or {})
    rec['fingerprint'] = dict(fp)
    rec['fingerprint_source'] = str(info.get('mode', source_mode)).lower()
    rec['fingerprint_trigger_channel'] = int(info.get('trigger_channel', 0))
    rec['fingerprint_response_channel'] = int(info.get('response_channel', 1))
    rec['fingerprint_pair_count'] = int(info.get('n_pairs', 0))
    rec['is_intersect_pair_fingerprint'] = True
    md = dict(rec.get('metadata', {}) or {})
    md['fingerprint_source'] = rec['fingerprint_source']
    md['fingerprint_trigger_channel'] = rec['fingerprint_trigger_channel']
    md['fingerprint_response_channel'] = rec['fingerprint_response_channel']
    md['fingerprint_pair_count'] = rec['fingerprint_pair_count']
    rec['metadata'] = md
    return rec


_LEMNIS_MF_PREV_INIT_SOURCE = MultiFingerprintDialog.__init__

def _lemnis_mf_init_source(self, parent=None):
    _LEMNIS_MF_PREV_INIT_SOURCE(self, parent)
    row = QtWidgets.QHBoxLayout()
    row.addWidget(QtWidgets.QLabel('Fingerprint source for intersect .p:'))
    self.cmb_lemnis_fingerprint_source = QtWidgets.QComboBox()
    self.cmb_lemnis_fingerprint_source.addItems(['Trigger', 'Response', 'Both'])
    self.cmb_lemnis_fingerprint_source.setCurrentText('Response')
    self.cmb_lemnis_fingerprint_source.setToolTip(
        'For intersect pickles: Trigger fingerprints the trigger-channel ROI series; '
        'Response fingerprints the causally filtered response-channel series; Both '
        'stores trigger_* and response_* features in one sample fingerprint. '
        'Ordinary single-channel pickles are unchanged.'
    )
    row.addWidget(self.cmb_lemnis_fingerprint_source)
    self.lbl_lemnis_fingerprint_source = QtWidgets.QLabel(
        'Response is recommended for particle-triggered Ca²⁺ experiments.'
    )
    row.addWidget(self.lbl_lemnis_fingerprint_source)
    row.addStretch(1)
    try:
        self.layout().insertLayout(1, row)
    except Exception:
        self.layout().addLayout(row)
    self.cmb_lemnis_fingerprint_source.currentTextChanged.connect(
        lambda *_: _lemnis_mf_rebuild_intersect_records(self)
    )

MultiFingerprintDialog.__init__ = _lemnis_mf_init_source


def _lemnis_mf_rebuild_intersect_records(self):
    if not hasattr(self, 'cmb_lemnis_fingerprint_source'):
        return
    mode = str(self.cmb_lemnis_fingerprint_source.currentText() or 'Response')
    changed = False
    rebuilt = []
    for rec in list(getattr(self, 'records', []) or []):
        path = str(rec.get('path', '') or '')
        if str(rec.get('kind', 'sample')).lower() == 'meta' or not rec.get('is_intersect_pair_fingerprint', False):
            rebuilt.append(rec)
            continue
        if not path or path == '(current session)' or not os.path.isfile(path):
            rebuilt.append(rec)
            continue
        keep_label = str(rec.get('label', ''))
        keep_condition = str(rec.get('condition', ''))
        keep_enabled = bool(rec.get('enabled', True))
        try:
            new_rec = _lemnis_mf_load_record_with_source(path, mode)
            new_rec['label'] = keep_label or new_rec.get('label', Path(path).stem)
            new_rec['condition'] = keep_condition
            new_rec['enabled'] = keep_enabled
            new_rec['kind'] = str(rec.get('kind', new_rec.get('kind', 'sample')) or 'sample')
            rebuilt.append(new_rec)
            changed = True
        except Exception:
            rebuilt.append(rec)
    if changed:
        self.records = rebuilt
        self.refresh_views()


def _lemnis_mf_load_files_source(self):
    paths, _ = QtWidgets.QFileDialog.getOpenFileNames(
        self,
        'Select exported combined pickles or fingerprint dictionaries',
        '',
        'Pickle (*.p *.pkl);;All files (*)'
    )
    if not paths:
        return
    mode = 'Response'
    try:
        mode = str(self.cmb_lemnis_fingerprint_source.currentText() or 'Response')
    except Exception:
        pass
    loaded = 0
    failed = []
    for path in paths:
        try:
            rec = _lemnis_mf_load_record_with_source(path, mode)
            rec['enabled'] = True
            rec['kind'] = str(rec.get('kind', 'sample') or 'sample')
            self.records.append(rec)
            if rec['kind'].lower() == 'meta':
                self.last_meta_profile = dict(rec.get('meta_profile', {}) or {})
            loaded += 1
        except Exception as e:
            failed.append(f'{Path(path).name}: {e}')
    self.refresh_views()
    if failed:
        QtWidgets.QMessageBox.warning(
            self,
            'Fingerprint workspace',
            f'Loaded {loaded} file(s).\n\nFailed:\n' + '\n'.join(failed[:12])
        )

MultiFingerprintDialog.load_files = _lemnis_mf_load_files_source


_LEMNIS_MF_PREV_RECORD_TYPE_SOURCE = MultiFingerprintDialog._record_type_text

def _lemnis_mf_record_type_source(self, rec):
    base = _LEMNIS_MF_PREV_RECORD_TYPE_SOURCE(self, rec)
    if str(rec.get('kind', 'sample')).lower() == 'meta':
        return base
    if not rec.get('is_intersect_pair_fingerprint', False):
        return base
    mode = str(rec.get('fingerprint_source', '')).lower()
    tc = rec.get('fingerprint_trigger_channel', '?')
    rc = rec.get('fingerprint_response_channel', '?')
    if mode == 'trigger':
        return f'sample · trigger Ch{tc}'
    if mode == 'response':
        return f'sample · response Ch{rc}'
    if mode == 'both':
        return f'sample · both Ch{tc}→Ch{rc}'
    return base

MultiFingerprintDialog._record_type_text = _lemnis_mf_record_type_source
# --- END PATCH: LEMNIS INTERSECT FINGERPRINT SOURCE ---


# --- BEGIN PATCH: INPUT PARAMETER TEXT LOG ---
# Narrow reproducibility addition only: capture the settings actually used by the
# existing filter / threshold / ROI Source Builder steps and write a human-readable
# companion text file named from the input image whenever exports are written.

def _s8_paramlog_bool(widget, default=False):
    try:
        return bool(widget.isChecked())
    except Exception:
        return bool(default)


def _s8_paramlog_text(widget, default=''):
    try:
        return str(widget.currentText())
    except Exception:
        return str(default)


def _s8_paramlog_value(widget, default=None):
    try:
        return widget.value()
    except Exception:
        return default


def _s8_paramlog_channel_data(widget, default=0):
    try:
        val = widget.currentData()
        return int(default if val is None else val)
    except Exception:
        return int(default)


def _s8_paramlog_active_state(panel, ch=None):
    try:
        if ch is None:
            ch = int(getattr(panel, 'current_channel', 0) or 0)
        if hasattr(panel, '_get_channel_state'):
            st = panel._get_channel_state(int(ch))
            if isinstance(st, dict):
                return st
        states = getattr(panel, 'channel_states', {}) or {}
        st = states.get(int(ch), {})
        if isinstance(st, dict):
            return st
    except Exception:
        pass
    return {}


def _s8_paramlog_filter_settings(panel, ch=None):
    st = _s8_paramlog_active_state(panel, ch)
    try:
        img = st.get('img', None)
        T = int(img.shape[0]) if img is not None else int(getattr(panel, 'T', 0) or 0)
    except Exception:
        T = int(getattr(panel, 'T', 0) or 0)
    win_req = int(_s8_paramlog_value(getattr(panel, 'spin_win', None), 49) or 49)
    try:
        win_norm = int(_normalize_savgol_window(win_req, T)) if T else int(win_req)
    except Exception:
        win_norm = int(win_req)
    return {
        'temporal_savgol_enabled': _s8_paramlog_bool(getattr(panel, 'chk_savgol', None), False),
        'savgol_window_requested': int(win_req),
        'savgol_window_applied': int(win_norm),
        'savgol_polynomial_order': 3,
        'background_subtract_min_per_zyx': _s8_paramlog_bool(getattr(panel, 'chk_bg', None), False),
    }


def _s8_paramlog_threshold_settings(panel):
    method = _s8_paramlog_text(getattr(panel, 'method', None), '')
    return {
        'spatial_blur_enabled': _s8_paramlog_bool(getattr(panel, 'chk_spatial', None), False),
        'spatial_blur_sigma': float(_s8_paramlog_value(getattr(panel, 'spin_sigma', None), 0.0) or 0.0),
        'noise_gate_enabled': _s8_paramlog_bool(getattr(panel, 'chk_gate', None), False),
        'threshold_method': method,
        'manual_threshold': float(_s8_paramlog_value(getattr(panel, 'spin_manual_threshold', None), 0.0) or 0.0),
    }


def _s8_paramlog_roi_builder_snapshot(dialog):
    panel = getattr(dialog, 'pipeline', None)
    default_ch = int(getattr(panel, 'current_channel', 0) or 0) if panel is not None else 0
    preset = _s8_paramlog_text(getattr(dialog, 'cmb_roi_source_preset', None), 'Generic objects')
    structure_ch = _s8_paramlog_channel_data(getattr(dialog, 'cmb_structure_ch', None), default_ch)
    signal_ch = _s8_paramlog_channel_data(getattr(dialog, 'cmb_signal_ch', None), default_ch)
    target_ch = signal_ch if preset == 'Signal activity' else structure_ch
    snap = {
        'roi_source_preset': preset,
        'output_domain': _s8_paramlog_text(getattr(dialog, 'cmb_output_domain', None), 'Resolved mask'),
        'structure_type': _s8_paramlog_text(getattr(dialog, 'cmb_structure', None), ''),
        'resolver_mode': _s8_paramlog_text(getattr(dialog, 'cmb_mode', None), ''),
        'structure_channel': int(structure_ch),
        'structure_source': _s8_paramlog_text(getattr(dialog, 'cmb_structure_source', None), ''),
        'signal_channel': int(signal_ch),
        'signal_source': _s8_paramlog_text(getattr(dialog, 'cmb_signal_source', None), ''),
        'time_projection': _s8_paramlog_text(getattr(dialog, 'cmb_projection', None), ''),
        'threshold_method': _s8_paramlog_text(getattr(dialog, 'cmb_threshold', None), ''),
        'manual_threshold': float(_s8_paramlog_value(getattr(dialog, 'spin_manual', None), 0.0) or 0.0),
        'spatial_blur_enabled': _s8_paramlog_bool(getattr(dialog, 'chk_rsb_spatial', None), True),
        'preblur_sigma': float(_s8_paramlog_value(getattr(dialog, 'spin_sigma', None), 0.0) or 0.0),
        'noise_gate_enabled': _s8_paramlog_bool(getattr(dialog, 'chk_rsb_noise_gate', None), False),
        'min_object_or_spike_voxels': int(_s8_paramlog_value(getattr(dialog, 'spin_min_size', None), 1) or 1),
        'watershed_peak_distance': int(_s8_paramlog_value(getattr(dialog, 'spin_peak_dist', None), 3) or 3),
        'min_terminal_branch_length': int(_s8_paramlog_value(getattr(dialog, 'spin_spike_len', None), 7) or 7),
        'signal_proximity_radius': int(_s8_paramlog_value(getattr(dialog, 'spin_proximity', None), 0) or 0),
        'signal_gate_enabled': _s8_paramlog_bool(getattr(dialog, 'chk_signal_gate', None), False),
        'signal_gate_relation': _s8_paramlog_text(getattr(dialog, 'cmb_gate_relation', None), ''),
        'signal_gate_threshold_method': _s8_paramlog_text(getattr(dialog, 'cmb_gate_threshold', None), ''),
        'signal_gate_manual_threshold': float(_s8_paramlog_value(getattr(dialog, 'spin_gate_manual', None), 0.0) or 0.0),
        'parallel_dynamic_resolving': _s8_paramlog_bool(getattr(dialog, 'chk_rsb_parallel', None), True),
        'parallel_workers': int(_s8_paramlog_value(getattr(dialog, 'spin_rsb_workers', None), 1) or 1),
        'ram_saver_uint16_display_labels': _s8_paramlog_bool(getattr(dialog, 'chk_rsb_uint16_labels', None), True),
        'store_detailed_object_rows_for_csv': _s8_paramlog_bool(getattr(dialog, 'chk_rsb_detail_rows', None), False),
        'step3_uses_active_roi_source_mask': True,
    }
    return int(target_ch), snap


def _s8_paramlog_format_value(value):
    if isinstance(value, bool):
        return 'True' if value else 'False'
    if value is None:
        return 'None'
    if isinstance(value, float):
        return f'{value:.8g}'
    return str(value)


def _s8_paramlog_write_mapping(lines, mapping, indent='  '):
    if not isinstance(mapping, dict):
        lines.append(indent + _s8_paramlog_format_value(mapping))
        return
    for key in sorted(mapping.keys(), key=lambda x: str(x)):
        value = mapping[key]
        label = str(key).replace('_', ' ')
        if isinstance(value, dict):
            lines.append(f'{indent}{label}:')
            _s8_paramlog_write_mapping(lines, value, indent + '  ')
        elif isinstance(value, (list, tuple)):
            if len(value) <= 20 and all(not isinstance(v, (dict, list, tuple, np.ndarray)) for v in value):
                lines.append(f'{indent}{label}: ' + ', '.join(_s8_paramlog_format_value(v) for v in value))
            else:
                lines.append(f'{indent}{label}: [{len(value)} values]')
        elif isinstance(value, np.ndarray):
            lines.append(f'{indent}{label}: array shape={tuple(int(v) for v in value.shape)}, dtype={value.dtype}')
        else:
            lines.append(f'{indent}{label}: {_s8_paramlog_format_value(value)}')


def _s8_collect_input_parameter_text(panel):
    src = _s8_live_input_path_for_manifest(panel)
    input_name = Path(str(src)).name if src else '(unknown input)'
    lines = [
        's∞ INPUT PARAMETERS',
        '===================',
        f'Input file: {str(src) if src else "(unknown)"}',
        f'Input filename: {input_name}',
        '',
    ]
    try:
        cal = getattr(panel, 's8_calibration', None) or globals().get('_S8_LAST_IMAGE_CALIBRATION', None)
        if isinstance(cal, dict):
            lines.append('Calibration / input metadata:')
            _s8_paramlog_write_mapping(lines, cal, '  ')
            lines.append('')
    except Exception:
        pass

    states = getattr(panel, 'channel_states', {}) or {}
    if isinstance(states, dict) and states:
        channels = sorted(int(ch) for ch in states.keys())
    else:
        channels = [int(getattr(panel, 'current_channel', 0) or 0)]
    lines.append(f'Channels in session: {len(channels)}')
    lines.append('')

    for ch in channels:
        st = _s8_paramlog_active_state(panel, ch)
        lines.append(f'CHANNEL {ch}')
        lines.append('-' * (8 + len(str(ch))))
        try:
            img = st.get('img', None)
            if img is not None:
                lines.append(f'  input shape TZYX: {tuple(int(v) for v in img.shape)}')
        except Exception:
            pass

        filt = st.get('_s8_input_filter_parameters') if isinstance(st, dict) else None
        if not isinstance(filt, dict):
            filt = _s8_paramlog_filter_settings(panel, ch)
        lines.append('  Temporal filtering / background:')
        _s8_paramlog_write_mapping(lines, filt, '    ')

        thr = st.get('_s8_input_threshold_parameters') if isinstance(st, dict) else None
        if not isinstance(thr, dict):
            thr = _s8_paramlog_threshold_settings(panel)
        lines.append('  Native threshold / mask preprocessing:')
        _s8_paramlog_write_mapping(lines, thr, '    ')

        analysis_source = st.get('analysis_mask_source', None) if isinstance(st, dict) else None
        if analysis_source is not None:
            lines.append(f'  4D analysis mask source: {analysis_source}')

        rsb = st.get('_s8_roi_builder_input_parameters') if isinstance(st, dict) else None
        if isinstance(rsb, dict):
            lines.append('  ROI Source Builder inputs actually used:')
            _s8_paramlog_write_mapping(lines, rsb, '    ')
        else:
            rsd = st.get('roi_source_definition', None) if isinstance(st, dict) else None
            if isinstance(rsd, dict):
                lines.append('  ROI Source Builder definition:')
                _s8_paramlog_write_mapping(lines, rsd, '    ')
            else:
                lines.append('  ROI Source Builder: not used / no active builder definition recorded')
        lines.append('')

    lines.append('Notes:')
    lines.append('  - Savitzky–Golay polynomial order is fixed at 3 in this source.')
    lines.append('  - The file records parameter values only; processing behavior is unchanged.')
    return '\n'.join(lines).rstrip() + '\n'


def _s8_write_input_parameters_text(panel, output_dir):
    try:
        if not output_dir:
            return None
        os.makedirs(str(output_dir), exist_ok=True)
        stem = _s8_safe_input_stem_for_manifest(panel)
        path = os.path.join(str(output_dir), f'{stem}_parameters.txt')
        with open(path, 'w', encoding='utf-8') as f:
            f.write(_s8_collect_input_parameter_text(panel))
        return path
    except Exception as e:
        print('Input parameter text export failed:', e)
        return None


# Capture the settings at the moment the existing processing operations run.
try:
    _S8_PARAMLOG_PREV_DO_FILTER = PipelinePanel.do_filter
    def _s8_paramlog_do_filter(self, *args, **kwargs):
        ch = int(getattr(self, 'current_channel', 0) or 0)
        settings = _s8_paramlog_filter_settings(self, ch)
        out = _S8_PARAMLOG_PREV_DO_FILTER(self, *args, **kwargs)
        try:
            st = _s8_paramlog_active_state(self, ch)
            if isinstance(st, dict) and st.get('filtered') is not None:
                st['_s8_input_filter_parameters'] = dict(settings)
        except Exception:
            pass
        return out
    PipelinePanel.do_filter = _s8_paramlog_do_filter
except Exception as _e:
    print('Input parameter filter capture patch skipped:', _e)

try:
    _S8_PARAMLOG_PREV_DO_THRESHOLD = PipelinePanel.do_threshold
    def _s8_paramlog_do_threshold(self, *args, **kwargs):
        ch = int(getattr(self, 'current_channel', 0) or 0)
        settings = _s8_paramlog_threshold_settings(self)
        out = _S8_PARAMLOG_PREV_DO_THRESHOLD(self, *args, **kwargs)
        try:
            st = _s8_paramlog_active_state(self, ch)
            if isinstance(st, dict) and st.get('mask_bool') is not None:
                st['_s8_input_threshold_parameters'] = dict(settings)
        except Exception:
            pass
        return out
    PipelinePanel.do_threshold = _s8_paramlog_do_threshold
except Exception as _e:
    print('Input parameter threshold capture patch skipped:', _e)

try:
    _S8_PARAMLOG_PREV_RSB_RESOLVE = MicrodomainResolverDialog.resolve
    def _s8_paramlog_rsb_resolve(self, *args, **kwargs):
        target_ch, settings = _s8_paramlog_roi_builder_snapshot(self)
        out = _S8_PARAMLOG_PREV_RSB_RESOLVE(self, *args, **kwargs)
        try:
            st = _s8_paramlog_active_state(self.pipeline, target_ch)
            if isinstance(st, dict) and st.get('microdomain_roi_mask_bool') is not None:
                st['_s8_roi_builder_input_parameters'] = dict(settings)
        except Exception:
            pass
        return out
    MicrodomainResolverDialog.resolve = _s8_paramlog_rsb_resolve
except Exception as _e:
    print('Input parameter ROI Source Builder capture patch skipped:', _e)
